INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898032966', 'Para ensinar e aprender xadrez | Adriano Caldeira', 'Neste livro, o Mestre da Federação Internacional de Xadrez, Adriano Caldeira, ensina passo a passo detalhes desse jogo milenar que conquista e desafia mais e mais adeptos a cada dia. Com orientações claras e simples, o leitor poderá aprender desde a história e o movimento das peças até acompanhar e reproduzir partidas memoráveis de grandes enxadristas. Trata-se de um manual prático com instruções e exercícios para realmente aprender a jogar xadrez. 14x22cm', 29.9, 19.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd6u-m6txsz3y7saj09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19898032966', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
