INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19897408612', 'Bíblia de Estudo NTLH | Tamanho Grande | Couro sintético | Rosa', 'Tradução: Nova Tradução na Linguagem de Hoje Idioma: Português Tamanho da Letra: Normal Capa: Rosa Acabamento: Couro sintético Medida: 17,0 X 23,5 cm Formato: Médio Páginas: 1792 páginas Índice: Não Indicado para: Crescimento Pessoal ISBN: 7899938423561 Recurso Concordância bíblica Ensinamentos de Jesus Impressão em duas cores Introdução a cada um dos livros bíblicos Palavras que consolam e animam Pesos, moedas e medidas Quadro histórico da Bíblia Recursos Adicionais Introduções gerais aos Testamentos e suas divisões, Introduções gerais: Antigo Testamento, Pentateuco, Históricos, Sabedoria, Poéticos, Proféticos, Novo Testamentos, Evangelhos, Cartas, Mais de 14 mil notas de estudo no rodapé, Cerca de 2,2 mil notas introdutórias a cada seção, 33 tabelas e quadros temáticos diversos, 33 mapas colocados ao longo do texto, Ensinamentos de Jesus, Palavras que consolam e animam, Dicionário da NTLH', 176.9, 176.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbm2-lm2n16r61ufucd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19897408612', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898493061', 'Bíblia Sagrada NTLH | Letra Grande | Capa Dura | Azaleia', 'Na tradução Nova Tradução na Linguagem de Hoje, esta edição da Bíblia Sagrada, por seu valor acessível, é ideal para ações de evangelização.Contém um conjunto de recursos como concordância temática abreviada, cronologia bíblica, plano anual de leitura da Bíblia, palavras de orientação e consolo, entre outros, que fazem desta Bíblia uma excelente opção para o dia-a-dia. 14x21cm 1400 Páginas', 52.9, 52.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qvd4-lgg5l51qlpmuc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19898493061', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994358585', 'Livro de Colorir | Cute Kawaii | Ilustrações Adoráveis para Colorir e se Apaixonar', 'Mergulhe no universo kawaii com ilustrações superfofas para colorir!Inspirado no famoso conceito japonês de kawaii, que significa "fofo" ou "adorável", este livro é um convite irresistível para liberar a criatividade e relaxar com personagens encantadores. Ideal para todas as idades, você não precisa de nenhuma experiência para dar vida às páginas. Descubra nuvens sorridentes, gatinhos carinhosos, cactos simpáticos, monstrinhos criativos, sobremesas deliciosas, snacks irresistíveis e muito mais.Perfeito para desestressar, estimular a imaginação ou simplesmente se divertir por horas, este livro é um presente incrível ― seja para alguém especial ou para você mesmo! 24x21 cm 64 Páginas', 25.9, 16.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824g0-me2te7kl8hkzea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22994358585', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16362219404', 'Bíblia | NVI | Letra Normal | Capa Dura | Jesus Copy | Cruz', 'Atendendo a pedidos, a Bíblia Cruz é NVI - Nova Versão Internacional, a versão que se tornou muito popular entre os jovens do Brasil devido a sua linguagem de fácil compreensão. Nessa versão ela vem com capa dura feita em parceria com a Editora Thomas Nelson. Novo e Antigo testamento. Com a linguagem na versão NVI (Nova Versão Internacional). Dentre as versões bíblia ela se torna uma das mais modernas e prezervando a clareza do texto, permanecendo fiel aos Escritos originais. Incluindo panorama bíblico e mapas. 14X21CM 855 Páginas', 54.9, 49.41, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/757cb1e95ea45739fa5b2182c41d2918', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F16362219404', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794368074', 'Scottini Caça-palavras com 32 pág | N.2001 | Fácil', 'Os caça-palavras contém assuntos diversos relacionados a cultura, tecnologia, ciência, arte... A questões exercitam nosso cérebro trazendo questões da atualidade e do passado, fazendo nosso córtex trabalhar toda a área da memória. Essa dinâmica de construção traz benefícios de longo prazo, fazendo nosso cérebro rejuvenescer. 14x21cm 32 Páginas', 8.9, 3.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824jl-me2sofgfu2o49f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22794368074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18059711476', 'Homens da Palavra | Nathan Buzenitz', 'Neste livro, iremos considerar as vidas de alguns dos mais amados personagens bíblicos – homens que andaram com Deus em obediência fiel. Seremos encorajados por suas bravuras, advertidos por seus fracassos e elevados por sua fé inabalável. Qual é o chamado de Deus para os Homens? Que Virtudes Ele valoriza? O que é masculinidade bíblica e como cultivá-la? Você encontrará as respostas para essas perguntas tão importantes nas vidas de homens da Bíblia – homens como Abrãao, Davi, Neemias, Paulo e Timóteo. Cada um deste lutou com os mesmos problemas que você enfrenta hoje. Você apenderá com eles que homens de verdade... Vivem pela fé Oram com ousadia Amam adorar Lideram corajosamente Estesouram a Palavra de Deus Fogem de Tentação Recusam-se a comprometer seus princípios Encontram satisfação em Deus. Aceite o desafio de se tornar aquilo que Deus quer você seja. A palavra dele mostra o caminho. E então experimentará êxitos e bênção que só o Senhor pode dar enquanto você avança para o prêmio celestial. “Diferente de tantos outros livros para homens, nos quais a sabedoria humana substitui a instrução bíblica, Homens da Palavra olha para as Escrituras para ver o que Deus diz sobre ser um homem que honra a Ele.” John MacArthur 14x21 246 Páginas', 45.9, 45.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-22110-snwd1wmfnfjvf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F18059711476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398878408', 'Bíblia Bilíngue | Português e Inglês | NVI | Leitura Perfeita | Capa Couro-soft Caramelo', 'LEIA, ESTUDE E COMPARE AS PASSAGENS BÍBLICAS EM DUAS VERSÕES A Bíblia Bilíngue NVI/NIV apresenta, lado a lado, o texto na íntegra de duas traduções: a Nova Versão Internacional, fiel e de fácil leitura, e a New International Version, uma das versões mais vendidas do mundo. Diagramada em duas colunas, essa Bíblia permite ao leitor o contato simultâneo com o texto bíblico em português e em inglês, enriquecendo seus estudos da Palavra sem comprometer o conforto na leitura. Ela é ideal tanto para estudo pessoal como para facilitar a comunicação e interpretação entre os dois idiomas. Recursos e acabamentos: Texto em português na Nova Versão Internacional (NVI23); Texto em inglês na New International Version (NIV); Parágrafos em português e inglês sincronizados na mesma linha; Fonte Leitura Perfeita; Capa em Couro-soft (PU); Dois fitilhos; Qualidade Thomas Nelson Brasil. 17x24cm 1840 Páginas', 155.9, 155.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824i6-me6xmr9v51509f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22398878408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792955750', 'Short Adulto Feminino Speedo Ii', 'O Short Adulto Feminino Speedo I é você em destaque no dia a dia. Confeccionado em 100% poliéster, tecido próprio para corrida, com recortes em mesh. Possui internamente cadarço para regulagem e 02 bolsos laterais para pequenos objetos. É muito conforto e segurança na prática de atividades esportivas.. É muito conforto e segurança na prática de atividades esportivas. Short de corrida em tecido leve de poliéster Cordão regulador Cós anatômico Logo estilizado Gênero: Feminino Tecido: 100% Poliéster Cuidados : Não guarde a peça úmida Não use amaciantes ou produtos com alvejantes à base de cloro Evite o contato com superfícies ásperas Sua peça possui instruções específicas para lavagem, secagem e formas de passar, veja na etiqueta Cloro e bronzeadores podem manchar o produto. Após o uso, enxague bem a peça em água fria A contínua exposição à luz forte do sol e água clorada podem deteriorar alguns tipos de tecidos e cores Itens inclusos: 01 un. Short Adulto Feminino Speedo II Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 76.1, 76.1, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-7rd3p-lu52tts9abc267', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F22792955750', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397902615', 'Balcão para Cooktop 1 Porta NT 3050 Notável', 'O Balcão Cooktop NT 3050 da Notável Móveis, combina estilo com funcionalidade! Ele possui tampo para cooktop de 05 bocas, 1 gavetão com amplo espaço e corrediças telescópicas, além de uma porta com 1 prateleira interna para você organizar seus utensílios. Tem também espaço para forno micro-ondas que irá deixar tudo a mão no momento mais gostoso do dia! Características: Estrutura em MDP em 15mm 1 Nicho, suporta peso máximo de 16kg 1 Porta 1 Prateleira interna removível, suporta peso máximo de 2 kg 1 Gavetão com corrediça telescópica Dobradiça super curva 26mm Puxador em plástico VPS Dimensões: Altura: 87,20 cm Largura: 110,6 cm Profundidade: 52 cm Peso: 31,6 kg Garantia do fornecedor de 3 meses.', 389.9, 359.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdyk-m12u5k3olrpj3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F23397902615', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23601745788', 'A Arte de Pastorear | David Hansen', 'Este livro relata algumas facetas do ministério pastoral. Foi escrito com uma linguagem simples e bem criativa. É uma obra inspiradora que une teologia bíblica à prática ministerial e à espiritualidade. 14x21cm 200 Páginas', 44.9, 43.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-22100-w0mrwzf1uziv7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23601745788', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18236879911', 'Vício e Virtude: A Adicção sob uma perspectiva teológica | Kent Dunnington', 'Escolha, doença ou hábito?O que de fato é a adicção? A maior parte dos estudos científicos sobre o tema entende esse fenômeno como doença ou como escolha deliberada, mas falham em compreender a experiência dos que sofrem e daqueles que buscam ajudá-los.Em Vício e virtude, Kent Dunnington insere a filosofia e a teologia nesse debate e, com base no pensamento de Aristóteles e Tomás de Aquino, formula uma alternativa aos modelos reducionistas modernos. Para o autor, a adicção é um hábito característico dos nossos tempos e vai além do âmbito individual: pessoas com adicções severas são “profetas contemporâneos”; elas mostram quem realmente somos e iluminam aspectos dacultura moderna que tendemos a ignorar.Esta obra interdisciplinar também oferece recursos para o ministério e a igreja local, e mostra como o evangelho oferece um modo de vida alternativo e mais atraente do que a vida adicta. 272 Páginas 14x21cm', 36.9, 36.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/b9c4acddac03156c2fcee4511341f73b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F18236879911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23691724971', 'Tudo que o cristão precisa saber sobre justificação | Guy Waters', 'Tudo que o cristão precisa sobre a justificação é tudo que o cristão precisa saber para ter a verdadeira paz. De forma extremamente didática, Guy Waters utiliza seu treinamento acadêmico para mostrar ao leitor como a doutrina protestante sobre a justificação pela fé somente se baseia nas Escrituras, pode ser defendida na academia e é imensamente relevante para viver para a glória de Deus. “Guy Waters é uma preciosidade: um acadêmico sério e capaz com seus pés firmemente fincados na igreja. Esta introdução à justificação é um guia claro e com o pé no chão que dialoga com as últimas questões acadêmicas. Ao ler este livro, você terá uma boa base sobre uma das doutrinas mais importantes e sua fé será enriquecida. Se você não tem absoluta certeza sobre a forma bíblica de Deus justificar, então ler a Bíblia com este livro a mão é sua necessidade mais urgente.” Richard D. Phillips, autor Homens de verdade: o chamado de Deus para a masculinidade. 104 Páginas', 25.9, 25.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qver-liza42y6liq54a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23691724971', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794149666', 'Travesseiro Memory Foam Ergonômico Cloud Airknit Grey', 'ALMOFADA ERGONÔMICA DE ESPUMA VISCOELÁSTICA – KIKKABOODescrição do Produto A almofada ergonomicamente projetada da Kikkaboo oferece conforto e apoio essenciais para o bebê, promovendo um sono saudável e adequado posicionamento da cabeça. Fabricada com materiais suaves e de alta qualidade, é ideal para bebês de 0 a 6 meses, unindo estilo e funcionalidade. Características: Suporte Ergonômico: Confeccionada em espuma viscoelástica macia, esta almofada melhora a posição de dormir, proporcionando suporte suave para o pescoço e ajudando a prevenir a síndrome da cabeça chata. Design Multiuso: A almofada é adequada para uso na cama, no trocador, no carro ou no carrinho, garantindo o conforto do bebê em diferentes situações. Suave para a Pele do Bebê: O produto proporciona alívio para bebês com pele sensível, reduzindo a irritação nos pontos de pressão e favorecendo um sono mais repousante. Detalhes Encantadores: Apresenta um formato de nuvem divertido e detalhes bordados luxuosos, adicionando um toque fofo e elegante ao produto. Apresentação: O travesseiro ergonômico de espuma viscoelástica da Kikkaboo é oferecido em uma embalagem luxuosa, ideal para presente, sendo uma escolha perfeita para novos pais que buscam conforto e estilo para seus bebês. Dimensões: Caixa de presente: 26 x 29 x 4 cm Caixa master: 49 x 31 x 23 cm Peso bruto (G.W.): 2.7 kg', 119.9, 119.9, NULL, 'Mom & Baby > Nursery > Mattresses & Bedding', 'https://cf.shopee.com.br/file/sg-11134201-7rat0-mb2kfl3tf5g060', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1419417476%2F23794149666', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15136176843', 'Vibrador Recarregável Duplo Unissex com 12 Modos de Vibração, 2 Motores e Resistente à Água - Pretty Love Dream Lovers Whip | 65 x 3,5 cm', 'Vibrador Recarregável Duplo Unissex com 12 Modos de Vibração, 2 Motores e Resistente à Água - Pretty Love Dream Lovers Whip | 65 x 3,5 cmCódigo: 3958Dream Lovers Whip é um vibrador que parece um cordão com pontas ogivas e bulbosas. Os 2 motores que entregam 12 modos de vibração em cada lado para usar solo ou compartilhar! Uau!É um vibrador duplo e unissex, isso significa que você pode usar independente do sexo e gênero, é versátil e irá estimular diversas áreas do corpo. Não há limites para su', 319.9, 319.9, NULL, 'Health > Sexual Wellness > Sex Toys', 'https://cf.shopee.com.br/file/21e94c1a0531b08feb539843e44a5fe5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F433423094%2F15136176843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13769052135', 'Preservativo Lubrificado mais Largo - Jontex XL Lubrificado - 6 unidades', 'Preservativo Lubrificado mais Largo - Jontex XL Lubrificado - 6 unidadesCódigo: 6236O Preservativo Jontex XL veio para revolucionar a sua relação!É um preservativo masculino lubrificado, mais largo, liso, opaco com lados paralelos e reservatório! Inofensivo à saúde, seu lubrificante neutraliza o aroma do látex, proporcionando uma relação confortável, saudável e segura e vem com 6 unidades.Animou? Já coloca no carrinho!Dimensões:56 mm.Informações e recomendações:Embalagem: 6 Unidades.Composição', 19.9, 19.9, NULL, 'Health > Sexual Wellness > Condoms', 'https://cf.shopee.com.br/file/f888ad1e2ed9f139dcf978f6f85d48a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F433423094%2F13769052135', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27894237780', 'Orações para Meninos | Raquel Almeida', '“Portanto, eu lhes digo: Tudo o que vocês pedirem em oração, creiam que já receberam, e assim lhes sucederá.” Marcos 11:24. Com o Orações para Meninos, o momento da oração será ainda mais gratificante. As mensagens de Deus chegarão ao coração pelas lindas mensagens e cores de cada página. E mais: “Vamos orar” é um convite a você e a toda turma para expressar seu amor ao Criador. 23x23 cm 36 Páginas', 24.9, 19.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-825zk-mkojs3aqfklg9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F27894237780', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397390177', 'Shampoo Anticaspa Principia AC-01', 'Shampoo anticaspa intensivo com 13% de Mix de Tensoativos + 2% de Ácido Salicílico + 1% Piroctona Olamina + 1% PCA Zinco, com alta eficácia na redução da caspa persistente, oleosidade e coceira do couro cabeludo. INDICAÇÕES Principais »Aliviar a coceira »Controlar a oleosidade »Reduzir caspas »Remover impurezas Complementares »Aumentar o brilho »Proporcionar maciez »Reduzir o frizz Tipos de cabelo »Todos INGREDIENTES ATIVOS ZINCO PCA Uma associação de Zinco e L-PCA. O Zinco ajuda a normalizar a secreção sebácea e reduzir a proliferação de bactérias que podem causar acne, enquanto o L-PCA contribui em processos que promovem a hidratação da pele. ÁCIDO SALICÍLICO Beta-hidroxiácido com propriedades antibacterianas e antifúngicas, promove a esfoliação do estrato córneo, removendo células mortas, controlando a oleosidade e inibindo a incidência de acnes e cravos. Sua ação queratolítica também aumenta a permeabilidade da pele à outros ingredientes ativos. TENSOATIVOS Substâncias com capacidade de degradar e emulsificar gorduras e óleos, e suspender partículas sólidas, facilitando sua remoção com água, são amplamente utilizados em formulações para limpeza da pele. Existem vários tipos de tensoativos, sendo normalmente classificados como catiônicos, aniônicos, não-iônicos e anfóteros, em função das características dos íons que podem ser gerados quando essas substâncias estão em solução aquosa. PIROCTONA OLAMINA Substância com alta eficácia contra bactérias e fungos inclusive os relacionados a ocorrência de caspa, irritação e coceira do couro cabeludo. MODO DE USO » Use diariamente » Aplique no couro cabeludo e cabelos úmidos, massageando delicadamente, deixe agir por 2 minutos e enxague » Evite contato com os olhos » Em caso de contato acidental com os olhos, enxague abundantemente » Mantenha fora do alcance de crianças » Não use em crianças DÚVIDAS FREQUENTES Contém parabenos, petrolatos e sulfatos? Sua composição não contém parabenos, petrolatos, corantes, silicones, nem glúten. Contém sulfato. Está regularizada na Anvisa? Sim, conforme o processo número 25351.842478/2023-55. Foi testada em animais? Não. A PRINCIPIA não realiza testes em animais. Qual o prazo de validade? Três anos, contados da data de fabricação. Pode ser usada junto com outras fórmulas? Sim. Praticamente não há restrições para uso conjunto com outros ativos.', 75.99, 74.48, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-maejjusmsyrdc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373261329%2F22397390177', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252060597', 'Pistola Airsoft VG Desert Eagle V30 Mola 6,0 + BBS + Óleo', 'A Pistola de Airsoft VG Desert Eagle Silver V30 Mola 6,0mm, da Rossi, combina design robusto e desempenho eficiente. Com velocidade de 150 FPS (45 m/s com bbs 0.20g) e funcionamento por mola, ela oferece uma experiência realista a operadores que buscam qualidade e custo-benefício. Seu grip texturizado garante firmeza e segurança no manuseio, enquanto o cão funcional proporciona um aspecto autêntico e desafiador. Além disso, conta com magazine para até 12 bb’s, permitindo múltiplos disparos sem necessidade de recarregar. As miras fixas em polímero facilitam a visualização de alvos em distâncias maiores, aumentando a precisão. Para quem busca uma pistola spring diferenciada e de alta resistência, a VG Desert Eagle Silver V30 é a escolha ideal. Ficha Técnica:- Marca: Rossi- Modelo: Desert Eagle V30- Cor: Silver- Calibre: 6mm- Modo de Ação: Spring (Mola)- Plataforma: Desert Eagle- Material: Polímero- Grip: Liso- Cão: Funcional- Trava de Segurança: Manual- Velocidade: 150 FPS - 45 m/s (com bbs 0.20g)- Capacidade do Magazine: 12 bb’s- Alça e Massa de Mira: Sim- Modo de Disparo: Repetição Manual- Tipo de Munição: BBs (Esferas Plásticas)- Comprimento do Cano: 130mm- Peso: 284g- Comprimento Total: 234mmItens Inclusos: 1x Pistola de Airsoft VG Desert Eagle Silver V30 Mola 6,0mm - Rossi, 1x Pacote de BBS com 1.000, 1x Óleo de Silicone, 1x Magazine para 12 bb’s, 1x Manual de Instruções. ATENÇÃO: Nos combos que acompanham capa, esta não comporta a luneta acoplada à carabina, somente desmontadas.', 184.18, 184.18, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-822yp-mic3a9hv26fac6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F58252060597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197718005', 'Kit 4 Gelatinas Salon Line Todecacho Melão + Melancia + Maracujá + Uva 550g', 'A Gelatina Salon Line Todecacho Kids é ideal para o cuidado diário dos crespinhos, cachinhos e ondinhas. Com efeito condicionante e desembaraçante, deixa o momento do cuidado com os fios muito mais leve e divertido. Sua fórmula proporciona definição e hidratação para auxiliar no dia a dia, mantendo os fios brilhantes, saudáveis e com frizz controlado. Além disso, garante cachinhos hidratados, volumosos e com fixação flexível. Contém filtro solar e é dermatologicamente testada. O Kit Contém: - 1 Gelatina Salon Line Todecacho Kids Antifrizz Melão 550g; - 1 Gelatina Salon Line Todecacho Melancia Kids 550g; - 1 Gelatina Modeladora Salon Line Todecacho Uva Kids 550g; - 1 Gelatina Salon Line Todecacho Kids Hidratante Maracujá 550g. Benefícios: - Fixação suave para penteados duradouros; - Cachinhos sem frizz ; - Dermatologicamente testada; - Hidratação intensa; - Fios com muito brilho e mega macios. Modo de usar: Com os cabelos limpos e úmidos, aplique a gelatina mecha a mecha, uniformemente, no comprimento e pontas. Desembarace os fios com um pente de dentes largos e, em seguida, amasse-os, iniciando o movimento das pontas até a raiz. Repita o movimento quantas vezes forem necessárias. Não enxágue. Sobre a marca: Salon Line, uma das maiores fabricantes de cosméticos do Brasil, acompanha a evolução da mulher brasileira há mais de 15 anos. Toda essa vivência faz da empresa uma profunda conhecedora do universo feminino. A Salon Line está sempre investindo em novas tecnologias e produtos para oferecer o que há de melhor no segmento cosmético mundial. Empresa 100% Nacional, tem como objetivo especializar-se na beleza das mulheres brasileiras, desenvolvendo produtos de alta tecnologia e valorizando todas as belezas.', 124.15, 91.96, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-82592-mqhxgpcyek8yc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22197718005', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197713843', 'Gelatina Capilar Widi Care Modelando a Jubinha 300ml', 'A Gelatina Capilar Widi Care Modelando a Jubinha 300ml chegou para definir ainda mais as curvas dos cabelos. Com seu poder de super definição, hidrata sem ressecar, oferecendo um efeito duradouro. Perfeita para manter os cabelos livres e bem modelados. Este produto é hipoalergênico e dermatologicamente testado, além de oferecer proteção térmica e filtro solar, garantindo segurança e cuidado para os fios. Benefícios - Definição dos cachos; - Proteção térmica; - Hipoalergênico e dermatologicamente testado. Modo de usar: Aplique a gelatina capilar nos cabelos úmidos, distribuindo uniformemente da raiz às pontas. Modele os cachos conforme desejado e deixe secar naturalmente ou use um difusor para um resultado ainda mais definido. Sobre a marca: A Widi Care é reconhecida por criar produtos inovadores e de alta qualidade que atendem às necessidades específicas dos cabelos cacheados, crespos e crespíssimos. Utilizando uma combinação de tecnologia avançada e ingredientes naturais, a marca oferece soluções eficazes que destacam a beleza natural dos cabelos. Os resultados excepcionais conquistam a confiança dos consumidores, tornando-a uma referência no cuidado capilar.', 43.07, 43.07, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-8262c-mkv5a6hsj6kj36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23197713843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
