INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893624119', 'Creme Clareador para Olhos - Eye Cream - Creamy Skincare - 15G', 'O que é? O Eye Cream oferece um tratamento completo para a área dos olhos, pois atua em todos os pontos de cuidado para a região: Hidrata profundamente, estimula a síntese de colágeno e ácido hialurônico para maior firmeza da pele (diminuindo rugas e linhas finas), ameniza a hiperpigmentação causada pelo excesso de melanina e estimula a microcirculação da região, diminuindo bolsas e olheiras. Traz a moderna cafeína vetorizada por silício, que potencializa os efeitos da cafeína em melhorar bolsas e olheiras enquanto repõe o silício da pele, um nutriente fundamental para a produção de colágeno e ácido hialurônico.', 157.35, 125.87, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfbiizd7zyfb69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1304513381%2F23893624119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
