INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698217409', 'Sintra Fast Vonixx Produto Para Limpar Painel e Plásticos Limpeza Interna Automotiva Oferta Premium', 'Sintra Fast – Multilimpador Flotador Universal Bactericida e Germicida – Vonixx 🧼🚗 O Sintra Fast Vonixx é um multilimpador flotador universal, bactericida e germicida, com pH balanceado, desenvolvido para a limpeza completa do interior automotivo. Indicado para painéis, laterais e cantos de portas, bancos de couro, carpetes e estofados, oferece alto poder de remoção de gorduras e sujeiras pesadas, além de eliminar microrganismos causadores de doenças 🦠❌ Reduz significativamente os maus odores, deixando o interior do veículo mais limpo, saudável e livre de impurezas ✨ 🧽 Indicações de Uso: 🧴 Limpeza de painéis 🚪 Laterais e cantos de portas 🪑 Bancos de couro 🧵 Carpetes e estofados 🛠️ Modo de Uso Painéis, laterais, cantos de portas e bancos de couro: 1️⃣ Pulverize o produto diretamente na superfície a ser limpa e desinfetada 2️⃣ Utilize pincel, escova macia ou aplicador de espuma, realizando movimentos circulares até o desprendimento da sujeira 3️⃣ Remova o excesso com uma toalha de microfibra levemente úmida 4️⃣ Seque em seguida com uma toalha de microfibra seca ⭐ Benefícios ✨ Alto poder de limpeza 🦠 Ação bactericida e germicida ⚖️ pH balanceado 👃 Reduz maus odores 🚗 Ideal para limpeza interna automotiva', 34.9, 34.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mki7ygjsdo8z85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F22698217409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193890738', 'Tampa De Vidro Temperado Avulsa 26 Cm Diâmetro', 'Seu design moderno e incrivelmente elegante não apenas enriquece a estética, mas também simplifica a preparação dos alimentos. A transparência do vidro permite observar o cozimento dos alimentos, enquanto a estrutura de aço inox proporciona durabilidade e resistência excepcionais. Essa tampa de vidro não apenas adiciona um toque de sofisticação à sua cozinha, mas também é altamente prática. Veja abaixo as especificações técnicas: Descrição Produto. Dimensões: 26 cm de diâmetro Compatibilidade: Panelas numeradas 26 cm Material do puxador: Baquelite Cor do puxador: Preto Embalagem: Saco plástico / Caixa parda Estamos a disposição.', 28.9, 28.9, NULL, 'Home & Living > Kitchenware > Pans', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m80fboemxoflf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379103154%2F22193890738', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494056583', 'Cabo de Dados Ugreen Us288 Usb 2.0 p Usb Tipo C 2m Preto', 'Cabo de Dados Ugreen US288 USB 2.0 para USB-C – 2 Metros, Transferência Rápida e Durabilidade - 60128 1. Transferência de Dados Confiável O cabo Ugreen US288 USB 2.0 para USB-C oferece velocidades de até 480Mbps, permitindo sincronização eficiente de arquivos, fotos, vídeos e documentos com segurança e rapidez. 2. Carregamento Seguro e Estável Além de transferência de dados, o cabo suporta carregamento rápido e estável, protegendo seus dispositivos contra sobrecargas e garantindo energia eficiente para smartphones, tablets e outros acessórios. 3. Comprimento de 2 Metros para Maior Flexibilidade Com 2 metros de extensão, o cabo proporciona maior liberdade de uso, permitindo conectar dispositivos em locais mais distantes, seja em casa, no trabalho ou em viagens. 4. Design Durável e Resistente Fabricado com materiais de alta qualidade, o cabo é projetado para resistir ao desgaste diário. Seu design reforçado evita danos causados por dobras e torções, garantindo longa vida útil. 5. Compatibilidade Universal e Garantia de Confiança Compatível com dispositivos USB-C, como smartphones, tablets, notebooks e acessórios, o Ugreen US288 é a solução prática e confiável para o dia a dia. Garantia de 90 dias.', 78.54, 78.54, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/br-11134275-7r98o-ma1m2k6skt8i91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163359442%2F23494056583', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
