INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799022075', 'Kit Iluminação Led TV Govee Backlight 3 Lite 75 a 85 pol', 'LED Iluminação RGBIC Govee Backlight 3 Lite p/TVs De 75 a 85 Pol, Sincronização De Cores Com Tela Via Câmera, Controle Por App Govee Home, Compatível Com Alexa E Google Assistant 1. Govee TV Backlight 3 Lite H60993D2: iluminação LED RGBIC para TV de 75 a 85 polegadas, criando luz ambiente imersiva e personalizável para sala, home theater e setup gamer. 2. Sincronização de cores com a tela via câmera externa: captura as bordas da imagem e ajusta as fitas em tempo real, com efeitos dinâmicos ideais para filmes, séries e jogos, além de cenas prontas no app Govee Home. 3. Controle inteligente e por voz: ajuste brilho, cores, modos e temporizadores pelo aplicativo; compatível com Alexa e Google Assistant para comandos simples e automação do backlight da TV. 4. RGBIC com segmentos independentes: múltiplas zonas de cor na mesma fita para transições suaves e efeitos addressable, oferecendo visual moderno e luz de fundo sem incidir diretamente na tela. 5. Instalação fácil em TVs grandes: fitas adesivas e acessórios de fixação inclusos, cabos otimizados e central de controle compacta. Backlight para TV 75–85 pol que eleva a imersão e o estilo do seu ambiente. Garantia 90 dias', 960.63, 960.63, NULL, 'Mobile & Gadgets > Accessories > USB & Mobile Lights', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mfofnnxrypdx05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163359442%2F22799022075', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
