INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29743144915', 'Tesoura Para Cortar Grama com Cabo Giratório VONDER', '***PRODUTO A PRONTO ENTREGA COM ENVIO IMEDIATO*** PRODUTO ORIGINAL COM NOTA FISCAL Conteúdo da Embalagem: 1 Tesoura para cortar grama. Leve, prática e de fácil manuseio. Possui cabo plástico com revestimento emborrachado e botão trava das lâminas, para maior segurança e fácil armazenamento com a lâmina fechada. Conta ainda com cabeça giratória 360° para uso em diversas posições. Indicada para acabamento em jardins, canteiros e gramados, para aparar cantos onde o cortador de grama não alcança. Pode também cortar pequenos arbustos. Garantia legal: 90 dias Detalhes Técnicos Comprimento da lâmina:150 mm Material do cabo da tesoura para cortar grama:Plástico Comprimento total:360 mm Massa aproximada (peso):0.25 kg', 107.9, 88.9, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mg04v1d09mvi4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F29743144915', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
