INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997115888', 'Correia Poly V Ford F1000 1994 a 1998 - 137573 - 6PK2050', 'Correia Poly V Ford F1000 1994 a 1998 137573 6PK2050 Motor 4.9 12v - (Alternador / Bomba D''água / Direção Hidráulica / Ar Condicionado) As correias Multi V permitem a transmissão não positiva de binários. A sua função: O acionamento do alternador, ventoinha, bomba de água, compressor do ar condicionado e direção assistida nos motores modernos. As correias Multi V estão sujeitas a envelhecimento e desgaste. Por essa razão, têm de ser controladas e substituídas a intervalos regulares. Os intervalos de controle e de substituição são sempre estabelecidos pelo fabricante do veículo e devem ser respeitados.', 155.82, 155.82, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbmw-lmqh68fvnqpx51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23997115888', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18798946745', 'Papete Sandália Infantil Plugt Menina De Fibras Naturais Confortável - Azul Marinho', 'A sandália Papete BoraBora da Plugt, é aquela sandália MACIA, VEGANA, ESTILOSA, LINDA E SUSTENTÁVEL!! Com fibras naturais em sua composição de COCO E BAMBU, ela é aquele modelinho completo onde o conforto, a praticidade, a modernidade e a segurança caminham juntos para o dia-a-dia dos nossos pequenos. Além de todas essas qualidades, ele ainda vem com um cheirinho natural das fibras, aquele aroma de coco como sentir a praia em seus pés! A febre das papetes continua conquistando novos pés a cada dia. Perfeita para acompanhar a energia dos pequenos. Estilo, palmilha flexível com tecnologia ARTEC, com dupla regulagem que abraça o pezinho garantindo segurança para os pequenos e uma diversidade de cores para diferentes estilos. Comprimento da Palmilha em CM: (medida do dedão ao calcanhar) 20 = 19/20 - 13,3 cm 22 = 21/22 - 14,6 cm 24 = 23/24 - 16 cm 26 = 25/26 - 17,3 cm --------------------------------------------------------------------------------- SOBRE NÓS: A Plugt é uma empresa há mais de 20 anos especialista em fabricação de calçados infantis injetados. Os nossos produtos são: - Leves, flexíveis e confortáveis; - Com solado antiderrapante; - Livres de FTALATOS (aceito em toda Europa); - Fácil de lavar; - Macio; - Sustentável, Vegano e Reciclável. Com design ECO e um toque de BRASILIDADE, esse produto possui FIBRA DE COCO E BAMBU, que agrega valores de responsabilidade ambiental, um processo amigo do meio ambiente. Sempre nos inspiramos no poder da imaginação das crianças para criar produtos divertidos e coloridos assim como a Plugt é!, sem deixar de lado o conforto, a praticidade de calce e a facilidade em lavar que as mamães amam!', 89.9, 49.9, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m03dytzf177h54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F284865829%2F18798946745', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492784387', 'Corrente de Comando Riffel BIZ 125 06> / PCX 150 14-20 / NEO', 'DESCRIÇÃO: CORRENTE DE COMANDO RIFFEL. APLICAÇÃO: BIZ 125 (06-23) / PCX 150 (14-20) / AKT 125 DINAMIC / AX 100-4T / BEST 125 / ELITE 125 (18-22) / NEO 125 (16-22) (0404SS - 92L). FABRICANTE: RIFFEL CÓDIGO DO PRODUTO: M405 - Tratamento termoquímico para maior resistência - Resistência à oxidação - Marcação do sentido de instação da corrente - Alta resitência à fadiga e tração - Garantia de qualidade Riffel e tecnologia das peças originais - Aplicada para motocicletas de baixa e média cilindrada A corrente de comando é confeccionada em aço de alta resistência para garantir uma resposta mais suave e reduzir o atrito com outras peças. Além disso, sua tecnologia japonesa proporciona mais durabilidade e precisão para oferecer um alto desempenho. De alta qualidade e tecnologia, a Riffel garante!', 40.0, 40.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbly-lpwg4tgigc7y81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F912455413%2F22492784387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
