INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18297692816', 'Pneu Barum By Continental 175/70r14 88t Xl Bravuris 5hm', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Pneu Barum By Continental Aro 14 175/70R14 88T XL Bravuris 5HM O Bravuris 5HM é um pneu desenvolvido pela Barum, pertencente ao grupo Continental, oferecendo um desempenho excepcional para motoristas exigentes. Sua construção focada na durabilidade e eficiência proporciona uma experiência de direção segura e confortável. Com alta aderência e baixa resistência ao rolamento, esse pneu é ideal para quem busca não apenas segurança, mas também economia. A combinação de tecnologia avançada e materiais de qualidade fazem deste pneu uma escolha inteligente para veículos de passeio. Desempenho superior: O modelo Bravuris 5HM oferece excelente tração em diferentes condições climáticas. Eficiência energética: A baixa resistência ao rolamento favorece a economia de combustível durante as viagens. Conforto acústico: Equipado com tecnologia que minimiza o ruído, proporcionando uma condução mais tranquila. Estabilidade em altas velocidades: Sua estrutura reforçada garante segurança e controle mesmo em altas velocidades. Classificação XL: Ideal para motoristas que precisam de um pneu com capacidade de carga adicional sem perder desempenho. Largura da Secção: 175 mm Perfil: 70% da largura Aro: 14 polegadas Índice de Carga: 88 (560 kg por pneu) Índice de Velocidade: T (até 190 km/h)', 479.9, 476.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rbm3-lmnm6mlwdf7v43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1197031273%2F18297692816', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
