INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193274797', 'Almofada SafeDream 2 em 1 Grey - Safety 1 St', '*Almofada para carrinho compatível com moisés SafeDream Safety 1st O ninho que transforma qualquer assento de carrinho em um confortável e aconchegante moisés. Laterais altas com zíper, removíveis, para uso também como colchonete. A almofada redutora Safedream é o acessório ideal para todos os assentos de carrinho terem o sonhado formato de um moisés, deixando o bebê mais protegido, para uso desde recém-nascido. -Acessório 2 em 1: pode ser utilizado como moisés ou como colchonete em carrinhos -Lateral elevada com zíper para fácil remoção -Aberturas universais para a passagem dos cintos -Tiras e fivelas de fixação laterais para maior segurança -Feito em algodão, trazendo o máximo de conforto para o seu bebê -Totalmente lavável, facilitando a limpeza (lavável à mão) Especificações: Compatibilidade: Moisés SafeDream Medidas: 33 x 75 x 18 Peso: 0,830g Material: Revestimento 96% Algodão 4% Elastano Conteúdo da embalagem: 1 Almofada Garantia: 12 Meses', 329.98, 329.98, NULL, 'Mom & Baby > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdw2-lzusod3iw8av25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207408200%2F22193274797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
