INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199368681', 'CONDUITE DE FREIO E CÂMBIO ESPIRAL COM TEFLON ROLO 20MTS PRETO BICICLETA BIKE', 'CONDUITE ESPIRAL PRETO ROLO COM 20 METROS TEFLONADO. SEJA BEM-VINDO(A) AO NOSSO CANAL DE VENDAS DE PEÇAS E BICICLETAS! NOSSO OBJETIVO É GARANTIR A SATISFAÇÃO DOS NOSSOS CLIENTES E NOSSA MISSÃO É OFERECER UM ATENDIMENTO DE QUALIDADE, COM PROFISSIONALISMO E DEDICAÇÃO EM TODAS AS ETAPAS DA COMPRA. TRABALHAMOS PARA PROPORCIONAR A VOCÊ UMA EXPERIÊNCIA DE COMPRA EXCEPCIONAL, COM UMA AMPLA SELEÇÃO DE BICICLETAS, ACESSÓRIOS E PEÇAS PARA TODOS OS CICLISTAS, DESDE INICIANTES ATÉ PROFISSIONAIS. CONTEM: 20 METROS ESPESSURA: 4.5MM COR: PRETO PARA USO EM CABO DE FREIOS E OU CABO DE CAMBIO COMPOSIÇÃO: AÇO, TEFLON E PVC MARCA: GTS AGUARDAMOS A SUA COMPRA, DESPACHAMOS O MAIS RÁPIDO POSSÍVEL!', 28.79, 28.79, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-8261t-mk3wv6cbr407c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22199368681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23092965162', 'Cebolinha Temperatura OPALA 1980/1992 - 39717 - 3025', 'Cebolinha Temperatura OPALA 1980/1992 (DIPLOMATA) 2.5 (151 - 4CIL.) /4.1 (250/S - 69CIL.) ÁLC./GAS. Cebolinha de temperatura ou Sensor Temperatura - Informa com precisão para o painel do veículo, como para o computador da injeção eletrônica o valor exato dessa temperatura, para evitar imprevistos e grandes prejuízos. Veículos mais novos aciona a ventoinha no lugar do Interruptor Térmico e a partida a frio nos veículos Flex. É possível encontrar o sensor de temperatura no cabeçote, ou seja, a parte mais quente do motor e onde a temperatura pode ser medida com uma precisão mais assertiva.', 63.59, 63.59, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd4a-lub96hxm3grqe7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23092965162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698180579', 'Roda Calha Traseira Raio 4mm Cromado Fan 125 2009 Em Diante Com Relação Pneu', 'Roda Traseira (Montada, Alinhada e Balanceada) Especificações: Modelo Compatível: Honda Cg Fan 125 Cilindradas Compatíveis: 125 Posição da Roda: Traseira Anos de Fabricação: 2009 Em Diante Características Técnicas: Aro: Pro Tork Raio: 4mm Cromado Cubo: Fabreck/Unibreq Sistema de Freio: Á Tambor ( Marca Instalada Conforme Disponibilidade no Estoque ) Pneu: Pneu Pro Tork Montado Na Roda Dimensões e Material: Material do Aro: Aço Estrutura de roda: De Raios Medidas do Aro: 18inches Incluso: Rolamentos + Lona + Espaçador + Espelho + Relação Sendo líder de mercado, os cubos de roda Fabreck são confeccionados em liga de alumínio especial e com pintura no padrão da original, além de serem produzidos em modernos equipamentos de usinagem, proporcionam grande durabilidade e resistência do produto. Conservação Os cuidados para conservação do cromo, tanto no seu aspecto quanto na prevenção contra a oxidação, devem considerar a limpeza frequente com água e sabão neutro aplicados com pano ou esponja macia. A montagem e desmontagem do pneu deve ser realizada por profissional experiente e com equipamento adequado. Nunca utilize materiais abrasivos ou produtos químicos para limpeza.', 659.9, 593.91, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5ubwt124nn675', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1421013142%2F23698180579', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
