INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093273618', 'Par Amortecedor Traseiro Original Kayaba New Civic G8 2007 2008 2009 2010 2011', 'Seja Bem-vindo(a)!! É um prazer imenso tê-lo em nosso anuncio. Abaixo algumas informações sobre o Produto e Aplicação. Por fim, conheça um pouco mais sobre a nossa loja. Produtos: 1 Amortecedor Traseiro Lado Esquerdo 1 Amortecedor Traseiro Lado Direito Marcas: Kayaba Aplicação: Veiculo: Civic G8 Ano: 2007 2008 2009 2010 2011 Garantia: 90 dias. É novo, e acompanha nota fiscal Sim! Todos nossos produtos são novos acompanhados de nota fiscal. Sobre a Loja: Somos uma empresa que trabalha exclusivamente com o setor de peças para veículos leves e médios, sendo eles nacionais ou importados. Oferecemos peças com qualidade, prazo de entrega, parcerias com as melhores marcas e eficiência no atendimento. Temos uma equipe de profissionais qualificados para orientar o cliente nas suas mais variadas necessidades relacionadas à manutenção do seu veículo. Oferecemos também um amplo estoque de peças e envios diários. Visamos constantemente o aperfeiçoamento e melhoria dos serviços para a satisfação total do cliente. ATENÇÃO Para garantia de AMORTECEDORES, só serão aceitas mediante apresentação do certificado enviado junto ao produto. Sem esse documento, não será possível efetuar a garantia do produto. Em caso do não recebimento do certificado, favor nos enviar assim que receber a mercadoria e notar a ausência.', 546.9, 546.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rdwb-m01mi7mqap8p1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373135807%2F23093273618', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599501388', 'Kit Amend Cosméticos Valorize Ultra Forte (6 Unidades)', 'Kit com sprays fixadores para todos os tipos de cabelos. Amend Valorize Hair Spray Ultra Forte oferece fios no lugar e com efeito duradouro, sem pesar, com realce de brilho. O Kit Amend Valorize Hair Spray Ultra Forte apresenta sprays fixadores formulados com silicones, para proteger os fios da umidade no dia a dia. Além disso, o design com jato seco não deixa resíduos no cabelo e permite um visual de alta fixação com mais naturalidade. Contém: Amend Valorize Ultra Forte - Spray Fixador 6x400ml Como Usar: ﻿ Agite bem antes de usar. Vaporize de modo contínuo e uniforme no cabelo seco ou levemente úmido à uma distância aproximada de 15-20 cm. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 221.4, 221.4, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-823rl-moohw4455q0y1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F22599501388', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11102519608', 'Máscara Facial Hidratante Vitamina C Bisnaga PhálleBeauty PH0052', 'A Máscara Facial Hidratante da PhálleBeauty é rica em Vitamina C possui função múltipla e de alta performance de hidratação. Seu cuidado começa com os benefícios promovidos pelas frutas cítricas e na suavidade proporcionada pelo toque seco. - Refrescante; - Tonificante; - Toque seco. Modo de usar: Com as mãos limpas e secas aplique uniformemente no rosto fazendo movimentos circulares do centro para o exterior até completa absorção. Não é necessário enxaguar.', 13.99, 13.99, NULL, 'Beauty > Skincare > Face Mask & Packs', 'https://cf.shopee.com.br/file/b8f11fe7537038fe2c0ef240bb07d936', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F11102519608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203149256', 'La Roche-Posay Pure Vitamin C12 Oil Control - Sérum Facial Redutor de Linhas 30ml', 'Sérum facial redutor de linhas para peles mistas à oleosas. La Roche-Posay Pure Vitamin C12 Oil Control é ideal para deixar a pele revigorada e com aparência mais jovem. O Sérum Facial La Roche-Posay Pure Vitamin C12 Oil Control conta com uma composição única que traz uma textura suave, não oleosa e que confere uma sensação de frescor. Além disso, ajuda na redução de rugas, deixando a tez com as aspecto mais saudável e renovado. Experimente! Como Usar: Aplique no rosto após a limpeza pela manhã e/ou à noite. Evite o contorno dos olhos. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 329.9, 329.9, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/sg-11134201-825zs-mjejsw0c4umdd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58203149256', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
