INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297747025', 'Kit 3 Desinfetante para Uso Geral Lysoform Original 2L cada', 'O Kit contém: 3 Desinfetantes para Uso Geral Lysoform Original com 2L cada. Lysoform Desinfetante Líquido é um desinfetante confiável, que mata 99,9% dos germes, bactérias e fungos. A marca mais recomendada por médicos para desinfetar sua casa, para que você possa aproveitar todos os momentos sem preocupações.', 98.59, 98.59, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rd66-lwq5uat7yyydab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819102498%2F21297747025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18048641025', 'Painel de Natal Fundo Decoração Natalina Cenário Árvore de Presentes para Fotos Em Tecido Sublimado', 'Todos os nossos Fundos Fotográficos Sublimados são confeccionados em tecido especial, com excelente acabamento e imagens nítidas que possibilitam fotos incríveis sem reflexos no resultado final. Por serem muito práticos, os fundos podem ser utilizados em estruturas como tripés (presos por garras) ou fixado em paredes e até mesmo placas de MDF com o auxílio de fita crepe ou dupla face (de formato largo, preferencialmente). Características: Tecido: Malha (estica e não amassa) Composição: 95% Poliéster + 5% elastano Gramatura: 140g m² Acabamento: Pode ser em overloque ou à laser, à depender da demanda. Ambos com acabamento perfeito que garantem sua durabilidade. ** Itens inclusos: 1 fundo fotográfico em tecido Malha ** Indicação de uso: Produção de fotos em estúdio fotográfico Informação complementar: As cores podem variar nas fotografias devido à qualidade da câmera fotográfica, ajustes/configurações da câmera, lente e iluminação do ambiente. Além disso, as configurações brilho e contraste do monitor ou celular onde a imagem está sendo visualizada, também podem dar a impressão das cores serem mais ou menos vivas, mais ou menos intensas. ** Todos os nossos produtos passam pelo processo de sublimação, sendo uma etapa onde passam por uma temperatura muito alta, podendo ter uma pequena variação em seu tamanho de até 5cm.** Nossos fundos fotográficos têm uma qualidade incomparável e é simplesmente incrível! Nosso tecido é maravilhoso, proporciona um toque suave e sem marcas de dobras, as cores são bem vivas e a nitidez da resolução incrível. Praticidade e economia de espaço, podem ser lavados, dobrados, guardados e é só esticar e arrasar nas fotografias. Possui acabamento impecável, não desbota e o caimento é perfeito! Uma combinação de qualidades especiais.', 139.9, 52.8, NULL, 'Cameras & Drones > Camera Accessories > Lighting & Studio Equipments', 'https://cf.shopee.com.br/file/395910a95a97d9eb3d58f6f3313a3422', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F776725570%2F18048641025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
