INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18364859281', 'Kit 2 Repelente Super Repelex Aerosol com 200ml', 'REPELENTE REPELEX FAMILY CARE AEROSOL Longa Duração. Repelex é super prático e conveniente para toda a família para proteção de insetos. Protege por até 6 horas, não oleoso e é dermatologicamente testado. Repelex aerosol tem ação refrescante e adequado para uso de dia e de noite. Fácil aplicação. Modo de Usar: Aplique Super Repelex Aerosol nas partes expostas do corpo com movimentos suaves e circulares. Caso seja necessário espalhe uniformemente com as mãos. Não aplique em excesso. Evite inalação e proteja os olhos durante aplicação.', 53.58, 53.58, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-823pl-mojkk9s5isxs48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18364859281', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
