INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597135678', 'Kit Desodorante Aerosol Bozzano Sem Perfume 90g - 12 unidades', 'O Desodorante Aerosol Bozzano Sem Perfume cuidadosamente desenvolvido para atender as necessidades masculinas, promove proteção antitranspirante por 24 horas, garantindo maior segurança, mantendo a pele saudável e livre de possíveis odores da transpiração corporal. Bozzano Sem Perfume é perfeito para pessoas que querem proteção altamente eficaz livre de perfume. Modo de usar: Agite antes de usar. Pulverizar a 15 cm de distância da região onde for aplicado. Em caso de entupimento da válvula remova o botão plástico e lave-o com água quente. Sobre a marca: Bozzano é a única marca brasileira que cuida dos homens desde 1946. Só uma marca 100% brasileira e masculina poderia oferecer uma linha completa de produtos que atende todas as necessidades do homem deixando ele pronto para enfrentar seu dia-a-dia.', 145.64, 113.88, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-824gl-mpi0t8fwizgt08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F23597135678', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21496914108', 'Teologia de John Wesley | Kenneth J. Collins | Cpad', 'A intrincada síntese teológica elaborada com esmero por Wesley reúne boa parte do grande projeto de sua carreira teológica, a saber, a tarefa de articular o lema de “só a fé” com a prática da “vida santa”.Nesta obra, o autor, um especialista no pensamento wesleyano, analisa sua teologia sob três prismas: os próprios escritos de Wesley, a crítica histórica e a crítica teológica.Mergulhe nesta profunda e consistente articulação sobre o amor santo e a forma da graça, presentes na teologia de John Wesley. Detalhes do Produto: Autor: Kenneth J. Collins Editora: Cpad Acabamento: Brochura Dimensões: 22,5 alt. X 14,5 larg. Número de páginas: 448', 52.99, 52.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qveh-lgfkiqeupcemf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F21496914108', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
