INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998218696', 'Verniz Tingidor Montana 18 Litros Acetinado Castanho e Imbuia', 'COMPRE APENAS 1 UNIDADE POR VEZ 30KG É O LIMITE DE PESO, E NÃO NOS PERMITE O ENVIO DE 2 OU MAIS PRODUTOS Verniz Premium Tingidor Base Solvente •Acetinado Para onde serve: Verniz Tingidor Premium é um verniz que além de proporcionar cor, protege a madeira contra as intempéries naturais, exposição à chuva e luz solar direta. Ideal para madeiras novas e para restauração. Onde usar: A aplicação do Verniz Tingidor Premium é indicada para dar cor às madeiras novas, renovar e impermeabilizar superfícies de madeira aplainadas, lixadas ou rústicas (portas, portões, janelas, beirais, forros e estruturas de telhado). Por que usa • Fácil aplicação; • Secagem rápida; • Ótimo alastramento; • Duplo filtro solar; • Resistência a intempéries. Versões: Quatro opções de cores: Castanho Imbuia Mogno Ipê Rendimento: Até 80 m² / 18 L / acabado', 837.26, 586.09, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mchpc9y479c124', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F23998218696', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
