INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23999001642', 'CHAVEIROS DIVERSOS OFICIAL PALMEIRAS OURO', 'CHAVEIRO OFICIAL PALMEIRAS – MODELO CHUTEIRA OU BOLA DOURADO Demonstre sua paixão pelo Verdão em todos os detalhes com este chaveiro oficial do Palmeiras. Produzido em metal com acabamento dourado de alta qualidade, o acessório une estilo, resistência e um visual sofisticado inspirado no universo do futebol. Disponível em dois modelos: • Bola de futebol com escudo do Palmeiras em destaque • Chuteira com acabamento detalhado e elegante Ideal para usar nas chaves, mochila, estojo ou até mesmo como item decorativo, o chaveiro é perfeito para torcedores que querem carregar a identidade do clube no dia a dia. DESTAQUES DO PRODUTO: • Produto oficial licenciado • Acabamento premium em metal dourado • Detalhes em verde com escudo do Palmeiras • Alta durabilidade e excelente acabamento • Possui argola metálica resistente PERFEITO PARA: • Torcedores do Palmeiras • Presentear amigos e familiares palmeirenses • Uso no dia a dia com estilo e praticidade • Colecionadores de produtos oficiais INFORMAÇÕES IMPORTANTES: • Venda unitária • Modelos vendidos separadamente • Produto enviado na embalagem oficial Leve a tradição e a grandeza do Palmeiras com você em qualquer lugar.', 21.9, 21.9, NULL, 'Hobbies & Collections > Souvenirs > Keychains', 'https://cf.shopee.com.br/file/br-11134207-820m6-mo03uj3olibk48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1561205436%2F23999001642', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
