INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698363787', 'Camiseta Masculina Penalty Futebol Max', 'A Camiseta Masculina Penalty Futebol Max foi projetada para atletas que exigem o máximo desempenho. Confeccionada em tecido de malha 100% poliéster, ela oferece leveza e respirabilidade excepcionais, mantendo eu seco e confortável do primeiro ao último minuto. Benefícios: Secagem Rápida. Liberdade de Movimento. Conforto e Leveza. Respirabilidade. Alguns diferenciais técnicos: A Camiseta Masculina Penalty Futebol Max possui recortes laterais e gola em contraste, que garantem um visual moderno e dinâmico, enquanto o logo da Penalty no peito exibe sua paixão pelo esporte. Com modelagem regular, esta Camiseta Masculina proporciona um ajuste perfeito e liberdade total de movimentos, permitindo que você se concentre no que realmente importa, a vitória. Além de garantir versatilidade, ideal para futebol, treinos e outras atividades esportivas.', 79.99, 79.99, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-7rd68-m7v37c0t1sdt84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F22698363787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
