INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597681074', 'GABINETE DE VIDRO SAN MARINO 60CM AC VERMELHO CEREJA', 'Os vidros são pintados com tinta de alta performance, o que lhe garante a permanência da cor original. Dados Técnicos Itens Inclusos: - Bancada de vidro com furo para instalação da torneira (3,5cm diâmetro) e da válvula click (4,5cm diâmetro) - Cuba de vidro - Espelho - Estrutura de polipropileno cinza, ultra resistente a umidade e não enferruja - kit parafusos completo para instalação - Prateleira de vidro da bancada - Válvula click Dimensões: - Bancada de Vidro: 60 x 45cm (largura x profundidade) - Cuba de vidro: 39x32cm (largura x comprimento) - Prateleira bancada: 60 x 20cm (largura x profundidade) - Espelho: 60 x 45cm (largura x altura) - Porta Toalha: 60cm (largura) - Válvula: 1" 1/4 Espessuras: - Bancada de Vidro: 8mm - Cuba de Vidro: 8mm - Espelho: 3mm - Prateleira da bancada: 5mm Garantia: 12 meses (conforme política de troca e devoluções). Atenção: Preço referente somente ao gabinete, não acompanha torneira. Montagem: Montagem e instalação não inclusa na venda ou preço do produto, elas são de inteira responsabilidade do cliente. * Imagens Ilustrativas.', 549.0, 549.0, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134211-7r98o-lv2iau2s5acp54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1146529360%2F21597681074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208127275', 'Leite de Coco TP - Mais Coco 1L', 'O leite de coco Mais Coco é perfeito para incrementar pratos doces e salgados, dando um toque exótico e delicioso em seus pratos.', 25.9, 25.9, NULL, 'Food & Beverages > Cooking Essentials > Others', 'https://cf.shopee.com.br/file/br-11134207-820lm-mmkfiueo7u2u23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895528519%2F58208127275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499727277', 'Condicionador Ocean Tech Ocean Guard Aquario Marinho 50ml', 'OceanTech OceanGuard • Remove cloro e cloramina da água da torneira, tornando-a segura para os peixes • Neutraliza a amônia, um composto altamente tóxico para os organismos aquáticos • Contém componentes que ajudam a formar uma camada protetora na mucosa dos peixes OceanGuard OceanTech é um condicionador de água seguro e eficaz que neutraliza instantaneamente o cloro tóxico, cloraminas e metais pesados encontrados na água da torneira. Além disso, fornece substâncias que ajudam na mucosa protetora natural dos peixes, perdida devido ao estresse, manuseio de coleta ou baixa qualidade de água. Possui em sua composição Aloe Vera e Vitamina E que auxiliam na redução do estresse dos peixes. Recomendado para aquários de água doce e salgada, seu uso deve ser feito desde a montagem inicial, bem como na manutenção periódica e reposição da água de evaporação. Como Usar: Use 2 gotas para cada 1 L ou 1 mL para cada 10 L. Para auxiliar na melhora da mucosa protetora natural dos peixes, utilize o dobro da dosagem recomendada. Você pode exceder em até 5x a dosagem com total segurança. Para melhores resultados, adicione OceanGuard OceanTech na água da torneira antes de adicioná-la ao aquário. Durante as trocas parciais, certifique-se de ajustar a temperatura e pH da água, bem como os demais parâmetros de seu aquário. Esse condicionador é indicado para todos peixes ou invertebrados ornamentais aquáticos. O mesmo não é indicado para sistemas que possuam peixes ou invertebrados aquáticos destinados ao consumo humano.', 31.88, 31.88, NULL, 'Pets > Pet Accessories > Aquarium Needs', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9lrnmxiagc90e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1470189844%2F18499727277', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
