INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22895859394', 'Tintura Alta Moda Castanho 4.0', 'A Coloração Creme Permanente Alfaparf Alta Moda oferece cor intensa, duradoura e uniforme, com cobertura perfeita dos fios brancos. Sua nova fórmula vegana, enriquecida com Ácido Hialurônico e tecnologia Metal Block, protege os cabelos contra danos causados por metais pesados, mantendo os fios hidratados, macios e sedosos durante e após a coloração. Além disso, o blend de óleos presente na composição garante brilho espelhado e toque aveludado, enquanto o filtro UV preserva a cor vibrante por mais tempo. Benefícios:Cor intensa, uniforme e de longa duração.Cobertura total dos fios brancos.Maciez, brilho e sedosidade extrema.Protege a fibra capilar com Ácido Hialurônico.Fórmula vegana com tecnologia Metal Block. Modo de usar: Siga as instruções da embalagem para preparo e aplicação. Utilize luvas durante o processo e respeite o tempo de pausa indicado. Enxágue bem e finalize com o tratamento pós-coloração. Sobre a marca: O Grupo Alfaparf está há mais de 30 anos no mercado internacional de cosméticos, atuando em 80 países e atendendo aos melhores salões do mundo. Com expertise na área capilar, o grupo iniciou sua atuação junto ao consumidor final no Brasil através da Alfaparf Cosmética Di Tratamento. Destaca-se pelo sucesso de suas linhas junto à mulher brasileira.', 17.54, 17.54, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-825ah-mqdqk53an573d8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22895859394', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
