INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993478283', 'Protetor Diário Tena Lady Discreet Flex 15 Unidades', 'Protetor Diário TENA Lady Discreet Flex é um protetor de calcinha, específico para mulheres com incontinência urinária leve. É ideal para gotejamentos e pequenos escapes de urina (espirros, risadas, ou algum escape com exercícios físicos). Indicado para usuárias ativas com mobilidade. Desenvolvido especialmente para se adaptar aos diversos tipos de calcinha, oferecendo segurança e conforto. Um protetor diário?com design anatômico, mais largo na frente e menor e mais?flexível na parte de trás. Garante total conforto num produto fino e flexível, se adaptando à todos os modelos de calcinha. Você pode escolher a roupa ideal em qualquer ocasião sem se preocupar! Seu material é de alta absorção, macio, suave e possui controle de odor. • Um protetor diário fininho; • Design anatômico exclusivo: mais largo na frente e menor e mais?flexível na parte de trás; • Ajuste perfeito para todos os tipos de calcinha; • Seu material é muito macio, confortável; • Possui controle de odor.', 15.19, 15.19, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-7rcd2-lstykja71f3jb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819145905%2F22993478283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
