INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794393820', 'Kit 2 Leite Condensado Piracanjuba 395g', 'O Leite Condensado Semidesnatado Piracanjuba é a escolha perfeita para preparar sobremesas deliciosas com leveza e cremosidade. Com 6 por cento de gordura, oferece o equilíbrio ideal entre sabor e textura, garantindo receitas irresistíveis. Ideal para bolos, pudins e outras criações, trazendo praticidade e qualidade para a sua cozinha.', 15.98, 15.98, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-82599-mqmsu5au5hxo31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23794393820', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
