INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193757818', 'Kit 3 Barra de Cereais Ritter Castanha-do-Pará com 3 Unidades de 22g Cada', 'BARRA DE CEREAIS RITTER CASTANHA-DO-PARÁ As barrinhas Ritter são preparadas com ingredientes selecionados, que você pode facilmente perceber, como flocos de aveia, milho, arroz e frutas desidratadas, numa verdadeira granola em barra. Práticas, fáceis e prontas para serem consumidas a qualquer hora, as barrinhas são ideais para quem leva uma vida dinâmica e saudável. Descubra o seu sabor preferido.', 23.67, 23.67, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/sg-11134201-8259n-mqmst0r9xf5sd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F22193757818', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27588480927', 'Aparelho de Barbear Gillette Mach3 Acqua-Grip', 'Aparelho de Barbear Gillette Mach3 Acqua-Grip Projetado para proporcionar um barbear mais rente, suave e controlado, o Gillette Mach3 Acqua-Grip é ideal para quem busca precisão e conforto no cuidado diário. Com cabo antideslizante e lâminas afiadas de longa duração, o aparelho alia segurança e eficiência, mesmo durante o uso no banho. Principais Características: - 3 lâminas com precisão de corte: Cortam cada pelo com menos passadas, reduzindo o risco de irritações e proporcionando um barbear mais rente. - Tecnologia Acqua-Grip no cabo: Cabo com revestimento emborrachado antiderrapante, que oferece controle total mesmo com as mãos molhadas. - Microtensores exclusivos: Esticam suavemente a pele antes da passagem das lâminas, garantindo um deslizamento mais eficiente e confortável. Benefícios: - Proporciona um barbear mais rente e suave - Reduz o risco de irritações e cortes - Maior controle e firmeza no uso, mesmo em ambientes úmidos - Ideal para o uso diário, com alto desempenho desde o primeiro uso Diferenciais do Produto: - Design ergonômico com Acqua-Grip, ideal para barbear no chuveiro - Compatível com todos os refis Gillette Mach3 - Lâminas duráveis, cada uma pode ser usada por até 15 vezes com desempenho ideal - Tecnologia confiável Gillette, líder mundial em cuidados com a barba Especificações Técnicas: - Peso: 54g Instruções de Uso: - Lave o rosto com água morna para suavizar os pelos. - Aplique espuma ou gel de barbear. - Deslize o aparelho suavemente no sentido do crescimento dos pelos. - Após o uso, lave o aparelho e guarde em local seco e arejado. Avisos e Precauções: - Mantenha fora do alcance de crianças. - Não utilize sobre a pele lesionada ou irritada. - Para melhor desempenho, substitua o cartucho de lâmina regularmente. O que está incluso? - 1 Aparelho de Barbear Gillette Mach3 Acqua-Grip - 1 Cartucho com 3 lâminas ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 52.29, 39.79, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcwiyirf2bzm1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F27588480927', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899256562', 'Livro de Atividades Caligrafia Divertida Disney Pixar Vogais', 'Companhia não vai faltar. Você estará com as ilustrações incríveis da turma do Mundo Pixar ao seu lado enquanto aprende! Com a Coleção Caligrafia divertida, os exercícios de apoio escolar ficarão ainda mais fáceis de concluir. Com páginas coloridas e grandes linhas para treinar, você terá tudo para ser incrível com as Vogais. A diversão é aqui, com a Bicho Esperto.', 13.9, 13.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/br-11134207-820m1-mnxb2rn30agx89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F18899256562', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55955819432', 'Retoque de Raiz L''Oréal Paris Magic Retouch - Louro Claro', 'Retoque de Raiz L''Oréal Paris Magic Retouch - Louro Claro O Magic Retouch L''Oréal Paris Louro Claro é um spray tonalizante temporário desenvolvido para disfarçar instantaneamente a raiz crescida e os fios brancos entre uma coloração e outra. Prático e de fácil aplicação, proporciona cobertura uniforme e acabamento natural em poucos segundos. Principais Características Cobertura Instantânea da Raiz Disfarça fios brancos e raiz crescida de forma rápida, com resultado visível em segundos após a aplicação. Tonalidade desenvolvida para se adaptar harmoniosamente aos cabelos loiros claros, garantindo efeito natural. Secagem Rápida e Fórmula Leve Textura leve que seca rapidamente, sem pesar nos fios e sem deixar resíduos aparentes. Benefícios Resultado imediato entre colorações Disfarce eficaz de fios brancos Aplicação prática em spray Fácil de transportar e ideal para retoques rápidos Sai com shampoo Acabamento natural e uniforme Diferenciais do Produto Tecnologia de pigmentos que se adaptam ao tom do cabelo Aplicador direcionado para maior precisão na raiz Solução temporária ideal para emergências e manutenção da cor Desenvolvido por L''Oréal Paris, referência mundial em beleza e coloração capilar Especificações Técnicas Peso: 75 ml Tipo: Spray tonalizante temporário para retoque de raiz Cor: Louro Claro Indicação: Cabelos loiros claros Instruções de Uso Agite bem antes de usar. Aplique nos cabelos secos, mantendo o spray a aproximadamente 10 a 15 cm da raiz. Pulverize levemente apenas nas áreas desejadas. Deixe secar por alguns instantes antes de tocar nos fios. O produto sai facilmente com shampoo. Avisos e Precauções Uso externo. Produto inflamável. Não aplicar sobre couro cabeludo irritado ou lesionado. Evite contato com os olhos. Em caso de contato, enxágue abundantemente com água. Manter fora do alcance de crianças. Armazenar em local fresco, ao abrigo do calor excessivo e da luz solar direta. O que está incluso? 01 Retoque de Raiz L''Oréal Paris Magic Retouch - Louro Claro ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 89.59, 73.59, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/br-11134207-81ztz-mkxyehp9ysxs09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F55955819432', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49005844135', 'Desodorante Aerosol Giovanna Baby Candy 150ml', 'Desodorante Aerosol Giovanna Baby Candy 150ml O Desodorante Aerosol Giovanna Baby Candy 150ml oferece proteção eficaz contra odores, aliado a uma fragrância doce e envolvente. Desenvolvido para proporcionar sensação prolongada de frescor, é ideal para o uso diário, garantindo conforto e perfumação suave ao longo do dia. Principais Características Proteção Contra Odores Ajuda a combater os odores da transpiração, mantendo sensação de limpeza e frescor por horas. Fragrância Candy Perfume doce, delicado e marcante na medida certa, ideal para quem gosta de aromas suaves e femininos. Fórmula Leve em Aerosol Aplicação prática, com secagem rápida e toque seco, sem deixar sensação pegajosa. Benefícios Sensação prolongada de frescor Perfume agradável e envolvente Aplicação rápida e uniforme Ideal para uso diário Não deixa resíduos aparentes nas axilas Praticidade no dia a dia Diferenciais do Produto Fragrância exclusiva da linha Candy Combinação de proteção e perfumação em um único produto Embalagem prática em aerosol Desenvolvido pela Giovanna Baby, marca reconhecida por suas fragrâncias marcantes Especificações Técnicas Peso: 150 ml Tipo: Desodorante aerosol Indicação: Uso diário Instruções de Uso Agite bem antes de usar. Aplique a uma distância aproximada de 15 cm das axilas, sobre a pele limpa e seca. Espere secar antes de se vestir. Avisos e Precauções Uso externo. Produto inflamável. Não aplicar sobre a pele irritada ou lesionada. Evite inalar diretamente o jato. Em caso de irritação, suspenda o uso. Manter fora do alcance de crianças. Conservar em local fresco, longe de fontes de calor e luz solar direta. O que está incluso? 01 Desodorante Aerosol Giovanna Baby Candy 150ml ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 28.19, 22.09, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/br-11134207-81zu4-mkxz4in6adc3a9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F49005844135', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43413431346', 'Repelente Spray SBP Mosquitos E Moscas Com 280ml', 'Principais Características: • Fórmula eficaz contra mosquitos, moscas e outros insetos voadores. • Apresentação em spray aerossol para aplicação rápida e prática. • Proteção imediata e prolongada para ambientes internos e externos. Benefícios: • Mantém o ambiente livre de mosquitos e moscas, proporcionando mais conforto e segurança. • Ideal para uso em residências, áreas de lazer e locais de convivência. • Fácil aplicação, sem necessidade de preparo ou diluição. Diferenciais do Produto: • Alta performance com ação rápida e duradoura. • Embalagem prática de 280ml, com válvula que facilita a pulverização. • Desenvolvido por marca referência em proteção contra insetos. Especificações Técnicas: • Peso: 280ml Instruções de Uso: • Agitar bem antes de usar. • Pulverizar no ambiente direcionando o jato para cima e em todas as direções. • Para melhores resultados, aplicar especialmente em áreas de maior incidência de insetos. Avisos e Precauções: • Não aplicar sobre alimentos, utensílios de cozinha, plantas ou aquários. • Manter fora do alcance de crianças e animais domésticos. • Evitar inalação direta e contato com olhos e pele. • Conservar em local fresco e ventilado, longe de fontes de calor. O que está incluso? • 1 Repelente Spray SBP Mosquitos e Moscas 280ml ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 48.29, 36.69, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdya-mdgkcymcr2zo8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F43413431346', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
