INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26120854379', 'Volante Revival Racing Volkswagen Brasília Fusca', 'Elegância e durabilidade em cada detalhe. O volante Racing Pu é a peça chave que faltava em seu clássico. Este volante combina beleza atemporal de poliuretano com a resistência incomparável do aço inoxidável. A missão da Revival é garantir o conforto ao dirigir e é indispensável para quem deseja elevar o nível de seu veículo. CONTEÚDO DA EMBALAGEM: * Volante Clássico Racing Pu; * Diâmetro 317mm; * Cubo Adaptativo com capa de metálica * Emblema * Parafusos para instalação COMPATIBILIDADES: * Volkswagen Brasília 1973 À 1976 * Volkswagen Variant 1973 À 1976 * Volkswagen Fusca 1950 À 1976 * Volkswagen Buggy grossa * Volkswagen Bugre grossa * Jeep Willys Estria Grossa EXCLUSIVIDADE * Nossos volantes de poliuretano possuem um manuseio suave e preciso, com cubos adaptativos e emblemas metálicos, garantindo a segurança de nossos clientes; * Fabricamos volantes de diversos estilos, materiais e compatibilidades para deixar seu veículo cada vez mais clássico e sofisticado; * Portanto, caso não encontre seu veículo em nossa tabela de compatibilidade, basta entrar em contato com nossa equipe de atendimento. IMPORTANTE * Certifique-se de que o anúncio seja compatível com seu veículo. Em caso de dúvida realize uma pergunta ANTES da compra; * Recomendamos que a instalação seja realizada por um profissional; * Perguntar se a geração do seu veículo é compatível com este anúncio. Eleve seu carro clássico ao próximo nível com perfeição em cada detalhe.', 999.98, 400.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rfh4-m3uz8tr32v3bf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401494968%2F26120854379