INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994233471', 'Bolsa Térmica Color Gel Dellamed', 'A Bolsa Térmica em Gel ColorGel Dellamed é perfeita para terapia quente e fria, ajudando a aliviar dores musculares, contusões e tensões do dia a dia de forma prática e segura. Diferenciais: Uso quente ou frio: ideal para aplicação em dores musculares, inflamações, contusões ou para relaxamento. Gel que não congela totalmente: mantém flexibilidade mesmo no frio, moldando-se ao corpo. Aquecimento direto no micro-ondas: sem necessidade de pano úmido ou água. Material externo em PVC: toque macio, protege a pele e é fácil de higienizar. Disponível em dois tamanhos: adapta-se a diferentes regiões do corpo. Display prático para organização em casa ou para revenda. Características: Tipos de terapia: Quente e fria. Temperatura de uso: Frio: até 10°C após 30 min. Quente: até 55°C, mínimo 40°C após 30 min. Material externo: PVC resistente e macio. Material interno: Gel (água, glicerina, carboximetilcelulose de sódio, ureia e conservantes). Flexível: molda-se ao contorno do corpo. Especificações Técnicas: Validade: 4 anos Cores: gel azul, embalagem vermelho com detalhes em preto e branco Dimensões Tamanho P: 180 ml Altura: 18cm Largura: 13cm Peso: 0,180 gramas Dimensões Tamanho M: 320 ml Altura: 25cm Largura: 12,5cm Peso: 0,320 gramas Garantia: 3 meses de garantia contra defeitos de fabricação.', 14.66, 12.9, NULL, 'Home & Living > Hand Warmers, Hot Water Bags & Ice Bags', 'https://cf.shopee.com.br/file/sg-11134201-7rdyv-mcakkst4v6354a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1557525936%2F22994233471', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
