INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498823174', 'Condicionador Dalsan Cresce Com Força 500ml', 'O Condicionador Dalsan Cresce Com Força 500ml oferece um cuidado completo e eficaz para os cabelos. Projetado para fortalecer e estimular o crescimento saudável dos fios, é uma excelente opção para quem busca cabelos fortes, longos e cheios de vitalidade. Sua fórmula exclusiva combina ingredientes de alta qualidade, cuidadosamente selecionados para fornecer os nutrientes necessários para fortalecer os fios desde a raiz até as pontas, combinando a expertise da Dalsan em cuidados capilares e os avanços tecnológicos mais recentes, este condicionador proporciona resultados visíveis e duradouros. Além disso, os benefícios vão além do fortalecimento dos fios, ele também ajuda a reduzir a quebra e a queda capilar, promovendo um ambiente saudável para o crescimento dos cabelos. Benefícios: - Auxilia no crescimento capilar; - Reduz a quebra e a queda; - Fortalece a fibra capilar; - Facilita o desembaraço. Modo de usar: Com os cabelos molhados, aplique o shampoo na raiz e massageie com movimentos circulares, espalhando bem. Enxágue e repita o processo se achar necessário. Sobre a marca: E, no início dos anos 2000, como um fio de cabelo que resiste às agressões externas e mantém-se forte, a Dalsan dava seus primeiros passos na fabricação de produtos capilares na cidade de Pindamonhagaba, interior de São Paulo. Depois de uma longa caminhada em terras paulistas, foi em Dom Silvério, uma cidade acolhedora, inspiradora e com espírito empreendedor, que escolhemos o nosso lar, fortalecendo nossas raízes familiares e nutrindo nosso empreendimento.', 80.99, 80.99, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-824gm-mpi3nrtlt6o226', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F21498823174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259234583', 'Freezer Vertical EOS 66 Litros EcoGelo Slim EFV70 220V', '🧊 Freezer Vertical EOS EcoGelo Slim 66 Litros EFV70 ✨ Compacto por fora, eficiente por dentro. O EFV70 foi desenvolvido para quem precisa de praticidade em espaços reduzidos, sem abrir mão de organização, economia e desempenho confiável no dia a dia. ✨ Destaques do Produto: ✅ Capacidade de 66 litros com excelente aproveitamento interno ✅ Design slim compacto, ideal para cozinhas pequenas e áreas reduzidas ✅ Melhor distribuição interna para organização prática dos alimentos ✅ Selo A++ e Procel de eficiência energética, com baixo consumo de energia ✅ Uso de gás ecológico, mais sustentável e amigável ao meio ambiente ✅ Funcionamento silencioso com apenas 40dB de ruído ✅ Mantém alimentos preservados por até 7,5 horas em caso de falta de energia ✅ Estrutura funcional que facilita o uso no dia a dia ✅ Organização inteligente mesmo em tamanho compacto ✅ Desempenho estável para conservação segura dos alimentos 📏 Medida (LxAxP/cm): 48 x 85 x 45 cm', 1648.91, 1648.91, NULL, 'Home Appliances > Kitchen Appliances > Freezers', 'https://cf.shopee.com.br/file/sg-11134201-820mh-mnaeguz0hudd24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1527564302%2F58259234583', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
