INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999711891', 'Escada para Cama Elástica e Pula Pula com 2 Degraus', '**Escada para Cama Elástica com 2 Degraus** Este modelo de **escada com 2 degraus** é perfeito para camas elásticas de **1,83m, 2m e 2,44m**, proporcionando praticidade e segurança para as crianças subirem e descerem do pula-pula. --- **Características do Produto:** - **Material:** Fabricada em aço galvanizado para maior durabilidade e resistência. - **Degraus:** Produzidos em plástico injetado de alta resistência, garantindo segurança e suporte adequado. - **Design prático:** Encaixe ideal para os pés das crianças, proporcionando estabilidade durante o uso. --- Ao adquirir a **Escada para Cama Elástica**, você está investindo em um produto de excelente qualidade, projetado para complementar a diversão de forma segura e confiável.', 82.8, 43.9, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-7reo2-m8p86gvps0whb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1479622710%2F20999711891', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998384353', 'Banheira Acqua Trio Galzerano p/ Bebê - Dobrável de Plástico', 'Banheira Infantil Galzerano Acqua Trio Dobrável de Plástico - Branca A Banheira Acqua Trio da Galzerano é prática, segura e funcional, ideal para o banho do bebê, promovendo conforto e facilidade para os pais. Com capacidade máxima de 20 kg (bebê + água), ela é uma excelente escolha para o dia a dia. Características do Produto: - Produto nacional com estrutura em aço resistente. - Design desmontável, garantindo praticidade e economia de espaço. - Capacidade máxima de 20 kg (bebê + água). - Função 2 em 1: o tanque pode ser utilizado tanto no suporte quanto fora dele. - Mangueira integrada para saída de água, facilitando a drenagem. - Inclui saboneteira e redutor para maior conveniência. - Pés desmontáveis que tornam a embalagem mais compacta. - Fácil desmontagem e limpeza, contribuindo para o uso prático. Certificação: - Certifique-se do prazo de garantia no manual de instruções e, em caso de dúvidas, procure uma autorizada ou entre em contato com o CRC. Essa banheira combina segurança e conforto, transformando o momento do banho em uma experiência mais agradável e relaxante para o bebê e para os pais. Se precisar de mais informações, estarei aqui para ajudar!', 354.0, 289.9, NULL, 'Mom & Baby > Bath & Body Care > Bathing Tubs & Seats', 'https://cf.shopee.com.br/file/sg-11134201-7reqd-m8kssmbh1b2xee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1479622710%2F23998384353', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
