INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297653122', 'Carregador de tomada USB Preto EC 1 Fast Intelbras', 'O EC 1 Fast é um carregador USB com saída de 2,4 A, que proporciona carregamento até 2 vezes mais rápido. Ideal para recarregar a bateria de smartphones, tablets, fones de ouvido, power banks, smartwatches, caixas de som portátil, e outros dispositivos com conexão USB. Fornece carregamento seguro, com proteção contra surtos de tensão e sobrecarga. Detalhes: - Carregador USB rápido - Saída USB-A: 5 V/2,4 A - Entrada: 100 à 240Vca 50/60Hz 0,6A máx (bivolt automático) - Possui proteção contra surtos de tensão e sobrecarga - Carrega qualquer dispositivo com conexão USB - Carregamento seguro que não vicia a bateria do produto conectado - Compatível com qualquer cabo (a utilização de cabos de má qualidade pode influenciar no desempenho de carregamento dos produtos). - Dimensões do produto sem embalagem CxLxA: 6 X 3,2 X 10 cm Código de Homologação Anatel: 05622-21-00160', 55.08, 55.08, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/sg-11134201-7reoe-m2cea2qciipn8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F23297653122', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192523581', 'Cabo micro USB PVC Branco 1,2m EUAB12PB Intelbras', 'Cabo micro USB PVC Branco 1,2m EUAB12PB - Intelbras O cabo USB para Micro USB EUAB 12PB permite a conexão de seus dispositivos para alimentação de energia e transferência de dados. Projetado e testado para garantir o melhor desempenho e durabilidade, tem 1,2 m de comprimento para oferecer maior comodidade no uso com smartphones, tablets, computadores, fones de ouvido sem fio, controles de videogame e outros dispositivos compatíveis Detalhes: - Conector 1: USB Type-A - Conector 2: USB Micro-B - Bitola do cabo: 24AWG energia / 30AWG dados - Corrente máxima: 3,0 A - Velocidade de transferência de dados: até 480 Mbps (em conformidade com o padrão USB 2.0) - Revestimento externo do cabo: Policloreto de vinila (PVC) - Capa dos conectores: Elastômero termoplástico (TPE) - Dimensão: 3,4 × 1.200 mm - Carregue e sincronize dados dos seus dispositivos - Velocidade de carregamento até 3,0 A (15 W)* - Transferência de dados até 480 Mbps - 1,2 m de comprimento - Revestimento emborrachado - Apotência e corrente podem variar de acordo com a fonte de alimentação e dispositivo conectados', 26.28, 26.28, NULL, 'Audio > Audio & Video Cables & Converters', 'https://cf.shopee.com.br/file/sg-11134201-7rbm3-lmnnyy67towb09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F22192523581', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
