INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394286368', 'Box com 6 Minilivros | Fisher-Price | Quando Estou...', 'As histórias desses livros falam sobre sentimentos e emoções presentes no dia a dia das crianças, por meio de rimas e doces ilustrações. Acompanhe seu pequeno nessa leitura e celebre o amor e o carinho em família! 24X18 CM 60 Páginas', 27.9, 24.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdyh-mcz4vbzpg3qx3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22394286368', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294014860', 'Plena: Encontrando a Plenitude em Meio aos Ciclos da Vida | Fernanda Brum', 'O que é ser plena? Muitas respostas cabem nessa pergunta. Para Fernanda Brum, a plenitude é como o Sol de meio-dia, que brilha intensamente no céu dos nossos corações. Mas, ninguém é pleno o tempo inteiro. Com o passar dos dias de nossa vida, entardecemos, anoitecemos e somos invadidas por eclipses diante das circunstâncias que ferem nossa alma.E o que fazer quando isso acontece? Como encontramos a plenitude em meio aos ciclos da vida?Neste livro, o terceiro escrito pela pastora, cantora, ministra e ganhadora de dois Grammys, Fernanda Brum revela que o caminho para se tornar plena passa por compreender os movimentos de rotação que nos atravessam e pelo entendimento de que existe um tempo cronológico e outro espiritual. A plenitude é resultado desses relógios sincronizados, que sempre vão apontar para a volta de Jesus.Por meio de histórias de vida e dos bastidores de um ministério bem-sucedido, você aprenderá que foi criada para ser uma estrela que brilha no firmamento da sociedade e será conduzida a perceber os processos de cura e restauração pelos quais Deus a guiará a fim de fazê-la viver uma vida plena. 16x23cm 144 Páginas', 41.9, 33.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfi6-m9u2bp81qm4v2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23294014860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
