INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893193750', 'Apoquel 3,6mg Zoetis para Cães – Alívio eficaz da coceira e dermatites alérgicas', 'Apoquel 3,6mg Zoetis Para Cães O Apoquel 3,6mg Zoetis Para Cães, vai trazer alivio da coceira e tranquilidade para seu cão, agindo nas primeiras 04 horas após consumo. Seguro e eficaz até mesmo nos tratamentos prolongados, e o melhor sem os indesejáveis efeitos da ciclosporina e dos corticosteroides. Indicações e benefícios: - Contém 20 comprimidos; - Alivio da coceira em 4 horas; - Uso oral somente em cães; - Pode ser utilizado em cães com mais de 1 ano de idade; - Alivia a coceira por 24 horas após uma única dose; - É seguro e eficaz em longo prazo; - Tratamento do prurido associado a dermatites alérgicas; - Manifestações clínicas de dermatites atópicas; - Odor no corpo e orelha alterado; - Perda de pelo ; - Para evitar lamber , mordiscar ou se arranhar excessivamente; - Vermelhidão na pele; Apresentação: Embalagem com 2 cartelas de 10 comprimidos cada (20 comprimidos) 3,6mg Produto Registrado no Ministério da Agricultura, Pecuária e Abastecimento sob o n 00072-8-000002 em 05/11/2015', 290.9, 222.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/sg-11134201-7rbnh-m5kgnhfpxilw45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F23893193750', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
