INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49756675377', 'Rebitador Manual Tipo Alicate 250mm Rebites 2,4-4,8mm MTX', 'Rebitador manual tipo alicate MTX, projetado para aplicação prática de rebites de fácil manuseio em trabalhos de manutenção, reparos e montagem. Compacto e ergonomicamente fabricado com 250 mm de comprimento, oferece alcance e alavancagem adequada para fixações em chapas e peças metálicas ou plásticas. Compatível com rebites nos diâmetros 2,4 mm, 3,2 mm, 4,0 mm e 4,8 mm, é uma ferramenta versátil para oficinas, uso doméstico e profissionais que precisam de uma solução portátil e resistente. Aciona rebites com precisão, sendo indicado para uma variedade de materiais e serviços rápidos. Características: Modelo: 405249 Referência: 405249 Tipo: Alicate rebitador manual Compatibilidade de rebites: 2,4 mm; 3,2 mm; 4,0 mm; 4,8 mm Comprimento: 250 mm Quantidade: 1 peça Marca: MTX Benefícios: Permite instalação rápida e precisa de rebites em diferentes diâmetros Design em formato de alicate para maior controle e conforto na operação Tamanho de 250 mm fornece boa alavancagem para reduzir esforço Versátil para uso doméstico, oficinas e trabalhos profissionais Fácil de transportar e armazenar devido ao formato compacto Conteúdo da embalagem: 1 rebitador manual tipo alicate MTX (250 mm)', 60.43, 42.41, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-82604-mlc4qz3u3l6o59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F49756675377', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
