INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22230470511', 'Batedeira Philco Paris Cristal Maxx Vermelha 400W', 'A Batedeira Philco Paris Cristal Maxx possui 400W, potência que te leva muito além na hora de cozinhar! Com 4 velocidades + botão Turbo, variação de velocidade para diferentes receitas. Oferece duas tigelas: tigela cristal 4 litros e plástico 3,1 litros, perfeitas para o preparo de grandes quantidades. Além de 2 batedores: para massas leves e clara em neve, bate bolos, pudins, mousses e outros cremes. Muito prática, pois possibilita retirar a batedeira da base para uso como portátil. Na hora de cozinhar, conte com a melhor, conte com Batedeira Philco Paris Cristal Maxx Vermelha 400W! Maior potência – 400W 4 velocidades + botão turbo 2 Tigelas plástica: Tigela cristal 4 litros e plástico 3,1 litros 2 pares de batedores em aço inox para massas leves e clara em neves Botão ejetor dos batedores Botão de articulação Unidade motora pode ser usada fora da base como portátil Espátula acoplada Peneira Tampa da tigela.', 179.9, 179.9, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/sg-11134201-823p5-mord8ajfksge54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811034337%2F22230470511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
