INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23417508546', 'Kit 2 Repelente SBP Baby Loção Corporal com Icaridina 100ml', 'REPELENTE SBP BABY LOÇÃO SEM FRAGRÂNCIA Repelente corporal no formato loção para bebês a partir de 2 meses. Fórmula suave com Icaridina e manteiga de karitê que protege por até 6 horas contra os mosquitos, incluindo o mosquito da Dengue, Zika e Chikungunya. Sem fragrância e hipoalergênico. Modo de usar: Agite bem antes de usar. Aplicar em abundância nas partes expostas do corpo somente quando necessário. Para aplicar no rosto, aplique primeiramente o produto nas mãos e a seguir leve ao rosto. Lavar as mãos com água e sabão após o uso.', 75.38, 75.38, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-823pi-mojsem8vn85q50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23417508546', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22596610970', 'Kit 4 Fralda Turma da Mônica Baby Mega Tamanho XG 42 Unidades Descartáveis', 'Fralda Infantil Turma da Mônica Baby Mega Tamanho XG A Turma da Mônica Baby uniu proteção e conforto em uma nova opção de fralda, para garantir que seu bebê cresça feliz e tenha as melhores lembranças da sua infância. A Nova fralda Turma da Mônica Baby possui a nova Tecnologia QuatroSec para que ele fique calmo, tranquilo e seguro durante o dia e a noite toda. Conta com um exclusivo sistema de canais que distribui mais rápido o xixi, barreiras anti-vazamento e uma fina camada extra que ajuda a manter o bebê sequinho por até 12 horas, além de cintura elástica que proporciona um perfeito ajuste no corpinho. A Nova fralda Turma da Mônica Baby possui a nova Tecnologia QuatroSec; com um exclusivo sistema de canais que distribui mais rápido o xixi, barreiras anti-vazamento e uma fina camada extra que ajuda a manter o bebê sequinho por até 12 horas, além de cintura elástica que proporciona um perfeito ajuste no corpinho. A Turma da Mônica Baby é uma marca de excelência no mercado de fraldas infantis há mais de 25 anos. A marca e sua turma estão presentes no coração dos brasileiros há mais de 3 gerações, e agora também faz parte do portfólio da Ontex. Os novos produtos foram pensados e elaborados para as mamães e os papais que, assim como nós, valorizam a tradição e os valores culturais aprendidos na infância, alinhado com o conforto e a qualidade dos produtos Turma da Mônica para seu bebê. Modo de uso: 1. Coloque o bebê sobre a fralda aberta com as fitas na parte traseira. 2. Abra as fitas agarradinhas e ajuste a fralda no corpinho do bebê posicionando as fitas sobre a faixa frontal branca.', 191.96, 191.96, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-824im-mpq8napgri1adb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F22596610970', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
