INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18297298892', 'Cubo De Roda Traseira Pop 100 110 Com Rolamentos Lonas e Raios', 'Cubo Roda Traseira + 4 Prisioneiros Para Pop 100 2013 Fabricante: Fabreck/Unibreq Raios 4mm Cromado Aplicação: Honda Pop 100 2013 Enviamos 4 parafusos (prisioneiros) para prender (fixar) a coroa da relação no cubo Característica do cubo: O corpo é fabricado em alumínio escovado e anel em ferro fundido no campo de frenagem, tornando muito mais resistente e confiável. Produto de alta resistência. Excelente durabilidade, garantindo segurança com alto conforto e dirigibilidade. Produto reconhecido pela sua qualidade e pelo processo de fabricação genuinamente nacional. Produto fabricado de acordo com as especificações técnicas da montadora Os cubos são o suporte do disco de freio ou do tambor de freio. Nele estão fixados os parafusos de roda e o rolamento de roda. Padrão original. Garantia: não cobre aplicação inadequada ou outro problema que possa vir ocorrer com uso indevido do produto. Conteúdo da embalagem: 1 Cubo traseiro para Pop 100 Garantia: 90 dias contra defeito de fabricação. A garantia não contempla (se estende) para desgaste normal, instalação mal feita, adaptação ou mau uso. Essa garantia não cobre quebras ou danos sofridos por acidentes (colisões, tombos, batidas).', 199.9, 179.91, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5dbbwj6sk3633', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1012518791%2F18297298892', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5894433926', 'Torneira De Esfera Para Tanque E Jardim 1/2 Para 3/4', '💧 Torneira Esfera Metálica para Jardim, Quintal e Tanque - Máxima Durabilidade e Vedação Garanta um controle de fluxo de água eficiente e durável para suas áreas externas (Jardim, Quintal) ou de serviço (Tanque) com a nossa Torneira Esfera Metálica. ✅ Controle de Fluxo Superior (Válvula Esfera) Mecanismo Esfera: Utiliza uma válvula esfera, um dos dispositivos mecânicos mais confiáveis em residências e indústrias para controlar o fluxo de fluidos. Funcionamento Eficaz: A esfera interna com orifício permite a passagem de água quando alinhada ("aberta") e interrompe totalmente o fluxo quando girada a 90° ("fechada"), garantindo uma vedação completa. Acionamento Confortável: Possui cabo emborrachado para uma pegada firme e confortável, facilitando o acionamento (abrir/fechar) mesmo com as mãos molhadas. 🛠️ Durabilidade e Versatilidade Construção Metálica: Fabricada com materiais resistentes (Ferro, Zinco e Cloreto Polivinila), que asseguram a longa vida útil do produto mesmo em ambientes externos. Bitolas Universais: Projetada com rosca de instalação dupla, compatível com as bitolas de 1/2" e 3/4". Pronta para o Uso: Acompanha adaptador para conexão de mangueira (engate rápido). ⚙️ Especificações Tipo: Torneira Esfera Metálica. Aplicação: Jardim, Quintal e Tanque. Bitola de Instalação: 1/2" e 3/4" (compatibilidade). Acessórios: Acompanha Adaptador para Mangueira. Composição: Ferro, Zinco e Cloreto Polivinila. A escolha ideal para quem busca uma torneira robusta, com vedação 100% e alta durabilidade.', 20.9, 19.99, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltz6edhes42c84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com