INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207496603', 'Conjunto Bebê Menino Com Colete Animais Elian Verde', 'O Conjunto Elian é composto por camiseta em meia malha e colete e calça em moletom felpado. A camiseta de mangas longas possui punhos ajustados e estampa frontal com um tigre superfofo, enquanto o colete conta com fechamento em zíper e estampa com vários animais da selva, trazendo ludicidade ao look. Já a calça tem elástico no cós e punho nas barras, completando o visual com conforto. Ideal para passeios e momentos especiais, invista nesse visual completo para seu bebê ficar ainda mais lindo!Detalhes da peça: • Conjunto composto por camiseta, colete e calça • Feito em meia malha e moletom felpado • Camiseta com mangas longas • Estampa com animais da selva • Colete com fechamento em zíper • Elástico no cós • Ideal para passeios e momentos especiais', 149.9, 89.94, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8259l-mr1ttgbp1dkwf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58207496603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
