INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294686687', 'CHAVE GRIFO TIPO AMERICANO, MORDENTES EM ACO, 12POL., 300MM, 1PC // MTX', 'Chave Grifo Tipo Americano MTX 1571355 – 12" com dentes frontais Versatilidade e robustez para trabalhos profissionais Com 12 polegadas de comprimento, a Chave Grifo Tipo Americano MTX 1571355 é projetada para manipular tubos e peças de até 42 mm de diâmetro. Fabricada em alumínio, ela alia leveza e alta resistência, ideal para encanadores, mecânicos e artesãos domésticos que precisam de uma ferramenta durável e eficiente para tarefas exigentes. Principais vantagens Força e durabilidade: Construção em alumínio resistente com dureza entre 48-58 HRC, garantindo longa vida útil e resistência ao desgaste. Proteção contra danos: Acabamento em esmalte em pó e fosfatização das superfícies de trabalho oferecem proteção contra corrosão e aumentam a durabilidade. Trabalho confortável: Material leve que facilita o manuseio e reduz a fadiga durante uso prolongado. Armazenamento prático: Orifício na alça permite pendurar a ferramenta, otimizando o espaço e o acesso rápido. Aplicações recomendadas Serviços profissionais em encanamento e mecânica Reparos, instalações e manutenções gerais Projetos que exigem precisão e robustez Ferramenta confiável para qualquer desafio A Chave Grifo Tipo Americano MTX 1571355 combina funcionalidade, durabilidade e ergonomia para oferecer desempenho superior. Uma escolha ideal para profissionais que buscam qualidade e eficiência em suas ferramentas diárias.', 53.25, 53.25, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821dv-mh1z515wbsaw53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577891436%2F23294686687', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
