INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16740996311', 'Creme Relaxante HairLife Cacho & Natural', 'indicação para cabelos cacheados e crespos. ação relaxa e ondula os fios. ativos contém sais de ácido tioglicólico, amônia e peróxido de hidrogênio. benefícios transforma e define seus cachos deixando-os com aspecto natural. resultado cachos definidos e prontinhos para arrasar! modo de uso veja guia de aplicação anexo. composição creme alisante: aqua, cetearyl alcohol, thioglycolic acid, ammonium hydroxide, ceteareth-20, sodium lauryl sulfate, paraffinum liquidum, parfum, sodium hydrosulfite, tetrasodium edta, butyrospermum parkii butter, helianthus annuus extract, persea gratissima oil. neutralizante: aqua, hydrogen peroxide, cetearyl alcohol, ammonium lauryl sulfate, parfum, disodium edta, sodium lauryl sulfate, sodium stannate, tetrasodium pyrophosphate, lactic acid.', 17.0, 17.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/9a7017f25d74f97b48905cc5633b4cd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719923009%2F16740996311', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40711302395', 'Kit 3 Tapete Higiênico 150 Unidades Premium My Pad One Slim 60x50 cm', 'My Pad One – Tapete Higiênico 50cmx60cm Neutro MY PAD ONE Tapete Higiênico 6 Camadas: Máxima proteção para seu pet e praticidade para você! Com absorção ultra rápida e ação antibacteriana, mantém sua casa limpa e sem odores. Suas 6 camadas, incluindo cobertura antirrasgo e antivazamento, garantem retenção completa e ambiente seco. Ideal para filhotes e pets adultos. Dicas de Uso: - Para uma adaptação rápida, posicione alguns tapetes na área destinada ao pet e vá reduzindo até restar apenas um. - Após a fase inicial, utilize apenas um tapete por vez. - Descarte o produto apos o uso no chão com o lado dos adesivos voltados para baixo. Modo de Fixação: - Fêmeas e filhotes: fixe o tapete completamente aberto no chão. - Machos adultos: fixe metade do tapete na parede e metade no chão. Composição Básica: - Filme de polietileno - Tecido não tecido - Celulose - Papel e Polímero superabsorvente Modo de Usar: - Retire o tapete da embalagem e desdobre-o. - Remova os papéis protetores dos 4 cantos e fixe no chão com os adesivos voltados para baixo. Importante: A capacidade de absorção e retenção do My Pad One pode variar de acordo com a concentração da urina e a umidade do ambiente. O tapete reduz odores, mas não elimina totalmente o cheiro no ambiente. Benefícios: - Treinamento prático para cães filhotes e adultos. - Redução de odores indesejados. - Fixação segura no chão ou na parede. - Super absorvente, mantendo o ambiente limpo e seco. - Indicado para uso diário com praticidade e higiene. Experimente também os educadores sanitários Xixi Não e Xixi Sim da MyPetOne, que auxiliam no processo de adestramento de forma prática e sem estresse.', 209.99, 168.89, NULL, 'Pets > Litter & Toilet > Dog Training Pads & Trays', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md0ghtca1df621', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F40711302395', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9466037235', 'Faixa de Exercício Hip Band 5cm VP1085 Vollo M', 'Faixa de Exercício Hip Band 5cm VP1085 Vollo Modelo: VP1048 Largura: 5cm A Hip Band Vollo é usada para ativar os músculos ao redor dos quadris e glúteos, a fim de melhorar a técnica e torná-lo mais forte, mais rápido. A faixa adiciona resistência para fortalecer os abdutores do quadril e os rotadores externos, mantendo os joelhos afastados durante o agachamento e o deadlifts. Você também pode usar a faixa para se aquecer antes de começar seus treinos. Deslize a faixa sobre as duas pernas e dê passos largos para aquecer as pernas. Faixa de Exercício de Poliéster Largura aproximada: 5 cm Comprimento aproximado: P: 32 cm (Comprimento - 32cm)-(Largura 5cm) - VP1085-P - CINZA M: 37 cm (Comprimento - 37cm)-(Largura 5cm) - VP1085-M - LARANJA G: 42 cm (Comprimento - 42cm)-(Largura 5cm) - VP1085-G - CINZA ESCURO Conteúdo da Embalagem: 1 unidade da Faixa de Exercício Hip Band 5cm VP1085 Vollo Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 50.84, 50.84, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Yoga & Pilates', 'https://cf.shopee.com.br/file/9453fac0af6294126fa4678916907bee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F9466037235', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298502905', 'Kit 3 Comedouro Pratico Alvorada 3 Litros - Preto', '3 Comedouro Prático Alvorada Pet 3 Litros Mais praticidade e higiene para a alimentação do seu pet com o Comedouro Prático Alvorada Pet 3 Litros. Ideal para cães e gatos de todos os portes, ele possui capacidade generosa e estrutura resistente, garantindo refeições sempre organizadas e acessíveis para o seu animal de estimação. Seu sistema de alimentação por gravidade permite que o compartimento inferior esteja sempre abastecido com ração, oferecendo autonomia e conforto mesmo quando você estiver fora por algumas horas. Por que escolher o Comedouro Alvorada 3 Litros: - Capacidade de 3 Litros: Armazena uma boa quantidade de ração seca, reduzindo a frequência de reabastecimento - Sistema por Gravidade: Mantém o recipiente sempre cheio conforme o pet consome a ração - Base Estável e Antiderrapante: Mais segurança na hora da alimentação - Fácil de Higienizar: Peças removíveis que facilitam a limpeza do dia a dia - Transparente e Funcional: Permite visualizar facilmente o nível de ração disponível Especificações Técnicas: - Capacidade: 3 Litros - Cores: Azul, Rosa, Preto, Vermelho Dimensões Aproximadas: - Altura: 22,5 cm - Base: 27 cm Material: - Reservatório em plástico translúcido de alta resistência - Base em polipropileno atóxico e livre de BPA Com o Comedouro Prático Alvorada pet 3L, você garante uma rotina mais prática e saudável para seu pet, com alimentação contínua e organizada.', 97.5, 70.9, NULL, 'Pets > Pet Accessories > Bowls & Feeders', 'https://cf.shopee.com.br/file/sg-11134201-7rfhr-m9ys2albn8o990', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22298502905', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
