INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097163290', 'Capa Rebolo Tantan Gope 12x50 Pol Nylon Reforcada Cor Preto', 'A Capa Rebolo Tantan Gope 12x50 Polegadas Nylon Reforcada Cor Preto e um produto de alta qualidade, proveniente da renomada marca Gope. Esta capa e confeccionada em nylon resistente, proporcionando protecao ao seu instrumento musical contra possiveis danos e desgastes. Com um diametro de 12 polegadas e uma altura de 50 cm, esta capa se ajusta perfeitamente ao seu Rebolo Tantan. A cor preta da capa confere um toque de elegancia e sofisticacao ao seu instrumento. O design e simples, porem eficaz, com um acabamento limpo e profissional. O modelo 50X12 e reconhecido pela sua durabilidade e resistencia, sendo uma escolha comum entre os musicos. Esta capa e pratica para usar e transportar, sendo ideal para musicos que estao sempre em movimento. O material de nylon reforcado e leve, mas robusto, oferecendo uma protecao confiavel para o seu Rebolo Tantan. Alem disso, a largura de 10 polegadas permite um ajuste confortavel e seguro. Em resumo, a Capa Rebolo Tantan Gope 12x50 Polegadas Nylon Reforcada Cor Preto e uma excelente opcao para proteger o seu instrumento musical. Com sua construcao de alta qualidade e design elegante, esta capa certamente atendera as suas necessidades e expectativas.', 99.17, 99.17, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rbn6-los8a3zc63pi87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F23097163290', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
