INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12037139226', 'Par de hastes com dobradiças para Notebook Samsung NP300E5M-XD1BR', 'Par de hastes com dobradiças para Notebook Samsung NP300E5M-XD1BR Estas hastes com dobradiças para notebook são a solução para seus problemas com o movimento de abrir e fechar a tampa do seu computador. O produto é novo, feito em material resistente e a embalagem contém duas unidades para montagem e fixação nos lados direito e esquerdo da carcaça do notebook. Com as hastes e dobradiças novas você soluciona alguns problemas: - Dificuldade ao abrir e/ou fechar o notebook - Tampa do notebook está frouxa e/ou mole - Barulho ao abrir e/ou fechar a tampa - Elevação ou rachadura na carcaça do notebook Atenção! É importante verificar a compatibilidade das hastes e dobradiças com o seu modelo de notebook para que sejam exatamente as peças que seu computador precisa. Garantia: 3 meses de garantia contra defeitos de fabricação Referência: HT046-0019', 107.2, 107.2, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-825bb-mq7pzsxscc1tac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F12037139226', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897269559', 'Halter Dumbbell Sextavado Pintado 12Kg Peso de Academia Para Treino Em Casa E Musculação', 'HALTER SEXTAVADO PINTADO 12KG – POTENCIALIZE SEUS TREINOS COM MAIS FORÇA E DURABILIDADE O Halter Sextavado Pintado MegaGym Equipamentos, é o halter ideal para o seu treino. Sendo o mesmo elaborado em ferro fundido e com revestimento em pintura weglack premium, o halter sextavado se destaca por sua qualidade e resistência. Pois sua pintura impede a sua oxidação, e permite que seu treino seja mais seguro e que tenha uma vida útil muito mais longa. Além disto o seu formato anatômico garante que o seu treino seja mais efetivo e funcional e muito mais eficiente. Benefícios: — Pegada Anatômica — Treinamento Versátil — Ganhos de Massa e Definição Muscular — Aprimoramento da Postura e Equilíbrio — Fortalecimento Muscular Característica Do Produto: Material: Ferro Fundido; Revestimento: Pintura Protetora Premium, que evita corrosão e desgaste por longos períodos; Modelo De Pegada: Anatômica; Numeração Gravada: Facilita a identificação do peso; Cor: Preto Exercícios Indicados: — Supino Reto com Halteres; — Supino Inclinado com Halteres; — Crucifixo Reto com Halteres; — Desenvolvimento com Halteres; — Elevação Lateral;', 287.23, 160.73, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4um519t6m3481', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867949056%2F22897269559', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
