INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208738207', 'Toalha de Papel Kitchen Jumbo Folha Dupla 360 Folhas 3 Rolos', 'A toalha de papel Kitchen Jumbo Folha Dupla foi desenvolvida para oferecer alta absorção, resistência e praticidade nas tarefas do dia a dia. Com folhas duplas, proporciona maior eficiência na limpeza, permitindo absorver líquidos com mais rapidez e reduzir o desperdício, já que é possível utilizar menos folhas por uso. Ideal para uso na cozinha, o produto auxilia na limpeza de superfícies, secagem de alimentos, remoção de gorduras e pequenas sujeiras, além de ser útil em diversas situações domésticas. Sua estrutura reforçada garante maior durabilidade mesmo quando úmida, evitando que o papel se desfaça com facilidade durante o uso. A versão jumbo conta com 360 folhas no total, distribuídas em 3 rolos, oferecendo excelente rendimento e economia para o consumidor. Versátil e prática, é uma solução indispensável para manter a higiene e organização da casa no dia a dia, combinando eficiência, resistência e ótimo custo-benefícioPerfeito para todas as ocasiões, desde a absorção de alimentos até a secagem de louças e superfícies.', 23.99, 18.99, NULL, 'Home & Living > Home Care Supplies > Tissue & Paper Towels', 'https://cf.shopee.com.br/file/sg-11134201-822wh-moa76egz1wy477', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302953%2F58208738207', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
