INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22996989019', 'Água Oxigenada Elisafer Color Affair 40 Volumes 90ml', 'A Água Oxigenada cremosa estabilizada Color Affair possui fragrância sofisticada e sua fórmula permite uma aplicação rápida e eficiente no processo utilizado em tinturas, reflexos, ballayages, decapagens, luzes, clareamentos e descoloração. Prova de toque: Prepare um pouco desse produto como se fosse utilizá-lo, aplique antebraço ou atrás da orelha e deixe agir por 30 minutos. Lave o local e aguarde 24 horas e se nesse período surgir irritação na pele, coceira ou ardência no local ou na sua proximidade, fica provada a hipersensibilidade da pessoa ao produto e, portanto não deve ser utilizado. Modo de uso: Deve ser utilizada na preparação de colorações e descolorações dos cabelos na quantidade indicada no modo de preparo do produto a ser utilizado. #html-body [data-pb-style="646BA646D6EFF"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA646D6F14"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 17.85, 17.85, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rbkz-lmf5blz6avrt4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22996989019', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792493672', 'Esmalte Anita Cremoso Maca Do Amor', 'As tarefas que realizamos diariamente prejudicam as unhas, por essa razão elas requerem cuidado e atenção constantes. Os esmaltes Anita possuem em sua fórmula vitaminas e minerais que ajudam a fortalecer as unhas. Modo de usar: Com as unhas limpas, aplique uma ou duas camadas do esmalte, de acordo com a intensidade desejada. #html-body [data-pb-style="646BA6478E453"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA6478E468"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 22.48, 22.48, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbld-lmg2216z28btac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22792493672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
