INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44505617513', 'Camisa CCCP Retrô 1982 Masculina', 'Camisa clássica usada pelo gigante URSS na copa de em 1982, mostraram ao mundo a força daquela equipe com sua tradicional camisa levando a inscrição CCCP no peito. Produzida com tecido de algodão e listras em silk, que oferece tradição e conforto. O escudo retrô bordado com preenchimento em couro ecológico mantém a originalidade da peça. Uso casual, indicado para momentos de lazer e ir ao estádio. — Característica: - 100% Algodão. - Escudo bordado em alta definição com preenchimento especial de couro. - Listras em Silk Medidas Aproximadas: Largura x Altura - P (BR): 50 x 69 - M (BR): 52 x 71 - G (BR): 54 x 73 - GG (BR): 56 x 75 - EG (BR): 62 x 78 - EGG (BR): 64 x 80 Informações Adicionais: - Envio imediato. - Todos os produtos a pronta entrega. - Garantia: Contra defeito de fabricação.', 199.9, 179.91, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jerseys', 'https://cf.shopee.com.br/file/sg-11134201-82633-mk2svk3o00slb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F698219490%2F44505617513', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897679010', 'Janela Veneziana de Alumínio 3 Folhas 100 x 80cm Linha Modular Preto Esquadrias Bergamo 100cm x 80cm', 'Janela de Alumínio Branco Veneziana 3 Folhas Linha Modular - Bergamo Em alumínio linha 20, esta janela de alumínio se destaca por ser resistente em todos os sentidos, tanto em sua funcionalidade, quanto na segurança e em seu design arrojado e ao mesmo tempo simples. Indicada para ambientes internos e externos. Um ponto importante é preparar o vão onde a janela de alumínio será instalada se atentando aos pontos onde irão ser fixadas as grapas, lembrando que é importantíssimo para um ótimo funcionamento do produto que ele seja assentado em nível e prumo. Características Quantidade de folhas: 3 folhas Tipo de Abertura: De Correr Lado de Abertura: Da esquerda para Direita, folha fixa direita (Ref. Estando dentro do ambiente) Largura do Batente: 8 cm Peso (kg): 6 Elétrica: Não Garantia: 12 Meses Altura (cm): 100 Largura (cm): 80 Cor do Vidro: Incolor Espessura (cm): 8 Possui Grade: Não Tipo de Vidro: Liso Vidro incluso: Sim Cor do Batente: Preto Tipo de Janela: Veneziana Tipo de Parede: Alvenaria Vidro Temperado: Não Desenho do Vidro: Transparente Escala de Brilho: Fosco Lado de Abertura: Esquerda Número de Folhas: 3 Acompanha Batente: Sim Origem do Produto: Nacional Palheta Removível: Não Espessura do Vidro: 3 Necessita Montagem: Não Acompanha Guarnição: Não Material do Batente: Alumínio Quantidade de Folhas: 3 Possui Controle Remoto: Não Abertura para Ventilação: Sim Possui Isolamento Acústico: Não Acompanha Manual de Instalação: Sim Material Principal Construção e Acabamento: Alumínio Marca: Esquadrias Bergamo Cor do Produto: Preto Itens Inclusos: 1 Janela Cor Predominante: Preto Linha ou Coleção: Linha 20 Tamanho do Produto: 100cm x 80cm', 802.48, 802.48, NULL