INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49501131988', 'Tênis Infantil Menino Kidy K360 Estilo Respitec Confortável Anatômico Flexível Leve Escolar Moderno', 'O tênis infantil streetwear da Kidy é perfeito para as pequenas que adoram estilo e conforto em cada passo. Com um design moderno, ele traz um toque descolado para qualquer look, combinando atitude e praticidade. Além de lindo, esse modelo é anatômico, garantindo um ajuste perfeito aos pés para acompanhar todas as brincadeiras. O solado antiderrapante oferece mais segurança, enquanto a palmilha Tec Gel proporciona uma pisada macia e confortável. E para manter os pezinhos sempre fresquinhos, a tecnologia Respitec permite a circulação de ar, evitando o acúmulo de suor e garantindo bem-estar o dia todo! Formato Anatômico: Sempre pensando na saúde e conforto das crianças, todos os calçados Kidy possuem formato anatômico que auxilia no crescimento e desenvolvimento saudável dos pés. Tamanhos:do 28 ao 36; Fechamento:Cadarço; Cabedal:Napa/Têxtil; Forro:Têxtil;Palmilha: EVA Perfurado/Tec-Gel; Sola:PVC Expandido;', 179.99, 162.0, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-821fk-mgwac4yxr18o26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F49501131988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292528594', 'Flange Bomba Combustível Peugeot 307 2007 a 2012 - 182275 - T030040', 'Flange Bomba Combustível Peugeot 307 2007 a 2012 182275 T030040 MOTOR 1.6/2.0 FLEX (BOSCH) Flange é um elemento de plástico ou de metal que fixa o Módulo de Combustível ao tanque de combustível do veículo. Além da fixação, a Flange faz ligação hidráulica e elétrica do interior do tanque para o exterior, permitindo o acesso ao Módulo de Combustível (composto por bomba de combustível, sensor de nível, pré-filtro, regulador de pressão, tubo corrugado e guarnição) sem operação destrutiva ou de descarte, proporcionando o reparo necessário dos componentes inclusive da própria Flange.', 72.06, 72.06, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-823re-mok3a2zjuwp793', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22292528594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
