INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798984156', 'Principia Kit Rosa Peles Sensíveis c/ Gel de Limpeza GL-03 + Água Micelar AM-10 + Sérum Multirreparador MIX-03', 'Kit com 3 produtos: um Gel de limpeza com 9,5% de mix de tensoativos, 30% de glicerina e 1% de extrato de algodão, melhora da hidratação, maciez e viço indicado para peles sensíveis e secas, um sérum com multivitaminas + manteiga de abacate + bisabolol + esqualano e uma água micelar com tensoativos não iônicos + ésteres de óleo de oliva RECOMENDAÇÕES Remover impurezas Remover maquiagem Promover hidratação Proporcionar maciez Remover impurezas MODO DE USO MIX-03 (MULTIVITAMINAS + MANTEIGA DE ABACATE + BISABOLOL + ESQUALANO) » Use diariamente de manhã e a noite » Aplique antes de cremes, protetor solar e maquiagem » Deixe o rosto limpo e seco » Sem encostar a cânula da pele, dispense algumas gotas nos dedos ou diretamente na face » Espalhe suavemente pelo rosto, inclusive na área dos olhos Aplique na área dos olhos GEL DE LIMPEZA GL-03 » Use todos os dias, de manhã e à noite » Aplique uma pequena quantidade na face úmida e massageie até fazer espuma, enxaguando em seguida Contém parabenos, petrolatos ou silicones? Não. Sua composição também não inclui corantes, fragrância nem glúten. AM-01 (TENSOATIVOS NÃO IÔNICOS + ÉSTERES DE ÓLEO DE OLIVA) » Embeber um algodão e passar suavemente na face, lavar a pele ou aplicar hidratantes depois. Contém parabenos, petrolatos ou silicones? Não. Sua composição também não inclui corantes, fragrância nem glúten.', 195.97, 150.9, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfmikr49iepx85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373261329%2F23798984156', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201294055', 'Almofada de Pescoço Flex FOM Edge - Turquesa', 'Conforto que acompanha o seu ritmo. A Almofada de Pescoço Flex FOM Edge – Turquesa foi criada para transformar viagens, pausas e momentos de descanso em experiências muito mais leves. Seu design flexível abraça o pescoço de forma ergonômica, oferecendo apoio estável e acolhedor que reduz a tensão e proporciona alívio imediato. Com a tecnologia de conforto da FOM, o tecido macio com toque suave se adapta ao corpo, enquanto o enchimento de micropérolas de poliestireno molda-se aos contornos do usuário, garantindo sensação de relaxamento a cada movimento. A cor Turquesa (Submarine) traz frescor e personalidade, perfeita para quem busca estilo e bem-estar no dia a dia ou nas viagens. Composição: Tecido: 78% Poliamida / 22% Elastano Enchimento: 100% micropérolas de poliestireno', 198.0, 198.0, NULL, 'Travel & Luggage > Travel Accessories > Travel Pillows & Eye Covers', 'https://cf.shopee.com.br/file/sg-11134201-8226z-mhqc5bxlt534a9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1366041969%2F58201294055', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
