INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26988742691', 'Kit Colorir - Harry Potter', 'Kit Colorir – Harry Potter_x000D_ _x000D_ _x000D_ Transforme seus momentos de descanso em uma jornada mágica com o Kit Colorir – Harry Potter! Inspirados no fenômeno do TikTok, esses dois livros de colorir são perfeitos para quem ama relaxar com criatividade e muita magia._x000D_ _x000D_ _x000D_ Com ilustrações encantadoras de personagens e elementos do universo Harry Potter, o kit inclui:_x000D_ _x000D_ _x000D_ Cozy Time Harry Potter – 48 páginas com 24 ilustrações_x000D_ Comfy and Cozy Harry Potter – 96 páginas com 48 ilustrações - Capa Dura_x000D_ _x000D_ _x000D_ Impressos em papel de alta gramatura, ideais para lápis de cor, canetinhas, esses livros proporcionam uma experiência calmante, divertida e envolvente — perfeita para fãs de todas as idades._x000D_ _x000D_ _x000D_ Prepare seu cantinho favorito, escolha suas cores e embarque nessa aventura criativa pelo mundo mágico de Hogwarts!_x000D_ _x000D_ _x000D_ _x000D_ _x000D_ Ciranda Cultural.', 84.8, 42.4, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc9pew6eqiuj60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F26988742691', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992953025', 'Livro Adesivos Barbie - Passatempos especiais', 'Venha passar momentos de diversão na companhia de Malibu e seus amigos, fazendo muitas atividades. Há jogo das diferenças, imagens para colorir, labirintos e muito mais!_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2024_x000D_ Autor: Marina Evangelista_x000D_ Idioma: Português_x000D_ Páginas: 24_x000D_ Dimensões: L 21.00 x A 28.00 x E 0.20_x000D_ ISBN: 9786526109861_x000D_ Coleção: Adesivos fofinhos_x000D_ Linha Editorial: Ciranda Cultural - Licenças_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Entretenimento, Diversão, Colorir, Desenhos, Amizade, Adesivos_x000D_ BISAC: Literatura Infantil / Mídia Tie-in_x000D_ Linha de Produto: Adesivos 3-D (puffy)_x000D_ Encadernação: Grampeado_x000D_ Acabamento: Verniz UV total_x000D_ Material: Papel', 19.9, 19.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd6d-lu0phlyfjziab4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F23992953025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10113515428', 'Livro - Anne de Green Gables - Capa comum - Ciranda Cultural', 'Os irmãos Mathew e Marilla Cuthbert moram em uma linda propriedade em Green Gables. Eles decidem adotar um garoto órfão para ajudar nos serviços gerais, em troca de moradia. Qual não foi a surpresa dos dois ao receberem, em vez de um garoto, a adorável Anne, uma menina ruiva, sensível e cheia de vida. Encante-se com essa história adaptada por Donaldo Buchweitz a partir do adorável clássico de Anne Maud Montgomery, Anne de Green Gables. Editora: Ciranda Cultural Edição: 1, 2021 Autor: Lucy Maud Montgomery Idioma: Português Páginas: 32 Dimensões: L 24.00 x A 26.00 x E 0.40 ISBN: 9786555005691', 39.9, 39.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/cc85b65d4bd9048e29add8f27287c9e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F10113515428', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
