INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293489743', 'Sandália Comfortflex Total Care Feminina 100% Original Com Nota Fiscal e Garantia de Fábrica', 'Sandália Comfortflex Total Care Feminina Este é um produto original Comfortflex com garantia vendido pela B2 Online. A Sandália Comfortflex Total Care é projetada com foco no bem-estar do usuário. Seu design ergonômico se adapta à forma do pé, proporcionando uma experiência de uso confortável, mesmo em longos períodos. A combinação de materiais leves e flexíveis ajuda a reduzir a sensação de cansaço, tornando-a ideal para o dia a dia. Um dos pontos altos desta sandália é a facilidade de calçar e descalçar. Com fechamento por aderência permite uma experiência ainda mais rápida. A Total Care tem palmilha super macia, sola flexível em TR antiderrapante e ajuste suave, calce perfeito. É uma escolha ideal para quem valoriza conforto, estilo e praticidade. Plataforma: 4 cm • Gênero: Feminino • Modelo com calce fácil • Feita de material sintéticо • Solado de borracha antiderrapante para proporcionar melhor tração e estabilidade • Palmilha anatômica • Solado macio e confortável • Nacional Foto do produto condiz com a realidade. Não existe variação significativa de cor entre o produto real e a foto. Edição realizada em programa gráfico para aproximar ao máximo a foto à cor real do produto.', 290.85, 159.0, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-7rdwv-m1hebrqktyylb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F535071110%2F22293489743', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55251750508', 'Par de Lâmpadas LED Torpedo SJ-COB-12C-39MM 12v 6000k Tarponn - TP-5033', 'O melhor custo-benefício em iluminação automotiva está aqui, com a Lâmpada Tarponn LED Torpedo SJ-COB-12C-39MM 12v 6000k! Conheça agora o LED COB Tarponn, considerado uma nova tendência em luz automotiva. Sabia que a tecnologia CO oferece uma área de luz superior (até 111 maior) e ainda evita o desconforto visual, por fornecer uma luz amarela de luz superior através dos chips? Além disso, sua construção dispersa calor rapidamente e permite vida útil prolongada além de maior eficiência energética. Perfeita para iluminação de interiores, como luz de teto, porta malas, porta luvas e placa. Para quem busca tecnologia e durabilidade, a Lâmpada Tarponn LED Torpedo SJ-COB-12C-39MM 12v 6000k é uma excelente alternativa! Características: Baixo consumo Durabilidade superior Iluminação branca fria Fácil instalação Aplicação: iluminação de ambientes internos, como luz de teto, porta-malas, porta-luvas e placa Ficha Técnica: Cor: Branca Fria Temperatura de Cor: 6000k Encaixe: Torpedo Tensão: 12v Equivalência: 10w Tipo de LED: COB Fluxo luminoso: 240 Im Características: -Marca: Tarponn -Modelo: TP-5033 *Imagens meramente ilustrativas* Conteúdo da embalagem: - 01 par de lâmpadas LED', 19.48, 17.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-821e4-mh9dhsl50kcr4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F55251750508', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
