INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260966706', 'Sanduicheira Blackstone Preta Midea', 'Praticidade que combina com sua rotina. A Sanduicheira Preta Blackstone Midea possibilita preparos saborosos com total facilidade. A Sanduicheira Preta Blackstone Midea possibilita preparos saborosos com total facilidade. Suas placas internas onduladas são ideais para sanduíches e grelhados, garantindo aquecimento uniforme e resultados perfeitos. Para sua segurança, o produto conta com luz indicadora de funcionamento, controle de temperatura automático, trava de fechamento e alça fria ao toque. Além disso, sua potência de 750W e a grelha dupla proporcionam mais rapidez e precisão no preparo. O interior antiaderente BlackStone exclusivo dispensa o uso de óleo ou manteiga, contribuindo para alimentos mais leves e saborosos, além de facilitar a limpeza. ATENÇÃO: PARA COMPRAS COM CNPJ, FATURAMOS APENAS PARA CADASTROS ISENTOS E NÃO CONTRIBUINTES DE ICMS.', 109.0, 109.0, NULL, 'Home Appliances > Kitchen Appliances > Toasters', 'https://cf.shopee.com.br/file/sg-11134201-825av-mqqab4dpqnsz0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1736335904%2F58260966706', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
