INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26983684734', 'Bíblia Sagrada Leia E Anote | Nvt | Letra Normal | Capa Luxo', 'Bíblia Sagrada Leia e Anote | NVT | Letra Normal | Capa Luxo Preta Bíblia Sagrada Leia e Anote Sabemos que é no secreto que revelamos nossos maiores desejos e expressamos nossos mais íntimos pensamentos, então para te auxiliar a extrair tudo o que Deus sondar e te revelar a cerca de ti, você poderá anotar tudo nos espaços para anotação dessa bíblia. O processo é simples, leia e anote e é claro reflita sobre o que leu. Depois saia do secreto e aplique tudo o que você absorveu nessa leitura incrível, afinal de contas, estamos falando da bíblia, não basta ler, precisa viver o que leu! Já conhece a versão bíblica Nova Versão Transformadora (NVT)? Uma revisão que desde lançada tem trazido aos leitores uma incrível experiência no entendimento da palavra através do seu fácil entendimento e fidelidade nos textos originais, uma versão que muito nos agradou. Agora você terá em suas mãos uma bíblia com linguagem fiel e, ao mesmo tempo, moderna, a Bíblia Sagrada NVT com o design bem mais fininho que as bíblias convencionais, com capa dura e bordas arredondadas. Páginas:768 Formato:Altura: 20 cm Largura: 17,5 cm Profundidade: 2,5 cm', 109.82, 109.82, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7renr-m8ne75yim8xse0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F26983684734', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
