INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297521584', 'Espátula de Aço Cromado 4/6/8/10/13 Cm Atlas', 'A Espátula De Aço Cromado 6cm 6255/10 Atlas é uma ferramenta de alta resistência, fabricada com aço polido, ideal para trabalhos de preparação e raspagem. Sua lâmina cromada garante durabilidade e eficiência, sendo perfeita para repinturas e remoções em diversas superfícies. Vantagens: Fabricada em aço cromado, garantindo resistência e maior durabilidade. Lâmina polida, proporcionando um corte preciso e uniforme. Ideal para preparações de repintura e raspagens em geral. Versátil, pode ser utilizada em diversos tipos de superfícies e acabamentos. Dados técnicos: Composição: Aço cromado polido. Largura da lâmina: 4cm, 6cm, 8cm, 10cm, 13cm. Indicação de uso: Preparações de repintura e raspagens em geral. Marca: Atlas. Garantia: Garantia de 3 meses pelo fabricante.', 42.9, 31.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7ra0r-m4z43602c5qvfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F21297521584', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
