INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198024090', 'Brinquedo Pônei Bee Toys Little Bee', 'Descubra a magia dos contos de fadas com o encantador Brinquedo Pônei Bee Toys Little Bee! Este pônei adorável é mais do que um simples brinquedo – é um companheiro de aventuras que trará à vida a imaginação das crianças, transportando-as para um mundo cheio de fantasia e diversão. Ideal para complementar o universo das bonecas, o Pônei Little Bee é a escolha perfeita para presentear e surpreender os pequenos.Penteie, trance, coloque fitas e presilhas – as opções são infinitas! Além de ser uma atividade divertida, pentear a crina do pônei ajuda a aprimorar a coordenação motora e a destreza das mãos das crianças. Este brinquedo mágico também é uma excelente ferramenta para estimular a interação entre pais e filhos. Ao brincar com o Pônei Little Bee, os pais têm a oportunidade de se envolver nas histórias e fantasias dos seus filhos, criando momentos preciosos de conexão e fortalecimento de laços familiares. As brincadeiras podem se tornar verdadeiras aulas de criatividade, onde cada nova história é uma aventura única e inesquecível.Seja no reino encantado das princesas ou em uma fazenda mágica, o Pônei Little Bee sempre será o herói fiel e companheiro das bonecas e outros brinquedos. Este pônei é uma porta de entrada para um mundo onde tudo é possível, e onde cada brincadeira é uma nova oportunidade de aprender e crescer.. Compre agora e deixe a imaginação voar alto com o Pônei Little Bee da Bee Toys!', 16.99, 16.99, NULL, 'Mom & Baby > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258k-mq571nv5fvuq63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F22198024090', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793943911', 'Meia Sapatilha Com Sola Emborrachada Feminina Unicórnio Encantado - Puket', '''A meia sapatilha pansocks é atoalhada, promovendo maior conforto na pisada. Produzida em algodão macio e desenho em poliamida no tema Uni Floresta Encantada. Não possui aroma, e possui acabamento em viés e elástico confortável. Possui solado emborrachado desenhado. Indicação de uso: Ideal para uso de prática de atividades sem uso de calçado Instruções de Lavagem: Lavagem a mão Não alvejar Instruções de Conservação: Não secar em tambor Não passar Não limpar a seco (MAIS INFORMAÇÕES, VIDE NA ETIQUETA) Instruções de Garantia: Deverá ser encaminhado dentro na embalagem original, sem indicações de uso ACOMPANHADO DE NOTA FISCAL E com todos os itens constante na solicitação da compra.'' 64%ALGODÃO;34%POLIAMIDA;2%OUTRAS FIBRAS', 64.9, 64.9, NULL, 'Women Clothes > Socks & Stockings > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7rfgy-m965th6ddlhxde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805460736%2F22793943911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
