INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15715211874', 'CALCINHA MODELADORA FIO DENTAL DEMILLUS 46005', 'Característica: Calcinha fio dental modeladora. Cintura alta. Faixa dupla canelada no abdômen modela com conforto e leveza. Cavas das pernas com acabamento em elástico viés suave. Confeccionada em microfibra estruturada, ajuste e compressão na medida certa.Composição: 85% Poliamida, 05% Algodão e 10% Elastano.', 72.5, 72.5, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/sg-11134201-22110-kpkrtv8bgsjv82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F15715211874', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
