INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22018508218', 'Máscara de cílios Lash Princess sculpted volume essence', '✨ MÁSCARA DE CÍLIOS LASH PRINCESS SCULPTED VOLUME Definição e volume para um olhar marcante. A máscara de cílios Lash Princess Sculpted Volume da essence foi desenvolvida para modelar e destacar cada fio, proporcionando cílios definidos, volumosos e perfeitamente separados. Seu aplicador cônico envolve os cílios desde a raiz até as pontas, garantindo definição precisa e um efeito modelado que realça o olhar. Com ela, tudo é possível: criar volume dramático, um olhar expressivo ou cílios ultradefinidos. A fórmula é livre de parabenos, fragrâncias e álcool, oferecendo performance com mais cuidado para a área dos olhos. 👑 Volume e Definição Cílios marcantes e perfeitamente modelados. ✨ Aplicador Cônico Modela os fios e garante separação precisa. 🖤 Olhar Expressivo Permite criar desde definição natural até volume dramático. 🌿 Fórmula Clean Sem parabenos, fragrâncias e álcool. 🔬 Oftalmologicamente Testada Segurança para a área dos olhos. 🌿 Sobre a Marca A essence é a marca nº 1 na Europa em unidades de cosméticos*, oferecendo qualidade com preço acessível. 100% livre de crueldade animal desde o início, com forte compromisso com produtos veganos. Acreditamos em uma beleza divertida, acessível e responsável. Para a essence, cada pessoa é única — o perfeito é ser você. *Marca de cosméticos em unidades.', 47.9, 47.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ln7pisrvff97e2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816819540%2F22018508218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
