INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21598101453', 'Chinelo Brizza Arezzo Slide EVA Marrocos Rosa - Feminino', 'Chinelo Slide Brizza Arezzo EVA Marrocos Rosa - Feminino. Conforto ao longo do seu dia. Ficha Técnica Material: EVA Cor: Rosa Palmilha: Texturizada com aspecto tramado e tag da marca Solado: Rasteiro flat Design: Tira larga com textura tramada Gênero: Feminino Marca: Brizza Arezzo Conteúdo da Embalagem: 1 par de Chinelo Slide Brizza Arezzo EVA Marrocos Rosa - Feminino. O Chinelo Slide Brizza Arezzo EVA Marrocos Rosa – Feminino combina elegância e conforto para o seu dia a dia. Com sola rasteira flat em EVA, o modelo se destaca pelo design que imita tiras de cordão torcido, oferecendo um visual moderno e diferenciado. A palmilha texturizada com aspecto tramado e tag lisa do nome da marca garante um toque sofisticado. O chinelo possui bico redondo e uma tira larga com textura tramada sobre os dedos, proporcionando firmeza e estilo. Aberto, ele exibe todo o pé, ideal para compor looks diários e elegantes.', 99.99, 79.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7reot-m8db3m7la3v9f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F21598101453', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21866262602', 'Fumaça em Pó', 'O tempero fumaça em pó é um produto desenvolvido a partir da fumaça líquida que dá sabor, cor e aroma defumado aos alimentos. É usado em carnes grelhadas, hambúrgueres, legumes, frango, carne suína, peixes, entre outros. Também é utilizado para fazer o famoso molho Barbecue. A fumaça em pó, tanto quanto a fumaça líquida, é um tempero que defuma instantaneamente os alimentos, proporcionado cor, aroma e sabor de defumado podendo ser usado em várias receitas. PRODUTO TRANSGÊNICO. Ingredientes: Sal, farinha de milho enriquecida com ferro e ácido fólico, aroma idêntico ao natural de fumaça, realçador de sabor glutamato monossódico, antiumectante fosfato tricálcico e acidulante ácido cítrico. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 28.81, 28.81, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mealpd9jr0ub8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F21866262602', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
