INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40881485718', 'Folhagem Eucalipto Artificial Pendente 95cm Verde Realista Jardim Vertical Decoração Casa Primo', 'Leve mais charme e aconchego para sua decoração com o Pendente de Eucalipto Artificial. Ideal para compor ambientes internos e externos cobertos, ele traz um toque natural e sofisticado sem exigir manutenção constante. Perfeito para decorar salas, cozinhas, varandas, escritórios, festas, jardins verticais e vasos. Com folhagens em tom verde escuro e acabamento realista, o pendente possui ramos flexíveis e ajustáveis, permitindo dobrar ou cortar para adaptar da melhor forma ao espaço desejado. Produzido em plástico ele oferece praticidade, durabilidade e beleza para qualquer ambiente. O produto é ideal para quem deseja um ambiente mais leve, elegante e harmonioso sem precisar dos cuidados de plantas naturais. Importante: O vaso e a placa de grama das imagens são apenas ilustrativos e não acompanham o produto. Características do Produto: Modelo: Pendente de Eucalipto Artificial Cor: Verde Material: Plástico Medidas aproximadas: 95 cm Ideal para vasos, cachepots, arranjos e jardim vertical Produto leve, resistente e de fácil manutenção Cuidados: Limpar com espanador ou flanela seca Não utilizar produtos químicos ou abrasivos Conteúdo da Embalagem: Kit com Dois Pendente de Eucalipto Artificial', 36.99, 20.09, NULL, 'Home & Living > Gardening > Others', 'https://cf.shopee.com.br/file/sg-11134201-823pj-mp442ycgx6o1fc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402450553%2F40881485718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
