INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23299488307', 'Kit Creme Dental Colgate Periogard 2 Unidade 90g', 'Colgate Periogard 2x90g: Tratamento Eficaz Contra Gengivite e Inflamações Este creme dental Colgate Periogard de hortelã 90g é uma pasta de dentes para combater a gengivite, que ajuda a prevenir sangramento na gengiva (a escovação diária com esse creme dental leva à remoção da placa bacteriana) e a placa bacteriana para uma saúde bucal completa e eficaz.O Creme Dental Para Gengivite Colgate Periogard foi desenvolvido especialmente para quem sofre com inflamações e sangramentos gengivais. Com fórmula antibacteriana potente, ele atua diretamente na causa da gengivite, ajudando a reduzir a placa bacteriana, fortalecer a saúde da gengiva e proporcionar uma higiene bucal mais profunda. Sua ação profissional oferece resultados visíveis desde os primeiros dias de uso, garantindo alívio, proteção e sensação de frescor prolongado. Para que serve o Creme dental Periogard: Trata', 70.95, 70.95, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-823oj-moslf385ks27cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23299488307', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694018229', 'Apontador com coletor Two Tone SM/TWOTONEAPT com 1 unidade Faber-Castell', 'O Apontador Faber-Castell Two Tone é a combinação ideal entre praticidade, qualidade e estilo. Com lâmina de aço temperado e corpo em cores vibrantes, garante um apontamento preciso e sem esforço, preservando a ponta do lápis e evitando quebras. Seu coletor translúcido permite visualizar o nível de resíduos, oferecendo mais higiene e comodidade no uso diário. Ideal para uso escolar ou no escritório, é compacto, leve e cabe perfeitamente no estojo. Detalhes: - Dois furos: Ideal para todos os formatos de lápis. - Apontador com depósito: mais praticidade e menos sujeira. - Lâmina de qualidade: pontas do lápis perfeitas ao apontar. - Design Exclusivo Faber-Castell.', 27.36, 27.36, NULL, 'Stationery > School & Office Equipment > Sharpeners', 'https://cf.shopee.com.br/file/sg-11134201-7rdwa-mc11k4nb4cum82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F23694018229', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093871507', 'Quadro Jesus Cristo Abstrato Para Sala Quadro Decorativo Com Moldura Grande Quadro Cristão Oração', '⚠️ ATENÇÃO – ESCOLHA A OPÇÃO DESEJADA No campo de variação, selecione: ✔ Com Vidro (mais proteção) ✔ Sem Vidro (mais leve e sem reflexo) Antes de finalizar a compra, confira o tamanho e o acabamento selecionados. 🖨️ QUALIDADE DE IMPRESSÃO DE ALTO PADRÃO • Papel adesivo vinílico • Sem relevo ou textura • Alta resolução com cores fiéis e riqueza de detalhes 🪵 ESPECIFICAÇÕES DA MOLDURA • Modelo caixinha (2 cm frontal x 1,5 cm profundidade) • Acabamento minimalista que valoriza a arte • Quadro completo, pronto para pendurar 🎨 CORES DE MOLDURA DISPONÍVEIS Preto, Branco, Marrom Claro (Freijó) e Marrom Escuro (Nogueira). 📏 DIMENSÕES (CADA QUADRO) Trio (3 peças) 30x45 cm - Ideal para espaços de 130 a 150 cm 40x60 cm – Ideal para espaços de 150 a 190 cm 50x70 cm – Ideal para espaços de 200 a 250 cm 60x90 cm – Ideal para espaços de 240 a 290 cm Duo (2 peças) 30x45 cm - Ideal para espaços de 90 a 120 cm 40x60 cm – Ideal para espaços de 120 a 150 cm 50x70 cm – Ideal para espaços de 160 a 180 cm 60x90 cm – Ideal para espaços de 180 a 210 cm Avulso (1 peça) 50x70 cm – Tamanho final aproximado: 52x72 cm 60x90 cm – Tamanho final aproximado: 62x92 cm 🛡 DURABILIDADE • As imagens não desbotam nem amarelam • Cores preservadas por muitos anos • Limpeza com pano seco 🔧 INSTALAÇÃO • Acompanha suportes metálicos serrilhados (brinde) • Recomendamos utilizar duas serrilhas por quadro, fixadas na parte traseira da moldura, a aproximadamente dois dedos de distância das laterais • Pendurar com parafusos e buchas 📌 Nos modelos sem vidro (mais leves), é possível utilizar pregos firmes. ❌ Não recomendamos o uso de fita dupla face. ‼️ A instalação é de responsabilidade do comprador. Recomendamos que seja feita com muito cuidado ou por um profissional, se preferir. 📦 EMBALAGEM REFORÇADA • Proteção contra impactos • Proteção contra umidade • Peças separadas individualmente, garantindo maior segurança ❓ DÚVIDAS FREQUENTES Rastreamento: pela Shopee (app ou site) Prazo de entrega: é informado antes da finalização da compra 🖥️ VARIAÇÃO DE CORES As cores podem variar até 15% conforme a tela do seu dispositivo, sem comprometer o resultado final da arte. 🖼 PRODUÇÃO PRÓPRIA / ENVIO RÁPIDO Transforme seu ambiente com arte de qualidade e acabamento profissional!', 149.9, 119.92, NULL, 'Home & Living > Decoration > Photo Frames & Wall Decoration', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m85b97fpxpu9d4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452488394%2F23093871507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
