INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29988014141', 'Kit 8 Lenço Umedecido Infantil Huggies Recém-Nascido Pacote Com 48 Unidades', 'Kit 8 Lenço Umedecido Infantil Huggies Recém-Nascido Pacote Com 48 Unidades Os Lenços Umedecidos Huggies Recém-Nascido foram desenvolvidos especialmente para a pele delicada dos bebês desde os primeiros dias de vida. Com uma fórmula segura e ingredientes suaves, garantem uma limpeza eficiente e cuidadosa, sem agredir a pele sensível dos recém-nascidos. Principais Características: - Fórmula exclusiva para recém-nascidos – Desenvolvida para peles sensíveis, sem álcool etílico, parabenos ou fragrâncias. - Tecnologia Puro e Natural – Com fibras naturais e ingredientes suaves que ajudam a proteger a pele do bebê. - Hipoalergênico e dermatologicamente testado – Seguro para uso desde os primeiros dias de vida. Benefícios: - Limpa com delicadeza sem agredir a pele do bebê. - Ajuda a manter a hidratação natural da pele. - Ideal para trocas de fraldas e higienização do bebê ao longo do dia. - Fácil de transportar e utilizar em qualquer momento. Diferenciais do Produto: - Indicado para recém-nascidos, incluindo bebês prematuros. - Livre de fragrâncias, álcool etílico e parabenos. - Textura extra macia e absorvente, proporcionando mais conforto na limpeza. Especificações Técnicas: - Peso: Aproximadamente 3 kg - Quantidade: 8 pacotes, cada um com 48 lenços Instruções de Uso: - Retire um lenço do pacote pelo lacre adesivo. - Passe suavemente sobre a pele do bebê para higienizar. - Após o uso, feche bem a embalagem para evitar o ressecamento dos lenços. - Descarte o lenço no lixo. Não jogue no vaso sanitário. Avisos e Precauções: - Uso externo. - Evite contato com os olhos. - Em caso de irritação, suspenda o uso e consulte um médico. - Manter fora do alcance de crianças. O que está incluso? - 8 pacotes de Lenço Umedecido Infantil Huggies Recém-Nascido, cada um com 48 unidades ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 154.59, 127.59, NULL, 'Mom & Baby > Bath & Body Care > Wipes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbfoja6v38u0e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F29988014141', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298096874', 'Creme de Barbear Pele Sensível Bozzano 65g', 'Creme de Barbear Pele Sensível Bozzano 65g Principais Características: - Fórmula Suave: Desenvolvida especialmente para peles sensíveis, a fórmula proporciona um barbear confortável e sem irritações. - Hidratação e Proteção: Contém ingredientes que hidratam e protegem a pele durante o barbear, prevenindo cortes e ressecamento. - Espuma Cremosa: Gera uma espuma densa e cremosa que facilita o deslizar da lâmina, proporcionando um barbear rente e eficaz. Benefícios: - Proporciona um barbear suave e confortável, ideal para peles sensíveis. - Hidrata e protege a pele, prevenindo irritações e cortes. - Facilita o deslizar da lâmina, garantindo um barbear mais rente e eficaz. Diferenciais do Produto: - Fórmula desenvolvida especialmente para peles sensíveis. - Alta performance com espuma cremosa e densa. - Testado dermatologicamente para garantir segurança e eficácia. Especificações Técnicas: - Peso: 65g Instruções de Uso: - Aplique uma quantidade adequada do creme nas áreas a serem barbeadas. - Espalhe uniformemente, formando uma espuma cremosa. - Prossiga com o barbear. - Enxágue bem após o uso. - Avisos e Precauções: - Evite contato com os olhos. - Em caso de irritação, descontinue o uso e consulte um médico. - Mantenha fora do alcance de crianças. O que está incluso? - 1 unidade de Creme de Barbear Pele Sensível Bozzano 65g ---DÚVIDAS FREQUENTES--- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 29.79, 22.69, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4aotqukr6lx97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560644869%2F23298096874'