INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493103693', '101 CURIOSIDADES CORPO HUMANO', '101 CURIOSIDADES CORPO HUMANO Você sabe qual é o maior músculo do corpo humano? E o menor? Tem curiosidade por descobrir um pouco mais sobre essa máquina perfeita, complexa e ainda cheia de mistérios? Então este livro é ideal para você! Vire as páginas e prepare se para embarcarneste universo surpreendente que é o corpo humano!. Informações Adicionais Autor: ALVES BARBIERI, PALOMA BLANCA Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: 101 CURIOSIDADES CORPO HUMANO Idioma: INDEFINIDO Páginas: 32 Edição: 1 ISBN-13: 9786555007428 ISBN-10: 6555007427', 16.55, 12.25, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbk6-lq0iaapd2d7q54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F22493103693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209710835', 'Café torrado e moído a vácuo tradicional 3 Corações', 'O Café 3 Corações Tradicional em Pó é perfeito para todas as situações. Há mais de 40 anos, oferece um sabor equilibrado e um aroma intenso, tornando seus momentos ainda mais especiais. Preparo: 1. Para cada litro de água, use de 4 a 5 colheres (sopa) de café 3 Corações tradicional. 2. Não deixe a água ferver. Ao primeiro sinal de borbulhas, despeje lentamente a água sobre o pó de café no centro do filtro ou coador, molhando todo o pó. Para preservar o aroma e o sabor do pó, guarde o pacote em um recipiente fechado e refrigerado.', 21.99, 13.99, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-825ag-mqnem1ya66fh73', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555128%2F58209710835', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20607533184', 'Brecha em Nossa Santidade | Kevin Deyoung', 'Brecha em Nossa Santidade A brecha em nossa santidade é a tendência de não darmos muita importância ao assunto da santidade ou pelo menos de não a compreendermos biblicamente Mas temos nossos motivos Talvez a busca pela santidade pareça ser algo pouco espiritual ou quem sabe você esteja tentando ser santo mas não está dando conta Qualquer que seja o caso o problema é claro poucos cristãos parecem se com Cristo e muitos parecem não estar preocupados com isso Este livro é para aqueles que estão prontos para levar a santidade a sério e buscar ser mais parecido com Jesus Este livro fala do poder de Deus para ajudar nos a crescer em nossa santidade pessoal e a nos alegrarmos no processo de nossa própria transformação Título Brecha em Nossa Santidade Autor Kevin Deyoung Páginas 208 Formato 14 x 1 2 x 21 cm Peso 0 240 kg ISBN 9786557230107 Editora Fiel', 51.97, 51.97, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/2e9b4e80c0a4135050b5aa410e2ce9eb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F20607533184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697605539', 'Tanqueray London Dry Gin 750ml', 'SOBRE O PRODUTO A marca favorita dos amantes de Gin London Dry, inspirado na mesma receita desde 1830, TANQUERAY London Dry® é o gin mais premiado na categoria. Perfeito para o preparo de drinks, é o gin preferido entre os bartenders dos 50 melhores bares do mundo. Presentear com gin é mostrar que conhece a personalidade da pessoa, e o Tanqueray é ideal para isso. A maior característica dessa bebida é se reinventar para cada nova geração de paladares, e o gin encontrou um novo público nos mais criativos drinks ao redor do mundo. Seus quatro ingredientes botânicos dão a nota do seu sabor inconfundível! Especificações País: Inglaterra Volume: 750ml Teor Alcoólico: 47,3%', 199.0, 114.74, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwx70bimjmine1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1009975506%2F22697605539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42329201082', 'Óleo de Tratamento Definição Natural 50ml', 'O Óleo de Tratamento Definição Natural é um óleo de cabelo que promove movimento, brilho ultra gloss e definição no dia a dia, mantendo a aparência natural dos fios com toque macio. Multifuncional, pode ser usado na finalização, umectação, pré-shampoo ou day after e ainda conta com proteção térmica de até 230 °C, ajudando a proteger e manter os cachos alinhados, definidos e cheios de brilho. <>INDICAÇÕES$& Para quais tipos de cabelo? Para cabelos ondulados, cacheados e crespos. Qual a indicação? Para cabelos sem brilho e nutrição. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Com Água de Coco, que repõe os nutrientes dos fios e potencializa a hidratação; Colágeno Vegetal, que auxilia no equilíbrio da oleosidade, promove força e brilho; Extrato de Hibisco, que hidrata, nutre e proporciona brilho; e Mix de Óleos, que revitaliza os fios e potencializa a nutrição e a hidratação capilar, garantindo cabelos mais saudáveis e luminosos. <>MODO DE USO$& Qual a melhor forma de usar? Com o cabelo seco ou úmido, aplique algumas gotas do óleo de cabelo na palma das mãos e espalhe bem do comprimento às pontas. Finalize como preferir.Sem enxágue. Sem enxágue. Multifunções: finalização, umectação, pré-shampoo e day after. Produto destinado a restaurar e proteger o cabelo das ferramentas de calor. <>CARACTERÍSTICAS$& É produto vegano? O Óleo de Tratamento Definição Natural não é vegano. É liberado? O Óleo de Tratamento Definição Natural não é liberado.', 21.0, 18.47, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260f-mlp4gfajowzl5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F42329201082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294687004', 'Par Esticador Regulador Corrente Suzuki Yes Intruder 125', 'Par Esticador de Corrente: A Solução para Manter sua Corrente de Moto em Perfeitas Condições Se você é um entusiasta das motos, sabe a importância de manter a corrente da sua moto devidamente esticada. É aí que o "Par Esticador de Corrente" entra em cena. Este acessório essencial é projetado para tornar o processo de ajuste da corrente da sua moto mais fácil e eficiente. Principais benefícios do nosso Par Esticador de Corrente: Ajuste Preciso: O par esticador é projetado para oferecer um ajuste de corrente preciso, garantindo que sua moto funcione de forma suave e eficiente. Facilidade de Uso: Não é mais necessário utilizar ferramentas complicadas ou gastar horas fazendo ajustes. O par esticador torna o processo simples e rápido. Durabilidade: Fabricado com materiais de alta qualidade, este acessório é construído para durar, resistindo ao desgaste e às condições adversas da estrada. Este par esticador é compatível com uma ampla variedade de modelos de motocicletas, tornando-o uma escolha versátil. Segurança: Manter a corrente de sua moto devidamente esticada contribui para um funcionamento seguro e evita desgastes prematuros de peças. Manutenção Eficiente: A manutenção adequada da corrente é essencial para a longevidade da sua moto, economizando dinheiro em reparos futuros. Detalhes do Produto: Ajuste Preciso da Corrente Fácil de Usar Durável e Resistente Compatibilidade Suzuki Yes AN125 - Todos os anos Mantenha sua moto em excelente condição!', 38.66, 38.66, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-821gg-mh23gzmmi51n2e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1410324