INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20198099924', 'Sofá Cama Estoril 1,90m Vermelho Suede Velut - King House', 'Dica Importante Gostou do produto, mas você tem preferência por outra cor ? Não tem problema, o sofá-cama Estoril está disponível 7 cores diferentes para que se adapte a qualquer ambiente e agrade a todos os gostos :) Materiais: Suede Velut Cores: Azul, Bege, Cinza, Marrom, Tabaco, Preto Vermelho Caso você tenha interesse em visualizar os anúncios de alguma das opções acima, basta efetuar uma busca de acordo com as opções descritas. Introdução ao Produto Sabe aquela sensação de felicidade e satisfação que você sente quando faz uma boa escolha ?! Pois bem, essa é a sensação de comprar um sofá-cama Estoril. Um produto moderno, com design elegante que combina com qualquer ambiente e o deixa ainda mais lindo e aconchegante. Seu sofá pode se transformar em uma verdadeira cama para assistir seu filme preferido. Não perca mais tempo e garanta já o seu sofá-cama Estoril! Características - Capacidade: 3 pessoas ou mais - Peso real suportado: 120kg por pessoa - Assento/encosto: espuma D28 - Pés Madeira: 12 cm Dimensões (Produto montado) - Altura: 0,46/1,01 m - Largura : 1,90m - Profundidade: 1,02 m - Profundidade aberto: 1,26 m Montagem A montagem do produto pode ser feita facilmente seguindo o manual de instruções que acompanha a embalagem do produto. Não é necessário técnico especializado. Garantia: 90 dias Informações Relevantes - É imprescindível ter ciência de que é possível que haja divergência de tonalidade nos tecidos devido às variações de configurações de monitores/telas; - Não nos responsabilizamos pelo transporte por escadas, elevadores, guincho ou içamento deste produto, qualquer despesa é de responsabilidade do cliente; - Verifique as dimensões do produto, certificando-se de que o mesmo possa ser transportado por portas, corredores e elevadores; - As imagens são meramente ilustrativas, podendo ter variação de tonalidades e não acompanham os objetos que decoram a imagem; - Não nos responsabilizamos pela instalação e montagem; - Prestamos assistência somente por defeitos de fabricação. Para quaisquer dúvidas adicionais, entre em contato com nosso SAC.', 1429.9, 1108.59, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7rep5-m82h80mlngyv79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F874507048%2F20198099924', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26489293675', 'Jogo Pastilhas Freio Traseiro Bosch Peugeot 308 2012 2013 2014 2015 2016', 'Jogo de Pastilhas de Freio Traseiro Bosch BB 362 *Confira a compatibilidade completa na descrição Frear com segurança faz toda a diferença no trânsito. E quando se trata de freio, confiança é essencial — por isso, conte com a qualidade da Bosch. - Frenagem eficiente com a tecnologia de fricção Bosch - Maior vida útil das pastilhas e menor desgaste do disco - Redução de ruído e vibrações - Sem amianto - Mais segurança e conforto para dirigir Compatibilidade: Peugeot 308 (1.6 i Flex) – 2012 a 2016 Reconhecida mundialmente pela tecnologia e durabilidade de seus componentes, a Bosch oferece pastilhas de freio desenvolvidas para diferentes condições de uso. A fórmula de atrito exclusiva garante desempenho constante, reduz o desgaste dos discos e proporciona frenagens mais suaves, sem abrir mão da durabilidade. Enviamos bem embalado, super rápido e com garantia de originalidade. Garanta o seu e confira os outros produtos da nossa Loja Koala Parts. Especificações técnicas: Material: Semi-metálico Com chanfradura: Não Aviso de desgaste: Sem Com molas: Não Com chapas de amortecimento: Não Com parafusos: Não Código Bosch: 0 986 BB0 290 Medidas: 87,1 x 52,8 x 14,9 mm (L x A x C) Conteúdo da embalagem: 1 jogo de pastilhas traseiras Bosch (4 peças)', 114.9, 114.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/sg-11134201-7rdyb-mcs1ww94koqo12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F288113309%2F26489293675', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998855434', 'Vinho Tinto Seco Brasileiro San Martin 750ml', 'Vinho Tinto de Mesa San Martin Bordô Seco 750 ml O Vinho San Martin Bordô Seco é um clássico da vitivinicultura brasileira, produzido com a uva Bordô, conhecida por sua intensidade e caráter marcante. De coloração rubi profunda, apresenta aromas frutados envolventes e um paladar encorpado e seco, que conquista apreciadores de vinhos mais robustos. Na versão garrafa de 750 ml em vidro, une praticidade ao charme tradicional, ideal para refeições em família, encontros especiais ou para apreciar no dia a dia. Harmoniza muito bem com carnes vermelhas, massas ao molho encorpado, queijos curados e pratos típicos brasileiros, realçando os sabores e proporcionando experiências únicas à mesa. Sabor intenso e seco, com boa estrutura Aroma marcante de frutas escuras Garrafa de 750 ml em vidro Ideal para harmonizações mais robustas O San Martin Bordô Seco 750 ml é a escolha certa para quem valoriza tradição e qualidade em cada taça.', 39.0, 34.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-824gf-me7mz2f5mzuraf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306254852%2F23998855434', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
