INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997243788', 'Kit Protetor Labial Hidratante + Máscara Labial Noturna + Esfoliante Labial (3 Produtos)', 'Protetor Labial Hidratante Fps30: o Protetor Labial Hidratante da Linha de Skincare Océane Chega com Muitas Propriedades e Benefícios para Os Lábios. Esse Lip Balm É Um Produto Multifuncional, É Um Hidratante Labial com Proteção, Ele Trata e Oferece Proteção Contra Os Raios Uvb. com Fps 30, Ele Protege Contra Os Raios Solares, Dá Brilho e Possui Uma Textura Bálsamo, Leve, Confortável e Fácil de Aplicar. Vale Destacar Que É Um Produto Vegano e Ainda Livre de Parabenos. Esfoliante Labial: Este Esfoliante Labial à Base de Açúcar Remove As Células Mortas e Deixa Os Lábios com Um Toque Especial. A Esfoliação Auxilia No Estímulo da Renovação Celular e Deixa Os Lábios Mais Macios e Lisinhos, sem Agredir a Pele. Sua Propriedades Vão Além e São Reforçadas Graças à Agentes Condicionadores Nutritivos e Hidratantes, Como Óleo de Macadâmia. Tenha Lábios Saudáveis em Poucos Instantes! Máscara Labial Noturna: Esta Máscara Labial Noturna É a Solução Perfeita para Amanhecer com Os Lábios Macios e Viçosos. Enriquecida com Antioxidantes, Especialmente do Óleo de Grapefruit, Revigora Os Lábios e Deixa-Os Macios Ao Toque. Contém Também Cera de Abelha, Que Hidrata a Pele e Ajuda a Remover Células Mortas. Sua Textura de Bálsamo Proporciona Uma Melhor Absorção Dos Seus Ingredientes Nutritivos. O Kit Protetor Labial Hidratante + Máscara Labial Noturna + Esfoliante Labial Contém: - 1 Esfoliante Labial Hidratante - Lip Scrub 15g - 1 Máscara Labial Noturna - Lip Sleeping Mask 15g - 1 Protetor Labial Hidratante - Lip Balm Fps30 10g', 169.9, 159.9, NULL, 'Beauty > Skincare > Face Mask & Packs', 'https://cf.shopee.com.br/file/sg-11134201-825ak-mqrwk96awqgyea', 'https://shope.ee/an_redir?origin_link=ht