INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893722402', 'Lápis preto Pitt Grafite Matt 4B Faber-Castell', 'O lápis Pitt Graphite Matt é uma escolha inovadora para artistas e desenhistas que buscam um grafite de alta qualidade com acabamento ultramate. Desenvolvido com tecnologia exclusiva, este lápis reduz significativamente os reflexos da luz no traço, proporcionando maior profundidade e contraste nos desenhos. Detalhes: - Graduação 4B - Ideal para escrever, desenhar e esboçar - Proporciona uma camada de cobertura ultra opaca, reduzindo o brilho do grafite no papel', 29.3, 25.5, NULL, 'Stationery > Writing & Correction > Pencils', 'https://cf.shopee.com.br/file/sg-11134201-7rcby-m6gum7h6n32s25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F479054821%2F22893722402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
