INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29092881978', 'Jacques Janine Hair Care Pistache Shampoo 450ml Condicionador 440ml Máscara 400g + Spray 120ml', 'Kit Jacques Janine Hair Care Pistache – Shampoo 450ml + Condicionador 440ml + Máscara 400g + Spray Leave-in 120ml O Kit Jacques Janine Hair Care Pistache oferece uma rotina completa de cuidados para proporcionar hidratação, nutrição, brilho e proteção aos fios. Desenvolvido para tratar e proteger os cabelos no dia a dia, ajuda a manter os fios macios, alinhados e com aparência saudável. A combinação de shampoo, condicionador, máscara e spray leave-in proporciona limpeza suave, tratamento intensivo e finalização com proteção térmica. Contém: Shampoo 450ml – Limpa suavemente os fios sem ressecar, preparando os cabelos para o tratamento. Condicionador 440ml – Auxilia no desembaraço e na hidratação, deixando os fios mais macios e alinhados. Máscara de Hidratação 400g – Tratamento intensivo que promove nutrição, brilho e maciez. Spray Leave-in 120ml – Finalizador com proteção térmica que ajuda a proteger os fios contra o calor de secador e chapinha. Benefícios: Hidratação e nutrição capilar Mais brilho e maciez Auxilia no controle do frizz Proteção térmica para os fios Facilita o desembaraço Cabelos mais alinhados e com aparência saudável Modo de uso: Lave os cabelos com o shampoo e enxágue bem. Aplique a máscara no comprimento e pontas, deixe agir de 5 a 10 minutos e enxágue. Use o condicionador para selar os fios e enxágue. Finalize com o spray leave-in nos cabelos úmidos ou secos. Resultado: Cabelos limpos, hidratados, macios e protegidos, com brilho natural e aparência saudável.', 142.9, 109.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8257s-mfsduel46jgv26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248946294%2F29092881978', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
