INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20897758950', 'Kit Laptop Infantil Educativo Candide Barbie Bilíngue + 1 Fidget Spinner Sortido', 'Os laptops infantis são uma febre entre a criançada, eles amam imitar seus pais fingindo que estão trabalhando como eles, eles também levam para a escola e mostram para seus amigos e se divertem muito com isso. O Laptop Candide é educativo, bilíngue (português e inglês) e vem com diferentes atividades, sendo elas: música, letras, palavras, ortografia, perguntas e respostas, soma, divisão e outros. São inúmeras atividades para a garotada aprender onde estiver. Você pode aprender brincando com o laptop infantil educativo da Barbie! Esse fashion laptop de brinquedo possui um lindo design inspirado nas suas bonecas favoritas! As brincadeiras vão ficar muito mais divertidas com o laptop da Barbie!FIDGET SPINNER ORIGINAL A febre do momento! O fidget spinner é um brinquedo que auxilia no alívio de estresse. É composto de um rolamento central e um desenho com 3 extremidades feitas em materiais como aço inoxidável, titânio, cobre e/ou plástico. O brinquedo tem sido anunciado como algo que ajuda as pessoas que têm dificuldade para se concentrar ou que são inquietas (tais como TDAH ou ansiedade), agindo como um mecanismo de liberação de energia nervosa ou estresse. Obs : Não é possível escolher a cor, será enviado 1 unidade da cor disponível. FIDGET SPINNER ORIGINAL A febre do momento! O fidget spinner é um brinquedo que auxilia no alívio de estresse. É composto de um rolamento central e um desenho com 3 extremidades feitas em materiais como aço inoxidável, titânio, cobre e/ou plástico. O brinquedo tem sido anunciado como algo que ajuda as pessoas que têm dificuldade para se concentrar ou que são inquietas (tais como TDAH ou ansiedade), agindo como um mecanismo de liberação de energia nervosa ou estresse. Obs : Não é possível escolher a cor, será enviado 1 unidade da cor disponível.', 98.98, 98.98, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdwk-lxwzcbb0a7wqac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F20897758950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
