INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250065670', 'colher de silicone com cabo de madeira resistente para cozinha - oikos', '"conheça a colher de silicone com cabo de madeira da oikos! prática: um item essencial para quem gosta de cozinhar com facilidade. ótima para mexer, raspar e espalhar pequenas porções com total controle! possui silicone duplo: resistência em dobro na hora de preparar as mais variadas receitas. além de não reter cheiro, o silicone é flexível, resistente e não conduz calor. não danifica a panela: o utensílio escorrega pelas superfícies sem deixar um arranhão. faz mágica na cozinha! fácil de limpar: lave em água corrente com esponja. para eliminação de bactérias é só limpar com sabão neutro. material: silicone, nylon e madeira. leve qualidade e modernidade para sua casa! medidas: comprimento: 7,3cm largura: 1,5cm altura: 29,5cm"', 56.9, 37.9, NULL, 'Home & Living > Kitchenware > Spatulas & Cooking Tweezers', 'https://cf.shopee.com.br/file/sg-11134201-8260b-mlgogjc64r2ad1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F58250065670', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
