INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399682155', 'Ventilador Circulador Britânia 30W 3 Velocidades BCA25A', 'Sinta a brisa fresca e relaxante em seu ambiente com o Ventilador Circulador Britânia 30W 3 Velocidades BCA25A! Imagine um dia quente e abafado, você chega em casa e liga seu ventilador Britânia BCA25A! Em poucos segundos, uma brisa suave e refrescante toma conta do ambiente, proporcionando uma sensação de relaxamento imediato. Com 3 velocidades, você escolhe a intensidade ideal para cada momento. Seja para um sono tranquilo ou para se concentrar no trabalho, o ventilador se adapta às suas necessidades. Tudo isso, com tecnologia Maxx Force, que garante um alto desempenho, mesmo sendo um ventilador compacto. Suas 3 pás de 23cm proporcionam uma ventilação potente e uniforme, enquanto o motor super silencioso garante um ambiente tranquilo e agradável. Com o ventilador Britânia BCA25A super silencioso, você transforma qualquer espaço em um refúgio de frescor e tranquilidade! • 3 velocidades • Hélice de 3 pás • Potência de 30W • Grade que atende às normas de segurança (contato com partes móveis).', 139.9, 84.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-823ou-mpcl3nui7eoe27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811879342%2F19399682155', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999190719', 'Mixer Britânia Lâminas Pro Maxx 2 em 1 350W BMX360', 'Que tal atingir a melhor textura nas suas receitas? Para isso, o Mixer Britânia BMX360 2 em 1 350W é a escolha ideal! São 350W de potência, ideal para preparar receitas das mais elaboradas até as mais simples. Por ser 2 em 1, pode ser usado como mixer ou como processador de alimentos, assim você ganha muito mais versatilidade para os preparos na sua cozinha! Com 1 velocidade + função pulsar, o Mixer Britânia BMX360 entrega alta performance para misturar e triturar até os alimentos mais difíceis. Além disso, o mixer é equipado com lâminas Pro Maxx em aço inox com altíssimo poder de trituração, resultando em maior resistência e durabilidade do seu produto. E se não bastasse, o Mixer Britânia possui um design ergonômico! Sendo assim, o corpo é desmontável e facilita muito na hora da limpeza e do armazenamento. Sua cozinha precisa e você merece um Mixer Britânia BMX360 2 em 1 350W! Design Ergonômico 1 velocidade Acompanha Lâmina, copo e processador Lâmina em inox - Pro Maxx Corpo desmontável Mixer 2 em 1 – Mixer e processador de alimentos.', 249.9, 249.9, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/sg-11134201-81zwt-mmw2cjs44pvp8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F811879342%2F21999190719', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23407015631', 'Armário de Cozinha Completa de Canto com Rodapé Veneza Multimóveis MP2105.898 Preto/Branco', 'A Cozinha Completa de Canto com Rodapé Veneza Multimóveis MP2105 com Armário e Balcão tem um excelente custo benefício e um amplo espaço interno. Produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), rodapés, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos de canto podem ser montados dos dois lados (esquerdo ou direito), conforme a sua preferência. Esta cozinha conta, ainda, com balcão com tampo removível (compatível com pia de 120 cm) com 1 gaveta e 2 portas e balcão para cooktop (o recorte do tampo deve ser realizado na hora da montagem conforme a medida do seu fogão) com 1 gaveta e 1 porta. Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. Para deixar sua cozinha mais bonita e organizada, possui espaço para forno e microondas, além de compartimento especial para utensílios mais altos. Conteúdo da Embalagem: 2 (dois) armários aéreos 70cm 1 (um) armário aéreo de canto 90cm 1 (um) armário aéreo 120cm 1 (um) balcão com tampo 70cm 1 (um) balcão com tampo de canto 90cm 1 (um) balcão com tampo 120cm 1 (um) armário para forno e microondas 62cm 1 (um) kit com rodapés Dimensões do produto montado: Altura: 203cm | Largura: 230 x 234cm | Profundidade: 32cm (aéreos) - 53cm (balcão com tampo e paneleiro) *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 3719.9, 2599.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvcs-li0hxqw99sz2b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F23407015631', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17090249955', 'Cozinha Completa Multimóveis Veneza GB FG3715 com Armário e Balcão Preta', 'A Cozinha Completa 5 peças com Armário e Balcão FG3715 Veneza Multimóveis tem um excelente custo benefício e um amplo espaço interno. Produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), pés retrô em polipropileno, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. O balcão possui tampo removível (compatível com pia de 120 cm). Para deixar sua cozinha mais bonita e completa possui vidro reflecta, compartimento especial para utensílios mais altos, balcão para cooktop, além de espaço para forno e microondas. Conteúdo da Embalagem: 1 (um) armário aéreo 120cm 1 (um) balcão com tampo 120cm 1 (um) armário aéreo 70cm 1 (um) balcão com tampo 70cmcm 1 (um) paneleiro 62cm Dimensões do produto montado: Altura: 203cm | Largura: 252cm | Profundidade: 31cm (aéreos) - 53cm (paneleiro e balcão com tampo) *Você pode consultar as medidas internas na imagem técnica do produto. Disponível nas cores: Branco - Preto Acetinado Texturizado *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem..', 2239.9, 1439.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvfj-lhz3v17v4iy6fe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F17090249955', NU