INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200101621', 'Notebook ASUS Vivobook 16 X1605VA Intel Core i7 1355U 8Gb Ram 512Gb SSD Linux Tela 16” IPS FHD MB742', '*** ATENÇÃO *** Sistema operacional Linux, não vem com o sistema Windows. Tudo se torna mais fácil com o poderoso ASUS Vivobook 16, o notebook repleto de recursos imersivos e visuais! Ele vem com tela nível IPS de 16 polegadas, resolução WUXGA (1920x1200) e proporção 16:10. Conta também com dobradiça plana de 180° para facilitar o seu dia a dia, tampa de proteção física da webcam para garantir sua privacidade e teclas de função dedicadas para ligar ou desligar o microfone e a câmera. Part Number: 90NB10N2-M00XZ0 SKU ASUS: X1605VA-MB742 EAN Code: 7908737300017 Código de homologação Anatel: 00595-18-04423 Processador Intel Core i7 1355U 3,7 GHz, 12 MB Cache Memória RAM: 8 GB (8 GB OnBoard + 0 GB OffBoard) Armazenamento: 512 GB SSD Tela 16,00" LCD LED Backlight, Nível IPS, Anti-Glare, 16:10 Resolução da Tela: 1920x1200 Placa de Vídeo: Intel UHD Graphics Garantia: 12 meses Tela Sensível ao Toque: Não Clock de Memória: 3200 MHz Wi-Fi 5(802.11ac)+Bluetooth 5.1 (Dual band) 1*1 Tipo da Placa de vídeo: Integrada Teclado retro iluminado: Não Câmera Frontal: HD Bluetooth 5,1 Áudio: SonicMaster Alto-falantes embutidos Microfone embutido Saídas: 1x USB 2.0 Type-A 1x USB 3.2 Gen 1 Type-C com suporte a power delivery 2x USB 3.2 Gen 1 Type-A 1x HDMI 1.4 1x 3.5mm Combo Audio Jack 1x DC-in Adaptador de Energia: 45,00 W Bateria 3 Cells / 4000 mAh Sistema Operacional: KeepOS Características: Tela com maior com resolução 1920x1200 16:10 Peso do Produto: 1,88 Kg Dimensões:35,87 cm X 24,95 cm X 1,99 ~ 1,99 cm', 4689.0, 4689.0, NULL, 'Computers & Accessories > Laptops', 'https://cf.shopee.com.br/file/sg-11134201-82593-mgdtucjwn5laba', 'https://shope.ee/an_redir?origin_link=https%3A%