INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255207552', 'Calça Infantil Motocross Pro Tork Hero 2026', 'Esta é a versão infantil da Calça Hero 2026, mais uma opção da Pro Tork para a prática do motociclismo off road. O modelo é fabricado em tecido 100% poliéster, com forro ventilado, fechamento por zíper tratorado e botões, além de possuir regulagens na cintura, conferindo o ajuste ideal. Uma excelente opção para quem curte acelerar com estilo, conforto e segurança. Especificações: - 100% Poliéster; - Forro interno ventilado; - Fechamento por zíper tratorado e botões; - Regulagens na cintura, conferindo o ajuste ideal; - Costura dupla reforçada; - Modelagem anatômica; - Marca: Pro Tork. Dica: - Recomendamos a compra de um número maior do que o utilizado para roupas casuais. Exemplo: Se você veste 14, adquira o tamanho 16. Observação: - Imagem ilustrativa: Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento da foto e a calibração de cores da tela do seu monitor ou aparelho.', 210.42, 204.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/sg-11134201-8262r-mko5l8bol81u3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F58255207552', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
