INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23391057046', 'Kit Carenagem Peças Plásticas Cromo Forte 3 Peças Biz 125 2006 2007 2008 2009 2010', 'As Carenagens e Peças plásticas Cromo Forte são produzidas nos moldes das peças originais da moto, descartando qualquer tipo de adaptação. Fabricado em ABS 100% virgem, as carenagens Cromo Forte são extremamente resistentes aos raios UV, tornando-se assim o melhor custo-benefício do mercado. Características: - Marca: Cromo Forte; - Modelo: Original; - Tonalidade de cores semelhante ao original; - Moto compatível: Biz 125 2006 a 2010 (Confira a relação de cores e anos abaixo). Aplicação: - Azul Saira: 2006; - Vermelho Caruaru: 2006; - Prata Appaloosa: 2006 e 2007; - Preto: 2006, 2007, 2008, 2009 e 2010; - Azul Twister: 2007; - Vermelho Guarau: 2007; - Amarelo Topázio: 2008 e 2009; - Prata Lumiar: 2008 e 2009; - Vermelho Maceió: 2008 e 2009. - Vermelho Cardeal: 2009; - Bege Cítrico: 2010; - Rosa Ágata: 2010; Componentes do Kit: - 1 Bico Frontal; - 1 Carenagem do Farol; - 1 Paralama Dianteiro. Atenção! - Devido ao desgaste da pintura da motocicleta com o passar do tempo, pode haver uma pequena divergência na tonalidade das cores. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada.', 399.9, 221.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lmoq54zjl9tid6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F23391057046', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
