INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256767359', 'Leite Vegetal Aveia Naveia Original Extra Fibra 1L Sem Lactose', 'Há quem defina nosso Original Extra como o deleite que fala mais grosso. Mas muita calma nessa hora: é que ele tem uma textura mais encorpada, um jeitão denso de quem adora causar novas sensações. No fundo, ele é um Naveia raiz: dá com tudo, naturalmente docinho, sem açúcar como ingrediente. Com café, com mate, com fruta, no drink - tudo fica mais uaaauu e encorpado. E claro, puríssimo. Quem tomou já sabe que extra cremosidade rima com extra felicidade.', 23.9, 20.81, NULL, 'Food & Beverages > Beverages > Non-dairy Milk', 'https://cf.shopee.com.br/file/br-11134207-820mh-mqm84dnd37yb1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1729403374%2F58256767359', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
