INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10814004151', 'Livro - Diário de um nerd - Livro 2', 'Phil, o Nerd, se prepara com seus amigos para viajar para Hollywood, onde vai conhecer os estúdios de clássicos do cinema e participar de um programa de talentos da TV. Mas seu novo professor, que odeia nerds, está disposto a acabar com a fama de nerd de Phil. Será que ele conseguirá vencer o programa de talentos e convencer o professor de que os nerds são legais?_x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 2, 2019_x000D_ Autor: Philip Osbourne_x000D_ Idioma: Português_x000D_ Páginas: 160_x000D_ Dimensões: L 13.50 x A 20.30 x E 0.90_x000D_ ISBN: 9788538091677', 24.9, 24.9, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-23010-bb77iz46xtlv8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F10814004151', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11313488252', 'Livro - Contos de fadas dos irmãos Grimm - Principis', 'Reconhecidos mundialmente pela qualidade dos contos que produziram desde o começo do século XIX, os irmãos Grimm diziam estar só escrevendo as histórias que escutavam de camponeses e amigos. Concomitantemente aos registros do cotidiano, começaram a pesquisar documentos e recolher histórias da Alemanha para a preservação da memória e das tradições populares. Neste livro encontram-se contos fantásticos que mantêm viva a memória da criação folclórica da população alemã. Editora: Principis Edição: 1, 2019 Autor: Irmãos Grimm Idioma: Português Páginas: 304 Dimensões: L 16.00 x A 23.00 x E 1.70 ISBN: 9788594318909', 29.9, 29.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/3ef976c0f07a9637ff92bab650dc677f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F11313488252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
