INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19797691420', 'Superwoman vol 02 - Panini', 'A Superwoman está em uma encruzilhada. Suas lembranças estão fora de sincronia com o mundo, seus superpoderes estão drenando sua vida pouco a pouco e a única esperança de sobrevivência é abrir mão de sua neófita carreira como super-heroína. E enquanto Lana lida com seus demônios internos e externos, novas ameaças monstruosas seguem ferindo aqueles mais próximos. Com ou sem poderes, a Superwoman não terá outra opção a não ser dar tudo de si para mudar o trágico destino da cidade de Metrópolis!', 19.0, 19.0, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rd72-lvuboe6svujp56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F19797691420', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253827612', 'Relógio Seculus Masculino Analógico Digital Esportivo Casual Preto Pulseira Em Silicone Prova D''água100 Metros Original', 'Com aro interno em relevo 3D, a coleção Steel Diver impressiona pelo visual robusto e moderno. Este modelo traz caixa em aço dourado com visor preto e função anadigi, unindo o clássico e o digital em um único acessório. A pulseira em silicone preto, com acabamento texturizado, oferece conforto e resistência, complementada por fecho de fivela que garante praticidade no dia a dia. Recursos do Modelo: Possui a Coroa Rosqueada; Formato 12/24hrs; Calendário Com: Dia do mês: de 1 a 31; Mês do ano: de 1 (Janeiro) a 12 (Dezembro); Dia da semana: de Monday a Sunday; Alarme; Cronômetro. Especificações do Relógio: Marca: Seculus; Modelo Referência: 77140GPSVDU4; Gênero: Masculino; Mecanismo: Quartz e Digital; Cor da Caixa: Dourado; Cor da Pulseira: Preto; Cor do Mostrador: Preto; Cor do Bisel: Preto; Material da Caixa: Aço Inoxidável; Material da Pulseira: Silicone; Tipo do Vidro: Cristal Mineral; Fecho: Fivela Simples. Dimensões: Espessura Caixa: 15.4mm; Diâmetro Caixa Com a Coroa: 51.2mm; Diâmetro Caixa Sem a Coroa: 47.8mm; Diâmetro Visor: 38.7mm; Largura Pulseira: 22.2mm; Largura Pulseira Base: 22.2mm; Circunferência da Pulseira: 21cm; Circunferência Pulseira com a caixa: 28cm; Peso sem a embalagem: 125g; Peso da caixa com relógio: 411g; Fundo do relógio: Rosqueado. Conteúdo da Embalagem: 1 Relógio Seculus Original; 1 Certificado de Garantia de Fábrica (2 ano); 1 Caixa Original Seculus. Perguntas Frequentes: Somos a Loja Oficial da Relojoaria Wenus; Tamanho: Grande; Possui coroa Rosqueada; Produto: Original; Acompanha Nota Fiscal; Pronta Entrega Disponível; Não Possui Catraca Giratória; Possui Visor noturno na cor verde; Possui efeito fosforescente presentes em seus ponteiros e marcadores; Nossos Clientes contam com uma equipe de especialistas altamente qualificados para atender todas as suas necessidades. Resistência à Água - 10 ATM: Adequado para a maioria dos desportos aquáticos como a vela, o mergulho e a natação em águas pouco profundas. Não adequado para mergulho com ar comprimido. Atenção e Cuidados Não usar o relógio durante o banho, pois os produtos que são utilizados durante o banho podem comprometer a vedação do seu relógio. Certifique-se de que a coroa está totalmente encaixada antes do contato com a água. Nunca pressione botões ou ajuste a coroa enquanto o relógio estiver molhado ou em contato com à água. Após exposição à água salgada, enxágue o relógio em água doce e seque-o completamente. Não exponha o relógio à água quente ou morna, pois isso pode afetar a vedação e reduzir sua resistência à água. Ideal para o homem que valoriza estilo, desempenho e presença marcante. Invista em um relógio que combina resistência, design arrojado e funcionalidade para te acompanhar em todos os momentos. Garanta já o seu e eleve o seu visual com atitude! Garantia de fábrica: 24 meses', 787.85, 415.6, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/br-11134207-820lg-mqouapa8q0aqb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F327120468%2F58253827612', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
