INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399650221', 'Constituição da República Federativa do Brasil - 56ª Edição 2025', 'Esta Constituição da República Federativa do Brasil consolida cinco décadas de tradição do Grupo Editorial Nacional | Editora Atlas na publicação de livros jurídicos. Confiantes em superar os constantes desafios, entregamos ao público um material consistente, funcional e atualizado, com um projeto gráfico prático e moderno, que permite a otimização na busca de informações. Trata-se de legislação criteriosamente selecionada e organizada para atender a estudantes, candidatos a concursos públicos, técnicos e profissionais do Direito e das mais diversas áreas do conhecimento. Aos adquirentes desta 56ª edição da Constituição da República Federativa do Brasil, é oferecido material suplementar exclusivo e gratuito para download, com a íntegra das Emendas Constitucionais de Revisão e das Emendas Constitucionais de 1 a 135. Além disso, o GEN disponibiliza para seus leitores um acompanhamento legislativo on-line, com informações sobre as normas de maior impacto nos principais ramos do Direito brasileiro, bem como aquelas que alterem os dispositivos legais contidos nesta obra, publicadas ao longo do ano. ?', 116.66, 116.66, NULL, 'Books & Magazines > Books > Politics, Law & Social Sciences', 'https://cf.shopee.com.br/file/sg-11134201-7rd3t-m7kuek879i7sc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F20399650221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
