INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897553814', 'No Game No Life - Livro 03', '“Disboard”... O mundo em que tudo se resolve com games. Os irmãos gamers, agora reis dos imanities – Sora e Shiro – desafiaram o terceiro maior reino do mundo, a Federação Oriental, para uma disputa valendo todo o território continental deles contra... O “direito por toda a raça imanity”! Porém, antes da disputa começar, Sora desaparece, deixando apenas palavras no ar. O gênio gamer Kuuhaku, dois que são um, estão separados. Sora está desaparecido e só Shiro pode salvar toda a humanidade! E o que acontecerá no paraíso das furries? A batalha contra os werebeasts chega à sua conclusão... Pisando em gelo fino, a conspiração vai ficando mais clara no terceiro volume desta aventura de um mundo de fantasia!', 25.93, 25.93, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rd64-lw0bd24hlldvb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23897553814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14609111078', 'Silicone perfumado spray lavanda luxcar 300ml proteção para plástico borracha madeira inox e vinil', 'Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há quase duas décadas, nosso estoque conta com uma variedade de 45000 itens. Todos os nossos produtos são novos, originais e com garantia._x000D_ _x000D_ 300 ml_x000D_ O Silicone Perfumado Spray Luxcar é um produto multiúso, ideal para lubrificação e proteção de diversas superfícies metálicas e não metálicas._x000D_ _x000D_ Vantagens:_x000D_ • Protege plásticos, metais, borrachas e vinil._x000D_ • Reduz o atrito, desgastes e ruídos._x000D_ • Lubrifica trilhos, fechaduras, dobradiças, etc._x000D_ • Excelente desmoldante para injeção termoplástica._x000D_ _x000D_ Modo de usar:_x000D_ Agite bem a embalagem, antes e durante o uso e aplique o produto no local desejado e em seguida espalhe com um pano limpo para um perfeito acabamento. Para locais de difícil acesso utilize o bico extensor. Obs.: não aplique sob a superfície úmida, pois poderá esbranquiçar._x000D_ _x000D_ Validade 24 meses.', 37.0, 37.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/eac57cd8ff82695b3772d38339373d9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549478150%2F14609111078', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10653903171', 'Kit com 4 livros - 365 Palavras Cruzadas Plus', 'Kit com 4 Livros - 365 Palavras Cruzadas Plus._x000D_ _x000D_ _x000D_ 365 Palavras cruzadas plus - volume I_x000D_ 365 Palavras cruzadas plus - volume II_x000D_ 365 Palavras cruzadas plus - volume III_x000D_ 365 Palavras cruzadas plus - volume IV_x000D_ _x000D_ _x000D_ Fazer palavras cruzadas é uma forma criativa e divertida de desenvolver o raciocínio, deixar o pensamento mais ágil e enriquecer o vocabulário, além de você se manter atualizado sobre diversos assuntos._x000D_ Editora: Ativamente_x000D_ Edição: 1, 2021_x000D_ Autor: Ciranda Cultural_x000D_ Idioma: Português_x000D_ Páginas: 288 cada livro_x000D_ Dimensões: L 15.60 x A 23.00 x E 1.50_x000D_ ISBN: 9786555005127_x000D_ 9786555005431_x000D_ 9786555006902_x000D_ 9786587466095', 79.6, 39.8, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/f2745aa99934e30de608173c1cbc39da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F10653903171', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19535136853', 'Kit com 2 Desinfetante Pinho Sol Original 500ml Cada', 'PINHO SOL® – ORIGINAL Elimina 99,9% das bactérias, germes e fungos Pinho Sol Original é um desinfetante que limpa e elimina 99,9% das bactérias/ germes e fungos*. Além disso, possui um delicioso perfume de Pinho, deixando a sua casa sempre limpa protegida e com um agradável perfume que dura por muito mais tempo. Use em todos os cômodos da casa e em diversas superfícies como: vaso sanitário, ralo, pia, tanque, azulejos e pisos. Quer saber como usar? É fácil: – Para desinfecção, utilize o produto puro e deixe-o agir em contato com a área por 30 segundos. – Para limpeza geral de superfície, dilua 2 colheres de copa (30ml) por litro de água. Seguindo essa instrução, o produto rende até 16 litros. – Para lavar roupa utilize um copo americano (200ml) de Pinho Sol com sabão ou detergente em um tanque ou máquina de lavar cheios de água. Para manchas, basta umedecer a parte suja com Pinho Sol e colocar a peça na máquina de lavar ou tanque. 1.75 L – Rende até 87 litros 1L – Rende até 50 litros. 500ml – Rende até 25 litros. Disponível nos tamanhos: 1.75L, 1L e 500ml', 26.79, 26.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/e05f081f0e865be51449f92cb4fa8272', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F19535136853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
