INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19598032204', 'Finalizador de Roupas Finisherfresh Requinte 1L Spartan', 'Finalizador de Roupas Finisherfresh Requinte 1L Spartan Facilitador para passar roupas e tecidos de fibras naturais e sintéticas presentes em toalhas, lençóis, edredons, cobertores, cortinas, entre outros, eliminando a aspereza e otimizando o efeito de passadoria, deixando os tecidos macios e perfumados por longos períodos. Indicação de Uso: - É indicado para roupas domésticas e profissionais. Modo de uso: - Uso puro pulverizando sobre o tecido, ou dentro do saco plástico de embalagem. - Caso queira uma menor intensidade do perfume na roupa, diluir o produto até 1:10 em água. PH: 5,5 - 7,5 Diluição: até 1:10 Fragrância: Requinte Embalagem: 01 frasco de 1L', 54.11, 54.11, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-7rccw-m6hbb4wuq6xm2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F19598032204', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
