INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207402903', 'Chave Roda Baixar Estepe Fiat Palio Wekkend Fase 3 e 4', '51861135 Chave Roda Baixar Estepe Fiat Palio Wekkend Fase 3 e 4. Envie todas as suas dúvidas antes da compra. Consulte nosso especialista online através do campo Perguntas e Respostas. Caso precise de informações sobre aplicação sempre informe o n° do Chassi do veículo, que se encontra no documento. Dê preferência para peças originais e negócios legítimos. O Grupo Barigui possui mais de 60 lojas e está há mais de 25 anos comercializando peças automotivas genuínas, novas e originais. Somos uma Concessionária Autorizada Fiat do GRUPO BARIGUI. Fotos reais do produto que esta sendo vendido, de autoria do Grupo Barigui. A cópia sem autorização será denunciada. Não nos responsabilizamos por defeitos recorrentes a má instalação. Procure sempre um profissional qualificado.', 63.94, 63.94, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Wrench', 'https://cf.shopee.com.br/file/sg-11134201-7rdxi-mcadlqwatzog45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1643586584%2F58207402903', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897759198', 'Colchão King Mola Ensacada Guldi Firme (25x193x203) Azul e Branco', 'Que tal o Colchão Guldi Original?Muito importante para uma rotina saudável, descansar bem renova as energias e nos mantêm ativos para enfrentar todas as tarefas do dia. E para que a sua experiência seja única, o Colchão Guldi reúne características que fazem dele o companheiro perfeito para a sua cama. Com molas ensacadas individualmente, ele permite a movimentação sem atrapalhar quem eventualmente estiver dormindo ao lado, enquanto o revestimento confere um toque agradável ao fazer contato com o corpo. Outro diferencial é que ele é embalado a vácuo, tornando o primeiro transporte simplificado. Ah, para garantir uma maior durabilidade, deixe a peça arejar após retirar a embalagem e procure limpar apenas com pano seco. Viu como é fácil conquistar o colchão dos seus sonhos? ;) Cor: Azul Garantia em Meses: 60 Cores do Produto: Branco Instruções/Cuidados: Deixar o Colchão para Arejar Após Remoção da Embalagem; Limpar com Pano Seco Conteúdo da Embalagem: 1 Colchão - Entregue em: 1 Volume - Enrolado Modelo: Guldi Original Firme Número de Volumes: 1 Material: Composto por molas ensacadas individualmente e espuma de 5 cm + 2 cm de espuma D33 com alta resiliência em 100% poliuretano. Possui 215 molas por metro quadrado, revestimento em malha 53%, poliéster 47%, viscose gramatura 277 g/m². O produto é embalado à Material para Filtro: Mola Ensacada Descrição do Tamanho: Altura: 25 cm Largura: 193 cm Profundidade: 203 cm Altura do Produto (cm): 25 Largura do Produto (cm): 193 Comprimento do Produto (cm): 203 Peso do Produto (Kg): 44.2 Produto precisa de Montagem?: Não Revestimento: Malha Título do Vídeo: Guldi Original Linha de produtos: Guldi Acabamento: Tecido Tendências: Minimal Pop Densidade da espuma: D33 Material do Revestimento: Malha Tipo de Colchão: Mola Tipo de mola: Mola Ensacada É coleta: 0 PROFUNDIDADE x LARGURA x ALTURA: 203 x 193 x 25 Fornecedor: Mellão & Skaf Ind E Com Colchões Ltda-ME Baterias são necessárias?: Não Certificação de teste externa: Não Componentes incluídos: Não Número da peça: Não Submarca: Produto: Colchão Classificação do Colchão: King Tipo do Colchão: Padrão Número do modelo: Não É colchão na caixa?: Não Marca: Mobly', 2664.88, 2172.97, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-821ew-mh94xq922ya6d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226120317%2F23897759198', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
