INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197538609', 'Fralda Pampers Confort Super Sec M 70 Unidades', 'Experimente a NOVA Pampers Confort Super Sec com canais de ar! Que permitem que o ar circule livremente dentro da fralda, para o bumbum ficar menos abafado, e a pele arejada e sequinha durante a noite. · Até 2X mais seco e arejado. · Canais de Ar: Permitem que o ar circule livremente dentro da fralda, para o bumbum ficar menos abafado, e a pele arejada e sequinha durante a noite. · Gel Mágico que absorve e retém a umidade no interior da fralda para noites mais sequinhas. · Camada ultra absorvente: Absorve rapidamente a umidade mantendo a pele do bebê sequinha. · Barreiras Antivazamento: Se adaptam suavemente ao redor das pernas do seu bebê. · Ajuste cômodo e flexível para dar uma proteção antivazamentos todas as noites. · Loção hipoalergênica: Ajuda a prevenir irritações.', 131.74, 131.74, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rd63-lvez0jx8eyo1e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F23197538609', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097424957', 'Fantasia Princesa Sophie Avental Azul Infantil Unico', 'Itens inclusos: 01 Avental Tamanhos: Único - (medias do produto) Especificações Técnicas Material: Fantasia 100% poliéster exceto adornos. Produto: Fantasia nova, na embalagem. Cor: Azul Produto a pronta entrega! Produto Original Fantasia Princesa Sophie é composta por 01 avental azul de material liso, na região do busto contém um grande laço azul em eva com glitter. O avental possui cordões para amarrar na nuca e na cintura para melhor ajuste da fantasia. Avental ideal para completar a fantasia de princesa da sua filha em festas temáticas, festa a fantasia, aniversário, carnaval e muito mais. Confira! Avental princesa Sophie Azul Com cordões Não Pinica Não esquenta Lavagem rápida Ideal para o verão', 36.9, 36.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Costumes', 'https://cf.shopee.com.br/file/sg-11134201-7rbk6-lmhq29xjxie29b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F18097424957', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993867297', 'Botina Segurança Combat Preto Biqueira Aço TAM 38 - Kadesh', 'Loja do Mecânico - O que você precisa, nós temos! A bota/botina de segurança é um equipamento de proteção individual (EPI) utilizado para proteger os pés dos trabalhadores contra riscos diversos, como quedas de objetos, escorregões, choques elétricos, cortes, perfurações e queimaduras. São projetadas para oferecer suporte, conforto e proteção em ambientes de trabalho adversos. É importante que as botas sejam escolhidas de acordo com a atividade que será realizada, garantindo assim a proteção adequada ao trabalhador. Especificações Técnicas - Marca: Kadesh - Cabedal: Couro - Fechamento: Elástico - Dorso: Couro - Forração interna: Não tecido transpirável - Palmilha de montagem: Sintética em não tecido - Sobrepalmilha: EVA dublada em tecido - Solado: Poliuretano - Biqueira: Aço - Cor: Preto - Tamanho: 38 - EAN: 7899713535540 Conteúdo da Embalagem - 01 Botina Segurança Combat Preto Biqueira Aço TAM 38 - Kadesh Importante - Garantia de 03 meses; - Enviamos em até 24 horas úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - A cor do produto pode variar de acordo com a tela do seu smartphone/computador; - Qualquer dúvida, utilize o campo "Perguntas e Respostas" e converse com o nosso SAC.', 97.99, 92.11, NULL, 'Men Shoes > Boots > Fashion Boots', 'https://cf.shopee.com.br/file/sg-11134201-7reox-m86eco84dw9dd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F23993867297', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203987001', 'Martelo de Unha 25 mm Tramontina MASTER', 'VENDIDO POR COMASP FERRAMENTAS | EMITIMOS NOTA FISCAL Martelo de Unha 25 mm Tramontina MASTER Basic - Força Superior para Trabalhos Pesados Descrição 🌟 POR QUE O MARTELO TRAMONTINA MASTER BASIC 25MM É A ESCOLHA DOS PROFISSIONAIS? ✔️ Máxima Potência - Projetado para serviços pesados de construção e demolição ✔️ Resistência Superior - Aço carbono de alta qualidade para impacto contínuo ✔️ Controle Total - Cabo em madeira com design ergonômico para precisão nas batidas ✔️ Versatilidade Extrema - Ideal para canteiros de obras, marcenaria industrial e reformas estruturais 🎯 VANTAGENS EXCLUSIVAS: ✅ Diâmetro Ampliado - 25mm proporciona melhor desempenho em trabalhos mais exigentes ✅ Tratamento Anticorrosão - Verniz especial que protege contra oxidação e aumenta a vida útil ✅ Equilíbrio Perfeito - Distribuição de peso otimizada para menos esforço físico ✅ Produtividade Aumentada - Realiza trabalhos mais rapidamente devido à sua potência superior 🔧 CARACTERÍSTICAS TÉCNICAS: → Peso da Cabeça: 680g (peso ideal para força) → Comprimento Total: 350 mm → Material da Cabeça: Aço carbono com verniz anticorrosivo → Material do Cabo: Madeira de reflorestamento envernizada → Diâmetro da Unha: 25 mm → Tipo: Martelo de unha para uso profissional intensivo 📦 ITENS INCLUSOS: • 1 Martelo Tramontina Master Basic 25mm • Embalagem protetora resistente • Manual de instruções • (Acessórios não inclusos) 🛒 COMPRE AGORA E TRANSFORME SEU TRABALHO PESADO! 🚚 CONDIÇÕES DE ENTREGA: 📦 FRETE GRÁTIS 🆓 para todo Brasil! ⏰ Entrega Rápida - receba em até 7 dias úteis! 🛡️ Garantia do Fabricante - Consulte a garantia padrão com o distribuidor no ato da compra.', 60.0, 45.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/