INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099317024', 'Colchão Queen Molas Ensacadas Zidi Alabama 158x198x24cm', 'Colchão Queen Alabama Molas Ensacadas 158x198x24cm O colchão Alabama além de responsável para garantir um boa noite de sono é uma ótima relação com custo-benefício. Tipo de Molas: Molas ensacadas, são elas responsáveis para garantir uma excelente noite de sono, elas são um saco de molas que trabalham de maneira individualmente, são independentes umas das outras, assim garante a longevidade da vida útil do colchão, pois quando uma pessoa se deita quase não afeta com o movimento ondular proporcionado, proporcionando assim também um conforto muito grande. Tipo de Pillow: Pillow Flat, Superfície plana, dando um visual mais clean ao colchão. Marca: Anjos Capacidade de peso por pessoa: 120kg Altura: 24cm Largura: 158cm Comprimento: 198cm Peso: 24,90kg ** IMAGENS MERAMENTE ILUSTRATIVAS. *** NÃO REALIZAMOS ENTREGAS EM LOCAIS DE ACESSO APENAS POR ESTRADA DE TERRA, ESTRADA DE AREIA, POR BALSA OU BARCO, NÃO SUBIMOS PRODUTOS POR ESCADAS, ELEVADORES OU IÇAMENTOS. NÃO NOS RESPONSABILIZAMOS POR MONTAGENS, DESMONTAGENS E INSTALAÇÕES, CONFIRA AS DIMENSÕES DO PRODUTO E CERTIFIQUE-SE QUE O MESMO PASSARÁ NORMALMAENTE POR ELEVADORES, PORTAS, ESCADAS OU CORREDORES. INFORMAMOS DESDE JÁ AOS NOSSOS CLIENTES PARA QUE NÃO HAJA TRANSTORNOS OU QUALQUER EXPERIENCIA RUIM NA COMPRA **** PRODUTO POSSUI 1 (UM) ANO DE GARANTIA FORNECIDA PELO FABRICANTE.', 1609.9, 919.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-8262x-mls8h647n3er8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1087752745%2F20099317024', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
