INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9098739849', 'Mangá - Re:Zero - Começando uma Vida em Outro Mundo - 18', 'Re:Zero - Começando uma Vida em Outro Mundo - 18 Livro de Bolso ''Maravilhoso. Você é a dama ideal que eu desejava!'' A operação de retomada do paço municipal terminou numa falha e Priestella, a cidade das comportas d''água, foi engolida por águas turvas em um instante. Subaru, saboreando uma derrota dolorosa, jurou se reerguer, mas as mãos vis dos Arcebispos Pecaminosos tornam a confusão mais profunda e mais perversa. Terror e insegurança roubam a sanidade das pessoas e bestas que não deveriam existir se esgueiram pela cidade. Em uma situação em que foram separados dos companheiros com os quais podiam contar, Subaru e os demais, como uma forma de virar o jogo, fazem uma aposta arriscada para salvar as pessoas da cidade. Criariam a lenda do herói.! Tipo de Produto: Revista Segmentos: Mangás Marcas: New Pop Novels Autor(es): Tappei Nagatsuki Editora: New Pop Número de páginas: 472 Lombada/Encadernação: Quadrada Tipo de capa: Cartão Idioma: Português Condição: Novo/Lacrado', 32.9, 32.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/35bfacb7b3ca5acfd5f5b44fce21f3f1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F9098739849', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252699479', 'MESA DE SOM AUTOMOTIVO TARAMPS T 0302 PLAYER MIXER EQUALIZADOR', 'A T 0302 Player é a primeira “Mesa Player” da Taramps. Além de controlar e mixar o seu sistema de som, ela é capaz de reproduzir sua playlist favorita sem a necessidade de usar um “player convencional”. O Player integrado, possui conexão Bluetooth, entrada USB, recepção de FM e saída para fones de ouvido. E para ficar ainda melhor, incluímos o controle remoto de longa distância, que permite aumentar ou diminuir o volume, trocar faixas e pastas, entre outras funções, quando utilizada a função Player. Dentre as principais aplicações do produto, podemos citar as famosas “Caixas Bob” e os mais variados sistemas de som automotivo. Simplicidade na instalação e versatilidade de uso são sinônimos deste produto. INFORMAÇÕES TÉCNICAS: Resposta de Frequência (-3dB): 2Hz ~ 76Khz Distorção Harmônica Total:', 529.99, 529.99, NULL, 'Audio > Amplifiers & Mixers', 'https://cf.shopee.com.br/file/sg-11134201-8261r-mj4dipbms7pg25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406280808%2F58252699479', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
