INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597323846', 'Leave-In Triskle Hidratação E Brilho 250ml', 'Perceba seus cabelos com aquela sensação de leveza, maciez e brilho que rende muitos elogios. Nossa fórmula possui uma combinação que reúne os benefícios hidratantes da Babosa e nutritivos do Óleo de coco. Juntos promovem finalização 360 , reduzindo o volume e protegendo os fios de fontes de calor. Você sentira o poder de ter cabelos lindos macios e perfumados Modo de Uso: Aplique na palma da mão a quantidade necessária para o comprimento e espalhe o produto entre os fios. Não enxágue. Possui proteção térmica.', 58.7, 58.7, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7rcci-lr5xwx0znskxfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23597323846', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
