INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297751626', 'Serum Facial Garnier SkinActive Uniform & Matte Vitamina C 15ml', 'O novo Garnier Uniform & Matte Sérum Booster tem Alta Concentração de Vitamina C, Niacinamida, Ácido Salicílico e Extrato de Limão, que garantem marcas menos visíveis, pele uniformizada e hidratada, sem deixá-la oleosa. A textura sérum garante fácil aplicação, sensação gostosa pós uso e rápida absorção.', 60.73, 60.73, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7rdwn-lzfndoj9d89294', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22297751626', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192992370', 'Livro Tempos Extremos: Edição comemorativa do romance de estreia da premiada jornalista, por Míriam Leitão - Intrínseca', 'Tempos Extremos: Edição comemorativa do romance de estreia da premiada jornalista, por Míriam Leitão - Intrínseca Descrição do Livro: Finalista do Prêmio São Paulo de Literatura, romance de estreia da premiada jornalista Míriam Leitão ganha edição comemorativa e se mostra mais atual do que nunca Quantos mistérios uma antiga fazenda perdida entre as serras das Minas Gerais pode guardar? Mistérios que chegam de forma inesperada, revelando passados diversos a uma família dividida por conflitos afetivos e políticos. É o que Larissa tentará descobrir, em uma estranha jornada na qual perseguirá sombras e segredos para entender os próprios sonhos. No memorável primeiro romance de Míriam Leitão, agora em edição comemorativa de dez anos, o leitor não encontra espaço para respirar. É uma história de paixões extremas, sobre tempos extremos. Uma viagem às vezes em quase delírio pelos flagelos da escravidão, no século XIX, e pelos subterrâneos do regime militar, no século XX. A narrativa se passa no século XXI, mas as linhas temporais são rompidas. No entremeio, as relações tormentosas entre pais e filhos e entre irmãos tecem uma trama densa e ousada que revisita passados que o Brasil tem preferido deixar acobertados pelo silêncio. Como ficcionista, Míriam Leitão mantém aqui a mesma postura que marcou sua trajetória de jornalista: não faz perguntas fáceis. Nem abre caminhos para zonas de conforto. Sobre o Autor: Míriam Leitão é de Caratinga (MG). É jornalista de TV, rádio, jornal e mídia digital. Em cinquenta anos de profissão, recebeu diversos prêmios, entre eles o Maria Moors Cabot, da Universidade Columbia de Nova York. Como escritora, ganhou o Jabuti de Livro do Ano de Não Ficção em 2012 por Saga brasileira. Também pela Intrínseca publicou História do futuro: o horizonte do Brasil no século XXI (2015), A verdade é teimosa (2017), a coletânea de crônicas Refúgio no sábado (2018), com a qual foi finalista do Jabuti, A democracia na armadilha (2021) e Amazônia na encruzilhada (2023). Detalhes do livro: Tradutor: Livro brasileiro Número de Páginas: 304 Gênero: Literatura e Ficção Dimensões do livro: 14 x 21 x 1,9 Peso do livro (Kg): 0,332 Tipo de capa: Livro brochura (paperback) Data de lançamento: 10/04/2024 Idioma do livro: Português Traduzido do: Português', 79.9, 63.92, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luxiot6fqlb90a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F23192992370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40863860792', 'Vejam como dançamos por Leïla Slimani, Intrínseca', 'Romance centrado em família franco-marroquina aborda pertencimento, colonialismo e liberdade. Após os turbulentos conflitos que eclodiram na guerra de independência, mais de dez anos antes, o Marrocos vive um período de reconstrução, instabilidade política e mudanças sociais. Amine e Mathilde Belhaj — ele, ex-soldado marroquino, e ela, alsaciana — criaram os dois filhos em Meknés e, com muita obstinação, prosperaram em meio às dificuldades, passando a integrar a recente burguesia nacional. Em 1968, a família leva uma vida abastada, dividida entre as velhas tradições e novos hábitos que acenam ao hedonismo ocidental, com festejos, músicas e danças. Enquanto Selim, o filho caçula, é um garoto pouco disciplinado que se prepara sem afinco para o exame de ingresso na universidade, Aïcha, a mais velha, sempre muito dedicada, estuda medicina em Estrasburgo. Nas férias da faculdade, durante a agitação que toma as ruas na França, ela volta para casa, depois de quatro anos fora, e encontra um Marrocos muito diferente. Em um passeio com uma amiga, Aïcha conhece “Karl Marx”, um estudante de economia idealista que a faz questionar a própria realidade e a ver as coisas com um novo olhar. Em Vejam como dançamos, sequência de O país dos outros, reencontramos a família franco-marroquina que retrata os desafios impostos pelo multiculturalismo e pelas relações inter-raciais em uma sociedade conservadora. Dessa vez, acompanhamos principalmente Aïcha e Selim, a geração dos filhos da revolução, que crescem em uma situação mais favorável, mas ainda buscam pertencimento e liberdade ao mesmo tempo que tentam compreender quem são. Com sensibilidade e uma narrativa potente, Leïla Slimani conta, a partir da trajetória das gerações da família Belhaj, a história do próprio Marrocos.', 89.9, 71.92, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/br-11134275-7r98o-mbwoycbb155l4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F40863860792', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9011163121', 'Doce De Leite Pronto 950g Alispec', 'O Recheio Doce de Leite Alispec em embalagem de 950g é um produto versátil, perfeito para confeitaria e ideal para ser utilizado em recheios, coberturas e decorações. Com uma consistência cremosa, é fácil de espalhar e possui um sabor suave de doce de leite, o que o torna ótimo para aplicação em: bolos e tortas, doces como churros e sonhos, sobremesas como pavês e verrines, pães e croissant s. A embalagem de 950g é pensada para quem trabalha com confeitaria ou deseja ter um bom estoque para preparar diversas receitas em casa. Rendimento: Cerca de 190 unidades de 5g cada. Conservação: Após aberta a embalagem, manter na geladeira e consumir, no máximo, em 20 dias. Ingredientes: Açúcar, xarope de glucose de milho, água, leite em pó, amido modificado (Bacillus thuringiensis e/ou Streptomyces viridochromogenes e/ou Agrobacterium tumefaciens e/ou Zea mays e/ou Sphingobium gerbicidorovans e/ou Dicissoma sp. e/ou Thermoccocales ssp. e/ou Bacillus substillis.), soro de leite, óleo vegetal, maltrodextrina, sal, espessante, pectina, estabilizante, citrato de sódio, emulsificante mono e diglicerídeos de ácidos graxos, conservador sorbato de potássio e aroma idêntico ao natural. Contém lactose. Alérgicos: Contém derivados de leite e soja. Pode conter amendoim. Não contém glúten. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 35.99, 35.99, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ggapacfgg266', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F9011163121', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
