INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205038840', 'Eletrodo Revestido para Inox AWS E308L 2,50mm Alta Resistência Vonder', 'É adequado para soldagem de estruturas de aço, deposita aço inox tipo 19/10 com baixíssimo teor de carbono. Os eletrodos, de um modo geral, não devem ficar armazenados diretamente no chão ou expostos à umidade. Para um mínimo de conservação, devem ser armazenados em cima de madeiras ou em prateleiras. No momento do uso, é muito importante a utilização de estufas (cochicho). O metal de solda possui excelentes propriedades mecânicas e mostra uma boa resistência à corrosão intergranular devido ao teor de carbono (0,04%). Pode ser usado para soldagem na maioria das posições (exceto vertical descendente), com excelente desempenho: arco estável, poucos respingos e boa aparência de solda. Detalhes Técnicos: - Classificação: E308L-16 - Diâmetro do eletrodo: 2,5 mm - Comprimento do eletrodo: 350 mm - Faixa de corrente do eletrodo: 50 A - 85 A - Tensão do eletrodo: 27 V a 33 V - Posições de soldagem: Plana, horizontal, vertical ascendente, sobre-cabeça e angular - Tipo de corrente do eletrodo: AC ? 50 V / DC+ - Tipo de revestimento do eletrodo: Rutílico - Atende norma: AWS A5.4 E308L-16', 99.9, 79.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8260e-mkkyckmolwjkfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F58205038840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
