INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23399018686', 'Lanterna de LED para Cabeça Recarregável LCV032 Vonder com Ajuste e Alta Iluminação', 'A Lanterna de LED para Cabeça Recarregável LCV032 da Vonder é ideal para trabalhos noturnos, manutenção, camping, trilhas e atividades que exigem iluminação prática com as mãos livres. Compacta e confortável, possui faixa ajustável para melhor encaixe e iluminação eficiente em diferentes ambientes. Conta com bateria recarregável, proporcionando praticidade e economia no uso diário. Seu LED de alta intensidade oferece excelente visibilidade, sendo indicada tanto para uso profissional quanto doméstico. Diferenciais: ✅ LED de alta iluminação ✅ Bateria recarregável ✅ Faixa ajustável para maior conforto ✅ Ideal para trabalho, camping e manutenção ✅ Leve, compacta e prática ✅ Permite uso com as mãos livres Conteúdo da Embalagem: 1 Lanterna para cabeça. Acompanha: 1 cabo tipo C. Detalhes técnicos: - Modelo: LCV 032 - Material da lanterna: Plástico ABS - Cor da lanterna: Preta - Fluxo luminoso (lúmen): Luz branca 1° estágio: 450 lm; 2° estágio: 110 lm / Luz amarela 1° estágio: 500 lm; 2° estágio: 130 lm - Tipo de lâmpada: Led - Quantidade de LEDs da lanterna: 32 - Alimentação da lanterna: 1 bateria 3,7 V - 1.200 mAh - Íons de lítio - Tempo de carga: Aproximadamente 3,5 horas - Autonomia aproximada: Nível 1 - Modo economia: 4 horas / Nível 2 - Modo alto: 2 horas - Massa aproximada (peso): 0,110 kg', 107.0, 99.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134207-820lr-moo0zq6pcqv9f0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F23399018686', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257990486', 'Serra Tico-Tico 400W TTV400 para Madeira Metal e Plástico Vonder', 'A Serra Tico-Tico 400W TTV400 Vonder é indicada para cortes em madeiras, metais, plásticos e outros materiais, desde que utilizada com a lâmina apropriada. É ideal para trabalhos de marcenaria, manutenção, reformas, instalação, acabamento e uso profissional ou doméstico. Possui cabo com revestimento emborrachado, proporcionando maior conforto durante o manuseio, além de dupla isolação, que oferece mais segurança ao operador. Conta com base inclinável em até 45°, permitindo cortes retos e inclinados conforme a necessidade do trabalho. Diferenciais do Produto: ✅ Indicada para madeira, metal, plástico e outros materiais ✅ Potência de 400W ✅ Base com inclinação de até 45° ✅ Capacidade de corte em madeira de até 55 mm ✅ Capacidade de corte em aço de até 6 mm ✅ Capacidade de corte em alumínio de até 10 mm ✅ Cabo com revestimento emborrachado ✅ Dupla isolação para maior segurança ✅ Compatível com lâminas tipo U e tipo T ✅ Acompanha lâmina para madeira e chave Allen **Detalhes Técnicos** Marca: Vonder Modelo: TTV400 Tipo de produto: Serra tico-tico Potência: 400W Frequência: 60 Hz Tipo de velocidade: Fixa Número de golpes por minuto: 3.000 gpm Ângulo de inclinação da base: 45° Capacidade de corte em madeira a 90°: 55 mm Capacidade de corte em aço a 90°: 6 mm Capacidade de corte em alumínio a 90°: 10 mm Tipo de encaixe da lâmina: Tipo U e tipo T Normas: ABNT NBR IEC 60745-1 e ABNT NBR IEC 60745-2-11 Aceleração transmitida em madeira: 7,3 m/s² Aceleração transmitida em metal: 11,1 m/s² Incerteza da aceleração: 1,5 m/s² Massa aproximada: 1,7 kg Conteúdo da Embalagem 1 Serra tico-tico 1 Lâmina 50 mm para madeira com encaixe tipo T 1 Chave Allen 3 mm', 392.52, 269.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-82600-mmhvdzvpwa331b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F58257990486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
