INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597713727', 'Fita Dupla Face Tissue 4869 50MM X 30M', 'A Fita Dupla Face de Não Tecido 3M 4869 é uma fita de uso geral com espessura total de 0,085 mm e um dorso não tecido, coberto em ambos os lados com o Adesivo Acrílico 3M. Este adesivo garante bom desempenho em substratos com alta energia superficial devido à sua capacidade superior de adesão e coesão. Além disso, seu liner de proteção do adesivo é siliconizado em ambos os lados, minimizando bolhas, ondulações e rugas. Boa aderência em materiais com alta energia superficial, como metais, poliéster, policarbonatos, acrílicos e outros', 64.9, 64.9, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/sg-11134201-7rdw6-lz0ls5gp81br93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328711923%2F23597713727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
