INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792256135', 'The Icon Antonio Banderas Perfume Masculino Eau de Toilette', 'The Icon é um perfume Antonio Banderas masculino oriental amadeirado. Uma fragrância cheia de atitude, que abre territórios para o homem de sucesso mostrar a singularidade de um verdadeiro ícone. O Perfume Masculino The Icon, de Antonio Banderas, traz o impacto de uma onda fresca, com notas requintadas de cítricos italianos intensificadas com a faceta luminosa e brilhante da pimenta preta. Além disso, uma mistura elegante de lavanda e óleo de sálvia reforçada com folhas de violeta aquática, para aumentar a masculinidade em contraste com uma combinação de madeiras e sensuais favas tonka, revestidas com o caráter imponente do musgo de carvalho. Disponível nas volumetrias: 50ml e 100ml. Experimente também The Golden Secret, outro grande sucesso da marca. Pirâmide Olfativa Topo: Bergamota, Toranja e Pimenta Preta. Corpo: Folhas de Violeta, Lavanda e Sálvia. Fundo: Patchouli, Musgo de Carvalho, Feijão Tonka e Âmbar. Ocasião Fragrância que acompanha perfeitamente ocasiões especiais, dias mais frios ou eventos noturno. Perfume para destacar o visual e envolver quem estiver à sua volta.', 241.99, 239.99, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-ll10914d6yqw71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F602117686%2F22792256135', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14268525289', 'Caneta Posca PC-7M Branco uni-ball', 'Caneta Posca na mão pra tirar a ideia da cabeça. A ponta média é ótima tanto para preenchimentos quanto para detalhes, dando mais opções para os artistas de plantão. Características do produto - Marcador multiuso. Escreve na maioria das superfícies, como cartões, cerâmica, madeira, metais, tecidos, porcelana, plástico, vidro, e muitas outras. - Tinta à base de água, com alta tecnologia em pigmentação. Cores mais intensas e uma cobertura com quase 100% de opacidade. Atóxica e sem cheiro. - Espessura do traço: Aprox. de 4.5 a 5.5 mm.', 54.6, 45.32, NULL, 'Stationery > Writing & Correction > Markers', 'https://cf.shopee.com.br/file/sg-11134201-823q7-mp40wcupprez9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F14268525289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41875214423', 'Truss Equilibrium Scalp - Shampoo 300ml', 'Truss Equilibrium Scalp - Limpa, Revitaliza e Combate a Oleosidade Excessiva Ideal para cabelos oleosos ou mistos. Com Bio Balance Complex e Reviscalp, controla a oleosidade, reduz a descamação e restaura o equilíbrio do couro cabeludo. Deixa os fios leves, limpos e fortalecidos, enquanto sua fragrância fresca transforma o cuidado diário em um ritual revigorante e sofisticado. Conselho de Aplicação Aplique nos cabelos molhados, massageando os fios com as pontas dos dedos. Enxágue e repita a operação se necessário.', 220.85, 129.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8259c-mg2oa8irolxkb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F41875214423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
