INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298397146', 'Kit Acquaflora Pós-Progressiva Home Care (3 produtos)', 'Acquaflora Pos-Progressiva Contém: 1 Shampoo Pos-Progressiva 300ml 1 Condicionador Pos-Progressiva 300ml 1 Mascara Pos-Progressiva 250ml Shampoo: Lava delicadamente os cabelos quimicamente processados e danificados por alisamentos e escovas progressivas. Proporciona brilho intenso, recuperação da fibra e devolve movimento saudável aos fios. Condicioador: Desembaraça instantaneamente, nutre e revitaliza os cabelos submetidos a alisamentos e escovas progressivas proporcionando recuperação da fibra, brilho intenso, diminuição do frizz e movimento aos fios. Mascara: Complexo de Nanocristalização dos fios. Hidrata, regenera e nutre profundamente os cabelos submetidos a alisamentos e escovas progressivas proporcionando recuperação da fibra, brilho intenso, diminuição do frizz e movimento aos fios. Agentes condicionantes exclusivos promovem o fortalecimento dos cabelos aumentando a durabilidade do efeito liso. Rica em ativos que aumentam o alinhamento das fibras e reduzem a fricção entre os fios de cabelo para a liberdade de movimento que somente os cabelos saudáveis apresentam.', 339.55, 177.9, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-8262e-ml2c2k7fd3wj29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22298397146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097471632', 'Kit 2 Hipoglós Amêndoas Creme Preventivo de Assaduras 40g', 'A fórmula do HIPOGLÓS AMÊNDOAS forma uma barreira nutritiva enriquecida com óleo de amêndoas que protege a pele até contra assaduras mais graves e reduz a vermelhidão em até 3 horas. HIPOGLÓS Amêndoas. Produto cosmético para prevenir assaduras. BENEFÍCIOS: - Protege contra assaduras formando uma barreira contra germes e outros agressores - Nutre e recupera a pele em até 3 horas - Com óleo de Amêndoas e manteiga de Karité - Seguro para ser usado desde os primeiros dias de vida - Hipoalergênico. Clinicamente testado por Dermatologistas e Pediatras - Barreira Branca em Textura Suave INDICAÇÃO: A fórmula do HIPOGLÓS AMÊNDOAS é indicada para nutrir e proteger a pele até contra assaduras mais graves. INSTRUÇÕES DE USO: A cada troca de fraldas, limpe e seque cuidadosamente a pele do bebê e aplique uma camada generosa de HIPOGLÓS sobre a área a proteger, massageando suavemente. PRECAUÇÕES: Mantenha fora do alcance de crianças. Deve ser aplicado por adulto ou sob sua supervisão. Não usar na pele irritada ou ferida. Em caso de irritação, suspender o uso e procurar um médico. Conservar em local seco, fresco e ao abrigo da luz solar direta. Este produto foi formulado de maneira a minimizar possível surgimento de alergia. COMPOSIÇÃO: Aqua/água purificada, Zinc Oxide/óxido de zinco, Isopropyl Palmitate/palmitato de isopropila, Dicaprylyl Carbonate/ carbonato de dicaprilila, Lanolin/lanolina, C12-15 Alkyl Benzoate/benzoato de alquila C12-15, Glycerin/glicerol, Polyglyceryl-2 Dipolyhydroxystearate/ dipoli-hidroxiestearato de poliglicerila-2, Butyrospermum Parkii Buer/manteiga de karité, Polyglyceryl-3 Diisostearate/di-isoestearato de poliglicerila-3, Magnesium Sulfate/sulfato de magnésio, Hydroxyacetophenone/ hidroxiacetofenona, Zinc Stearate/estearato de zinco, Parfum/fragrância, 1,2-Hexanediol/1,2-hexanodiol, Caprylyl Glycol/caprililglicol, Tocopheryl Acetate/acetato de dextroalfatocoferol, Prunus Amygdalus Dulcis Oil/ óleo de amêndoas, Tropolone/tropolona. HIPOGLÓS Amêndoas. Produto cosmético para prevenir assaduras.', 51.98, 51.98, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/sg-11134201-82608-mkm6escchmgw14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F22097471632', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294664657', 'Kit 2 Esmalte Risqué Menta Liza Cremoso 8ml', 'Esmalte Risqué Menta Liza Cremoso 8ml O esmalte Risqué Menta.liza é cremoso, de secagem rápida e com ultra brilho, além de ter longa duração nas unhas. Sua fórmula é hipoalergênica, isto é, livre de componentes que costumam causar alergias e seu pincel proporciona aplicação perfeita e alta cobertura. Toda a linha de esmaltes Risqué apresenta textura única, cores elegantes e acompanha as tendências da moda, possibilitando diversas composições de looks e maximizando a beleza da sua maquiagem e acessórios. Apaixone-se pela cor, presencie a longa duração e viva a beleza de suas unhas de forma única com o Esmalte Menta.liza.', 14.72, 14.72, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-825ai-mqmgpzv8hudd20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23294664657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
