INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198360370', 'Panela de Pressão Eirilar Polida Prata 4,5L', 'A Panela de Pressão Eirilar é perfeita para quem busca praticidade e segurança na cozinha. Ela é feita em alumínio, com acabamento externo com polimento de alto brilho e os Cabos e alças são feitos de Baquelite reforçado que resistem ao calor e haste cromado de alta dureza. Além disso, a Panela de Pressão Eirilar é muito segura, pois conta com uma borracha e válvulas de silicone que garantem a perfeita vedação, mesmo quando submetidas a altas temperaturas. Com seu design moderno na cor prata, ela tem capacidade para 4,5L, ideal para preparo de médias porções. A opção ideal para quem busca praticidade, seja para preparos longos ou rápidos. Recomendação de Uso Pode ser utilizado no fogão a gás, elétrico Dicas de Preservação Para garantir a durabilidade da panela de pressão, não se recomenda o uso de produtos abrasivos no processo de limpeza. Secá-la bem após a lavagem. Podo ser utilizado no fogão a gás e Elétrico.', 69.99, 69.99, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-825a4-mqyt0x3os0zqf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23198360370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
