INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597970988', 'Pneu Moto Rinaldi 3.00-10 42j Bs32 Scooter e Camara Ar Rh10', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação HONDA LEAD 110 2010 até 2016 Conteúdo Da Embalagem 1 Pneu 3.00-10 + Câmara de ar Rh10 Largura do Pneu 3.00 Tipo de Veículo para Motos Marca Criada em 1969, a Rinaldi é fabricante de pneus e câmaras de ar para motocicletas off-road e on-road, motonetas, ciclomotores, tratores agrícolas (linha leve), charretes e industrial não motorizada. A marca é certificada pelo Inmetro na categoria "Acreditação de seus produtos" da linha de motocicletas. Importante • Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 5 Anos a partir da emissão da nota fiscal por defeito de fabricação. • O consumidor tem o prazo de 7 (sete) dias a contar do ato de recebimento do produto para exercer o seu direito de arrependimento. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Imagem meramente ilustrativa. • Alguns veículos podem sair de fábrica com mais de uma medida de pneu. Por favor, verifique sempre no veículo qual é a medida exata. Código do Fabricante 800830001 Aro 10 Posição Dianteiro Traseiro Garantia 60 meses', 264.9, 247.03, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rbn4-llujbb5651zt26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1197031273%2F21597970988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207497374', 'TOALHINHAS UMEDECIDAS LUNIS PEQUENINOS COM 100 UNIDADES', 'As Toalhinhas Umedecidas Lunis Pequeninos são práticas e macias, ideais para higiene e limpeza da pele delicada do bebê. Possuem em sua fórmula ingredientes suaves como: Glicerídeos de Manteiga de Karité e extratos de Capim Limão e Aloe Vera, proporcionando uma limpeza delicada e eficaz. Modo de usar: 1.Ao abrir a tampa, retire os lenços um a um. 2.Utilize-os nas áreas que deseja limpar, fazendo uma suave massagem. 3.Após o uso, feche bem a embalagem para conservar a umidade dos lenços. Benefícios - Limpa, sem agredir a pele do bebê - Dermatologicamente testado - Toque macio - Perfume suave - Ideal para troca de fraldas - Tampa Flip-Top - Embalagem econômica com 100 unidades', 12.99, 12.99, NULL, 'Mom & Baby > Bath & Body Care > Wipes', 'https://cf.shopee.com.br/file/sg-11134201-8260z-mm7j07e23a4o52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1765202114%2F58207497374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21698822882', 'MAGICA MORTAL, A - SEGUINTE', 'A cada truque de mágica, um crime. Em seu primeiro livro juvenil, o mestre do suspense Raphael Montes nos apresenta ao Esquadrão Zero ― um grupo de jovens detetives que vai encarar uma investigação repleta de perigos e reviravoltas. No mundo da mágica, nem tudo é o que parece. Pedro sabe disso muito bem, afinal, sempre foi fascinado por ilusionismo. Só não imaginava que ia entrar para valer nesse universo por causa de um crime terrível. Depois que seu melhor amigo é vítima de um mágico sinistro, Pedro decide encontrar o culpado a qualquer custo. Assim, o garoto reúne Pipa, Analu e Miloca, seus amigos de escola, para formar o Esquadrão Zero ― e juntos desvendarem o caso.Não demora para o criminoso fazer novas vítimas, sempre utilizando números de mágica famosos. Em uma corrida contra o tempo, os quatro jovens investigadores terão de cruzar a cidade numa aventura que envolve ilusionistas excêntricos, livros eletrizantes e um castelo imponente. Será que o grupo conseguirá descobrir quem é o mágico assustador antes que ele realize seu próximo truque? Indicado para leitores a partir de 10 anos. “Um suspense mais intrincado do que um quebra-cabeça montado pelo avesso.” ― Pedro Bandeira “Com escrita fluida e magnética, Raphael Montes fez um thriller adolescente com tudo a que tem direito: morte, suspense e muita, muita mágica.” ― Thalita Rebouças', 61.1, 61.1, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-8258n-mfyhmi9f8pvud0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F21698822882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
