INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17068510464', 'Kit de Elásticos Extensores em 3 Resistências HP249 Proaction', 'O Kit de elásticos extensores possui 3 elásticos de diferentes resistências e um pegador com mosquetão de metal. Proporciona treinamento funcional completo possibilitando o trabalho do corpo inteiro de maneira prática e muito eficiente. Os elásticos possuem diferentes intensidades para pessoas com diferentes níveis de condicionamento e força. Substitui os pesados aparelhos de musculação, fortalecendo o corpo de uma maneira mais natural, funcional e sem riscos de lesões. Utilizado em exercícios de pilates, funcional e reabilitação. Leve, resistente, eficiente e prático de levar para qualquer lugar. Indicação : Fortalecimento e Tonificação Muscular. Reabilitação e Prevenção de Lesões. Mobilidade Muscular. Trabalho de Todos os Grupos Musculares. Medidas Aprx. e Resistências : Leve (VERDE) - 5mm x 11mm x 1,1m Média (CINZA) - 6mm x 11mm x 1,1m Forte (PRETO) - 7mm x 11mm x 1,1m Conteúdo da Embalagem: 01 Kit de Elásticos Extensores em 3 Resistências HP249 Proaction Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 98.0, 98.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/d1fa4a59304e310140b80abc92e4a3b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F17068510464', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
