INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9380188243', 'Touca de Natação Afro GG Daminhacor Branco', 'Touca Afro de Natação e Banho Muito Volumosos Daminhacor - Modelo: Unissex - Material: Silicone (Composição:100%) - Origem: Produto Importado - Dimensões: 35.5cm altura, 31.5cm largura, 22.5cm abertura para cabeça. Recomendada para cabelos super-volumosos ou com “dreadlocks” e/ou tranças “Rastafári” que ultrapassem a linha da metade das costas. Obs.: As recomendações acima são apenas referenciais. Recomenda-se que você avalie o tamanho do seu cabelo, comparando-o com as dimensões de cada tamanho, antes da tomada de decisão. MANUSEIO: - Ao colocar ou retirar a Touca utilize as pontas dos dedos, nunca use as unhas - Nunca puxar a Touca por sobre os Olhos, Nariz e Boca - Ao usar a Touca, não use Grampos, Presilhas e Similares no Cabelo - Após vestir a touca, pressione com as mãos para RETIRAR O AR de dentro, deixando a touca rente aos seus cabelos - Após o uso, lave em água corrente, secando com pano seco e limpo - Evite guardar o produto molhado - Guardar em lugar fresco e arejado e longe de fontes de calor - Evite contato com objetos pontiagudos - Nunca cortar ou alterar o formato original do Produto PRECAUÇÕES: - Caso ocorra irritação na pele ou couro cabeludo, suspenda o uso imediatamente. - Crianças não devem utilizar o produto sem supervisão de um adulto. Conteúdo da Embalagem: 01 un. Touca de Natação Afro GG Daminhacor Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 149.0, 149.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/dc11834c49c64c94226050332ee31ac9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F9380188243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42729726261', 'Relógio Champion Ana Hickmann Dourado Luxo AH28955X', 'Você está procurando um relógio resistente e sofisticado para acompanhar o seu dia a dia? Seja bem vindo à RBM WEBSHOP - todos os nossos relogios são originais e a pronta entrega para envio imediato. Veja as PRINCIPAIS CARACTERÍSTICAS do Relógio Feminino Ana Hickmann Dourado Informações Básicas Marca: Ana Hickmann Modelo: AH28955X Gênero: Feminino Resistência à Água: 10atm – 100mts: Pode ser usado para mergulhos profundos em piscinas e no mar Medidas do Relógio Diâmetro da Caixa: 3,3cm (MÉDIO) Circunferência Máxima da Pulseira: 19 cm (DIÂMETRO MÁXIMO NO PULSO) Espessura: 0,9 cm Peso: 82 gramas Materiais do Relógio Composição do Vidro: Cristal Mineral (RESISTENTE A RISCOS) Material da Caixa: Aço inoxidável Material da Pulseira: Aço inoxidável Material da Tampa: Aço Inoxidável Características do Relógio Mecanismo: Analógico Alimentação: Quartzo Duração aproximada da bateria: 2 anos Fecho: Dobrável com dois botões Fundo: Rosqueado Cores Mostrador: Branco e Preto Caixa: Dourado Pulseira: Dourado Garantia 1 ano de garantia em todo território nacional com a rede autorizada Conteúdo da Embalagem O relógio vai na caixa original, com a nota fiscal, certificado de garantia e manual de instrução. VAMOS CONHECER MELHOR SOBRE A LOJA RBM WEBSHOP RELOGIOS? Somos uma das melhores e maiores lojas de relogios no Brasil. Todos os relógios vendidos pela nossa loja são 100% originais, contém nota fiscal, certificado, manual de instruções e garantia de 12 meses com a rede de assistência em todo o Brasil. Dúvidas? Pergunte, e será um enorme prazer lhe atender!', 399.0, 279.0, NULL, 'Watches > Women Watches', 'https://cf.shopee.com.br/file/sg-11134201-81zwe-mmkpwroslkp4da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356201012%2F42729726261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
