INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46807401537', 'Sandália Papete Infantil Menina Kidy Wave Light Nude Com Luz Led Pisca Pisca Colorido Confortável', 'Sandália Kidy Wave Light Nude Delicada, moderna e cheia de brilho, a Sandália Kidy Wave Light Nude é perfeita para meninas que adoram conforto com um toque de encanto. O tom suave combinado com detalhes de glitter e aplicação de borboleta deixa o visual ainda mais especial. O cabedal sintético oferece resistência e fácil limpeza, enquanto o forro têxtil proporciona toque macio no contato com a pele. A palmilha em EVA garante leveza e conforto, absorvendo impactos e acompanhando a rotina de brincadeiras. O destaque fica por conta da sola em TR com luzes em LED que acendem ao caminhar, criando o efeito “pisca pisca” que transforma cada passo em diversão. O fechamento em velcro facilita o calce e permite ajuste firme e prático. Ideal para passeios, festas e momentos de lazer, unindo conforto, tecnologia e muito estilo para brilhar em todos os passos. Especificações Técnicas · Cabedal: Sintético · Forro: Têxtil · Palmilha: EVA (antimicrobiana) · Sola: TR · Numeração: 25 ao 32 Kidy, cuidando de cada passo.', 189.99, 171.0, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-8262b-mlzdw07qmqyr75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F46807401537', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11733774316', 'Jogo de Cama King Cetim 300 Fios Buddemeyer Bud Vision New Colors II 100% Algodão Penteado 4 peças', 'CARACTERÍSTICA DO PRODUTO: A sofisticação se dá pelo fino acabamento nas peças, cores e brilho dos tecidos.Tecido cetim 300 fios - 100% algodão fio penteado - toque acetinado e macio; acabamento de excelente qualidadeQualidade e design Buddemeyer CONTEÚDO DA EMBALAGEM: Contém: 1 sobrelençol 280x250cm + 1 lençol 193x203x40cm + 2 fronhas 50x70cm COMPOSIÇÃO: Tecido cetim 300 fios - 100% algodão, Fio Penteado TIPO DE MATERIAL: Tecido 100% algodão, fio penteado COR: Branco EAN: 7909301350872 REFERÊNCIA: F00123330000013446 DESCRIÇÃO: Jogo de cama king Bud Vision New Colors. É produzido em tecido cetim 300 fios 100% algodão de excelente qualidade. Para colchão com altura até 40cm. A coleção Bud Vision New Colors da Buddemeyer é composta por jogos de cama com bordado ponto ajour. A sofisticação se dá pelo fino acabamento nas peças, cores e brilho dos tecidos. Fronha 3 abas com acabamento em ponto ajour, lençol com elástico para colchão com altura até 40cm, sobrelençol com acabamento em ponto ajour. É produzida em tecido cetim 300 fios 100% algodão de excelente qualidade. Toque acetinado. A Buddemeyer é referência em qualidade e estilo. INSTRUÇÕES DE CUIDADO: Lave antes de usar. Cores escuras devem ser lavadas separadas das cores claras. Lavar em água fria ou em temperatura de até 60°C. O melhor sabão para manter as características do produto é o de coco ou neutro. Não colocar sabão diretamente no produto. Evite alvejantes e quaisquer produtos a base de cloro, eles atacam o corante dos tecidos. Não exagere no uso de sabão em pó e use pouco amaciante. Permite secadora em temperatura baixa. Temperatura máxima da base do ferro 110°C. Não usar ferro a vapor. Não lavar a seco.', 825.98, 825.98, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/sg-11134201-7rfic-m9kt28gdvr8161', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462263068%2F11733774316', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
