INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262797577', 'Camisa do Brasil Feminina Copa do Mundo 2026 Licenciada Original', 'A Camiseta Brasil Feminina Retrô é a escolha perfeita para quem quer demonstrar orgulho pela Seleção com estilo e conforto. Inspirada nas cores que representam a história do futebol brasileiro, a peça combina um visual esportivo com um toque moderno e feminino. Confeccionada em 100% algodão, a camiseta oferece toque macio, excelente respirabilidade e conforto para o uso no dia a dia. Seu tecido leve proporciona um caimento natural que valoriza o visual e garante bem-estar em qualquer ocasião. O destaque fica por conta do escudo do Brasil aplicado em patch no peito, trazendo autenticidade e reforçando a identidade da Seleção. A estampa BRASIL no centro da peça e as estrelas acima do nome simbolizam as conquistas que marcaram a história do futebol brasileiro. A camiseta conta ainda com gola V, que traz um visual mais moderno e feminino, além de detalhes contrastantes em verde na gola e nas mangas, reforçando as cores tradicionais da Seleção. As listras nos ombros completam o design esportivo inspirado no estilo clássico das camisas de futebol. Destaques do produto:', 194.85, 129.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-820lv-mpmm6j2ob66a46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1716040168%2F58262797577', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
