INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17586103807', 'DISCO FLAP 4.1/2X7/8" G60 DEWALT', 'DISTRIBUÍDO POR C-JAÚ FERRAMENTAS DISCO FLAP 4.1/2X7/8" G60 DEWALT Flap Dual Trim combina a alta remoção do grão cerâmico com o acabamento do grão zirconado, proorcionando o melhor custo x benefício. Características Camadas duplas sobrepostas (cerâmica e zircônia) para a máxima eficiência e desempenho. Alta remoção e excelente acabamento. Revestimento especial que reduz a temperatura durante o uso, extendendo a vida útil. Costado plástico usinável. Aplicação Remoção de material. Chanfros e bizel. Remoção e nivelamento de cordão de solda. Rebarbação. Acabamento.', 20.0, 20.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m04widrlv78nd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F17586103807', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23096954660', 'Proteção de Molas para Cama Elástica Trampolim Pula Pula 2,44m Protetor Colorido', 'Proteção de molas para Cama Elástica (2,44M) Imagine um protetor de molas colorido e divertido para cama elástica, feito de material resistente e adornado com bagunzitos. Projetado para segurança, proporciona uma experiência segura e visualmente estimulante em parques, áreas recreativas ou em casa, transformando qualquer espaço em um playground encantador. Atenção: antes de realizar a compra, favor medir o diâmetro total da cama elástica (de ponta a ponta da ferragem, não apenas onde a proteção de molas vai cobrir). Assim saberá a medida correta para comprar. Outra observação; a proteção de molas é feita apenas para garantir a segurança, não recomendamos que a criança pule no produto, pois pode interferir na durabilidade.', 160.0, 160.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98p-lm35kdbjpkomd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438656550%2F23096954660', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597600261', 'Cama Box Colchão Casal King Molas Ensacadas Real 193x203x65cm Branco / Bege Inducol', 'Descubra o extremo conforto da Cama Box Com Colchão Real, projetado para elevar a qualidade do seu sono proporcionando uma experiência única de descanso! Conta molas ensacadas de alta qualidade que trabalham em conjunto proporcionando resistência e aconchego na hora do descanso. Além de possuir revestimento em malha de qualidade que é uma camada extra de conforto proporciona uma experiência de sono inigualável. Seu box revestido em linho apresenta uma estrutura resistente fabricado com matérias de qualidade, invista na qualidade do seu sono e experimente garantia total de descanso e qualidade de vida! MEDIDAS: [ A ] = 65 cm / 53 cm (Sem Pés) [ L ] = 193 cm [ P ] = 203 cm ALTURA DOS PÉS: 12 cm PESO: 111,90kg PESO SUPORTADO: 130kg por Pessoa MODELO: Cama Box Colchão Casal King Molas Ensacadas Real 193x203x65cm MARCA DO COLCHÃO: Inducol MARCA DO BOX: Prince COR DO COLCHÃO: Branco COR DO BOX: Bege REVESTIMENTO SUPERIOR: Tecido em malha branca que permite melhor ventilação, proporcionando conforto e sensação agradável ao toque. REVESTIMENTO INTERIOR: Molejo estrutural em molas ensacadas individualmente, que permitem que o colchão suporte até 130kg por pessoa, oferecendo conforto e estabilidade durante o sono. REVESTIMENTO INFERIOR: Tecido antiderrapante ESPUMA: Camada superior D65 TIPO DE MOLA: Molas Ensacadas ANTI ALÉRGICO / ÁCARO: Sim POSSUI EPS: Sim TECIDO DO BOX: Suede QUANTIDADE DE PÉS: 9 MATERIAL DOS PÉS: Plástico OBSERVAÇÃO: Box desmontável GARANTIA DO COLCHÃO: 12 Meses pelo Fabricante GARANTIA DO BOX: 3 Meses pelo Fabricante A Esplanada Móveis se responsabiliza pela entrega dos produtos adquiridos até a porta de entrada ou portaria do endereço indicado, se a portaria do condomínio permitir, as entregas são efetuadas no piso térreo e é de responsabilidade do cliente a locomoção da mercadoria até seu apartamento ou casa. Confira as dimensões do produto e certifique-se de que estão adequadas aos elevadores, portas e corredores do local da entrega. Não fazemos a montagem, desmontagem do produto e/ou portas e janelas, transporte pela escada ou içamento pelo lado de fora do prédio. Não está incluso no serviço de entrega o deslocamento até o interior do apartamento, com ou sem elevador, ou deslocamento em locais de difícil acesso como escadarias. Caso o cliente necessite de entrega dentro das dificuldades mencionadas, deverá entrar em contato para análise e cotação do valor do serviço. Certifique-se de tudo antes de finalizar a compra, evitando assim futuros desagrados ou imprevistos com a entrega.', 1999.0, 1999.0, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-821dy-mgs4yrha2aks3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097902002%2F23597600261', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
