INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209721053', 'Cerveja Eisenbahn Pilsen Lata 350ml', 'A Eisenbahn Pilsen Lata 350ml é uma cerveja puro malte leve e com amargor na medida certa, ideal para ser apreciada bem gelada. De baixa fermentação e com teor alcoólico de 4,84%, a Eisenbahn Pilsen é o rótulo mais vendido da marca no Brasil. A cerveja possui cor dourada, aromas de malte e lúpulo e oferece um equilíbrio excelente entre o amargor e o doce. Harmonize a sua Eisenbahn Pilsen com frutos do mar, peixes e queijos. Fundada em Blumenau, a Eisenbahn é uma cerveja brasileira que tem alma alemã. Todas as cervejas produzidas pela fábrica seguem à risca a Lei Alemã da Pureza.', 4.79, 4.79, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-825af-mqnekq7607ibb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554977%2F58209721053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
