INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258500267', 'Vestido Infantil Feminino Lilica Ripilica', 'Vestido em Interlock com Elastano Lilica Ripilica – Conforto e charme em cada detalhe Este vestido encantador é confeccionado em interlock com elastano, garantindo toque macio e ajuste confortável para acompanhar todos os movimentos com leveza. Sua estampa digital exclusiva imprime modernidade e delicadeza, enquanto o recorte na parte frontal proporciona um charme extra, criando a sensação de uma saia soltinha a partir da cintura. O fecho em gota nas costas, além de funcional, adiciona um detalhe sofisticado e facilita na hora de vestir. A modelagem fluida valoriza a silhueta e oferece liberdade para brincar e se divertir com estilo. Sugestão de uso: Perfeito para ocasiões especiais, como festinhas, almoços em família ou passeios no parque. Combine com sandálias ou tênis para um visual despojado e cheio de personalidade.', 229.0, 137.4, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-81zwc-mmudffrefshw33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F58258500267', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
