INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098168034', 'Tomada de Telefone RJ11 para 2 Fios Ilumi', 'A Tomada de Telefone RJ11 Ilumi é uma solução prática e confiável para conectar seu telefone fixo à rede. Esta tomada é projetada para oferecer alta durabilidade e funcionalidade superior. O design é simples, permitindo uma instalação rápida e sem complicações em qualquer ambiente residencial ou profissional. Com um acabamento discreto, ela se integra facilmente a qualquer decoração, mantendo o ambiente organizado e elegante. Além disso, a qualidade dos materiais utilizados assegura uma longa vida útil, garantindo que você faça um investimento seguro para suas necessidades de comunicação. Benefícios do produto e características: A tomada de telefone RJ11 Ilumi se destaca por sua facilidade de uso e pela confiabilidade que oferece. Com três meses de garantia, os usuários têm a tranquilidade de saber que estão protegidos contra eventuais defeitos de fabricação. Especificações técnicas: Marca: Ilumi Tipo de Produto: Tomada de Telefone RJ11 Conexão: 2 Fios Design: Discreto e funcional Conteúdo da embalagem: - 1 Tomada de Telefone RJ11 Garantia: - 3 meses pelo fabricante.', 38.9, 38.9, NULL, 'Home Appliances > Small Household Appliances > Telephones', 'https://cf.shopee.com.br/file/sg-11134201-7rd6x-m6qsub4gv7vf9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F22098168034', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
