INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259424385', 'Kit 2 Baterias Pilhas Recarregáveis 9V Elgin 250mAh para Microfone sem Fio Detector e Multímetro', 'A Bateria Recarregável 9V Elgin 250mAh oferece energia estável, longa duração e excelente economia para diversos aparelhos eletrônicos. Com capacidade para até 1.000 recargas, é ideal para microfones sem fio, detectores de fumaça, multímetros, brinquedos, instrumentos de medição e outros dispositivos compatíveis com bateria 9V. Desenvolvida com alto padrão de qualidade, proporciona desempenho confiável e reduz o impacto ambiental em comparação às baterias descartáveis. Diferenciais • Capacidade para até 1.000 recargas. • Maior economia em comparação às baterias descartáveis. • Energia estável e confiável para diversos equipamentos eletrônicos. • Ideal para microfones sem fio, detectores de fumaça, multímetros, brinquedos e instrumentos de medição. • Produto testado por laboratórios credenciados pelo INMETRO. • Atende à Resolução CONAMA 401. • Solução sustentável e de longa vida útil. Detalhes Técnicos Marca: Elgin Tipo: Bateria recarregável Tensão: 9V Capacidade: 250mAh Quantidade: 1 bateria Embalagem: Blister com 1 unidade Ciclos de recarga: Até 1.000 recargas Certificação: Testada por laboratórios credenciados pelo INMETRO Norma ambiental: Conforme Resolução CONAMA 401 Conteúdo da Embalagem - 1 Bateria Recarregável 9V Elgin 250mAh (Blister com 1 unidade)', 100.0, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Battery Tools', 'https://cf.shopee.com.br/file/sg-11134201-820nt-mnepku631yisf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F58259424385', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
