INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13253664107', 'Ração Úmida Pedigree Sachê Cães Adultos Raças Pequenas Cordeiro ao Molho 100g', '- Alimento 100% completo & balanceado - Contém Vitamina E que ajuda a manter uma vida saudável - Sem conservantes, corantes & aromas artificiais - Balanço ideal de fibras - Com vitaminas e minerais Nós de PEDIGREE® acreditamos que todos os cães merecem um lar amoroso. Eles alimentam o que há de melhor nas pessoas e PEDIGREE® alimenta o que há de melhor neles, por isso trabalhamos duro para dar a cada um deles uma nutrição completa, equilibrada e de qualidade. ​Assim, o delicioso sachê PEDIGREE® é uma excelente forma de você demonstrar amor pelo seu cão todos os dias, oferecendo-o uma refeição saborosa e de qualidade. ​É um alimento 100% completo e balanceado, feito com Vitamina E que ajuda o sistema imune e contém ingredientes de alta qualidade para manter o seu cão feliz e saudável. Também não contém conservantes, sabores e aromas artificias. INGREDIENTES Miúdo de ovino, carcaça de frango, miúdo de suíno, farinha de trigo, glúten de trigo, plasma suíno em pó, fibra de cana-de-açúcar, água, amido de milho, tripolifosfato de sódio, goma xantana, corante natural caramelo. Eventuais substitutivos: Carne mecanicamente separada de frango, miúdo de ave, vísceras de frango, gordura de frango, pé de frango, cabeça de frango, miúdo de bovino, baço de bovino, baço suíno, polpa de beterraba, proteína concentrada de soja. D3, E, C, B1, B2, B6, niacina, ácido pantotênico, ácido fólico, cloreto de colina, biotina Cloreto de sódio – sal comum, cloreto de potássio, fosfato bicálcico, óxido de manganês, iodato de cálcio, óxido de zinco, óxido de magnésio', 5.25, 4.2, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/br-11134201-23010-e1p5zj1bafmv96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F13253664107', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
