INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29943923878', 'Arame Galvanizado 22 BWG 0,71 mm – VONDER', 'Arame Galvanizado 22 BWG 0,71 mm – VONDER Arame galvanizado com camada de zinco leve, ideal para aplicações gerais na construção civil, agropecuária e indústrias. Proporciona maior resistência à oxidação e à corrosão, garantindo durabilidade e confiabilidade no uso. Não indicado para aplicação em gesso. Itens Inclusos 1 Rolo de arame galvanizado (~1 kg, aproximadamente 325,7 m) Especificações Técnicas Diâmetro: 22 BWG – 0,71 mm Tipo: Comercial Material: Aço com baixo teor de carbono (macio) Acabamento: Camada de zinco leve Comprimento aproximado: 325,7 m por kg Peso aproximado: 1 kg Por que escolher este produto? Produto novo e original Pronta entrega e envio em até 24 horas Compra 100% segura', 34.99, 34.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zwl-mj05ey3c9qtg4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F29943923878', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
