INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897341449', 'Pneu Aro 18 Bridgestone 235/55 R18 100V Alenza 001', 'Pneu Aro 18 Bridgestone 235/55 R18 100V Alenza 001 Sobre o pneu Desenvolvido pela BRIDGESTONE para o segmento de SUVs Premium, o novo pneu ALENZA 001 foi projetado com tecnologias que permitem uma performance superior nas mais diferentes condições. O novo ALENZA 001 assegura que o veículo tenha uma ótima precisão na direção e contato firme com o solo nas mais difíceis situações, sem abrir mão do conforto ao dirigir, da economia de combustível e ainda proporciona redução de ruído para uma rodagem perfeita. Informações Adicionais: - Marca: BRIDGESTONE - Modelo: ALENZA 001 - Medida: 235/55R18 - Largura: 235mm - Perfil: 55% - Aro: 18 - Índice de peso: 100 - 800 kg - Índice de velocidade: V - 240 km/h - RFT = RunFlat: NÃO - Tipo de construção: RADIAL - Extra Load: NÃO - Protetor de bordas: NÃO - Sidewall: BSW LETRAS PRETAS - Tipo de terreno: HT - Desenho: Assimétrico - Garantia: 5 anos Contra Defeito de Fabricação Aplicação: - JEEP: COMMANDER - KIA: SPORTAGE, SPORTAGE II, SPORTAGE IV - VOLKSWAGEN: TIGUAN, TIGUAN II - VOLVO: XC40 - MERCEDES BENZ: CLASSE GLB - LEXUS: NX200T, NX300, NX300H - AUDI: Q3 II, Q5 - TOYOTA: RAV4, RAV4 II - CHEVROLET: CAPTIVA, CAPTIVA II “POR FAVOR, VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU PNEU”', 1383.64, 1383.64, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rcec-lrt58xloitjl70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F22897341449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
