INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23412894064', 'Caixa Organizadora de Seagrass 30cm - Oikos', 'Essa é a caixa organizadora de seagrass 30cm branco com fecho da OIKOS. Prática: boa para organizar toalhas, roupas, brinquedos, livros, jogos, pastas, produtos de limpeza e muito mais. Versátil: vai bem em qualquer ambiente da casa: no quarto do casal ou do bebê, no banheiro, na lavanderia, na sala ou na cozinha. você que manda! Empilhável: além de ser charmosa, seu corpo permite empilhar uma caixa em cima da outra, otimizando os espaços e deixando tudo bem organizado. Decorativa: esse item é charmoso e neutro, ele harmoniza com diversos estilos de decoração, deixando sua casa mais aconchegante e cheia de bossa. Funcional: essa caixa permite deixar tudo em ordem na casa, sem falar que otimiza os espaços e ainda deixa cada cantinho mais convidativo. Detalhes: seu fecho é de metal, deixando o interior protegido e dando uma aparência mais moderna à peça. o trançado de seagrass tingido de branco chama tanta atenção nesse item, que ele pode ser utilizado somente como peça decorativa :). Feita de seagrass: seu material é uma tendência no mundo da decoração, atributos não faltam: ele é ecológico, 100% natural, trançado, leve, firme e biodegradável. legal, né? Durável e higiênica: só precisa lavar e secar de acordo com as recomendações, combinado? Feita em três medidas: essa caixinha tem 30cm de comprimento, 20cm de altura e 12cm de largura. ainda contamos com outros tamanhos no nosso sortimento: 27cm e 24cm de comprimento. ah, vários tamanhos combinados podem deixar a casa ainda mais bonita, fica a dica :)', 225.9, 152.9, NULL, 'Home & Living > Bathrooms > Toothbrush Holders & Toothpaste Dispensers', 'https://cf.shopee.com.br/file/sg-11134201-8262u-mlfcl3nnu0awce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fsho