INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993531965', '100% Whey protein Refil 900g - FTW', '100% Whey Protein FTW é um suplemento alimentar em pó à base de proteína concentrada do soro do leite (WPC), reconhecida por seu alto valor biológico e excelente perfil de aminoácidos essenciais. Ingredientes Proteína concentrada do soro do leite (WPC), espessantes (goma xantana e goma guar), edulcorantes (sucralose e acessulfame de potássio), aromatizantes idênticos aos naturais (variam de acordo com o sabor). NÃO CONTÉM GLÚTEN. CONTÉM LACTOSE. ALÉRGICOS: Contém derivados de leite e soja. Podem conter derivados de crustáceos, peixe, ovo, cevada, trigo e amendoim. Apresentação - Refil com 900g - Porção: 30g (1 ½ medida dosadora) - Rendimento: Cerca de 30 porções. Como Consumir Diluir 1 ½ medida dosadora (30g) em 200ml de água ou bebida de sua preferência. Misturar com coqueteleira, liquidificador ou manualmente até completa dissolução. Informações Adicionais - Produto indicado para adultos maiores de 19 anos; - Este produto não deve ser consumido por gestantes, lactantes ou crianças; - Mantenha fora do alcance de crianças; - Não exceder a recomendação diária de consumo indicada na embalagem; - Conservar em local seco e fresco, ao abrigo da luz e umidade; - Após aberto consumir em até 60 dias; - Este produto não é um medicamento. Certificação Suplemento alimentar dispensado de registro conforme Resolução RDC nº 240/2018. Alegações baseadas no Anexo V da IN 28 Anvisa.', 189.9, 157.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi9nfazk7x8h46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1397772996%2F22993531965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
