INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255460408', 'Eudora Club 6 Intenso Desodorante Antitranspirante 125ml/75g', 'O Desodorante Antitranspirante Club 6 Intenso dispõe de uma proteção perfumada com dupla proteção, este desodorante antitranspirante atua na desodorização e perfumação do seu corpo. Com 48 horas de proteção contra mau odor e transpiração, este produto garante mais segurança e autoconfiante para a sua rotina. Além disso, apresenta mais vantagens: -Não contém CFC, sendo inofensivo à camada de ozônio. -Possui cápsulas ativas de fragrância com liberação prolongada. Por meio dessa liberação prolongada, você possui mais tempo de proteção e perfumação para viver sua vida com mais intensidade. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 38.9, 38.9, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-82605-mkwqp3piv9j8b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58255460408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259710841', 'Papel Toalha Scala Plus Mega 360 Folhas', 'O Papel Toalha Scala Plus Mega 360 Folhas foi desenvolvido para oferecer mais rendimento, resistência e praticidade no dia a dia. O pacote contém alta absorção, ideal para auxiliar nas tarefas domésticas com eficiência. Produzido com folhas resistentes e macias, o Scala Plus Mega é indicado para uso na cozinha, limpeza de superfícies, secagem de alimentos, absorção de líquidos e apoio na rotina da casa. Sua tecnologia proporciona maior poder de absorção, ajudando a reduzir o desperdício e garantindo melhor custo-benefício. O formato “Mega” entrega mais quantidade por embalagem, sendo ideal para quem busca economia sem abrir mão da qualidade. Prático e versátil, é um item essencial para manter a higiene e organização do ambiente com rapidez e eficiência.', 23.49, 15.9, NULL, 'Home & Living > Home Care Supplies > Tissue & Paper Towels', 'https://cf.shopee.com.br/file/sg-11134201-8259k-mqnekl8pnp4y1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554886%2F58259710841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
