INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208923328', 'Par Lâmpada Led Pinguinho B8,5d-t5-cob 12v 6000k Com Soquete', 'APLICAÇÃO: CARACTERÍSTICAS: COMPACTA MODERNA BAIXO CONSUMO ALTA DURABILIDADE ILUMINAÇÃO BRANCA FRIA FÁCIL INSTALAÇÃO APLICAÇÃO: PAINEL DE CARRO FICHA TÉCNICA: COR: BRANCA FRIA TEMPERATURA DE COR: 6000K ENCAIXE: B8,5D-T5 COM SOQUETE TENSÃO: 12V EQUIVALÊNCIA: 3W TIPO DE LED: COB REFERÊNCIA: TP-5039 FAVOR CONSULTAR O VENDEDOR SE REALMENTE É COMPATÍVEL COM SEU VEÍCULO! • VALOR REFERENTE AO PAR • PRODUTO NOVO E ORIGINAL • ENVIO DO PEDIDO COM NOTA FISCAL • COM GARANTIA DE FÁBRICA • ANTES DE EFETUAR O PEDIDO, FAVOR TIRAR AS DÚVIDAS NO CAMPO DE PERGUNTAS CUIDAR DO SEU CARRO DE MANEIRA PREVENTIVA GERA ECONOMIA E, ACIMA DE TUDO, GARANTE SUA SEGURANÇA PARA DIRIGIR TRANQUILO. A NOVA VIA TRABALHA PARA OFERECER O MELHOR EM AUTOPEÇAS, COM UM ESTOQUE DE MAIS DE VINTE MIL ITENS, PARA QUE VOCÊ ENCONTRE SEMPRE O QUE PRECISAR. DISTRIBUÍMOS AUTOPEÇAS DAS MAIORES E MELHORES MARCAS DO MERCADO, COM UM ATENDIMENTO QUALIFICADO DE PROFISSIONAIS QUE ATUAM HÁ MAIS DE VINTE ANOS NO SEGMENTO. NOVA VIA AUTOPEÇAS: SEMPRE O MELHOR PARA SEU CARRO!', 19.37, 18.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-81zvh-mn3b0628622o99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F714090968%2F58208923328', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494280638', 'Kit Teclado Semi Mecânico + Mouse Gamer 3200dpi Rgb Led M300 LED-H8', '🔥 KIT GAMER ESSENCIAL - TECLADO SEMI-MECÂNICO RGB + MOUSE COM LED 🔥 🎮 PARA GAMERS QUE EXIGEM ESTILO E PERFORMANCE! 🌟 TECLADO GAMER SEMI-MECÂNICO RGB RAINBOW ✔ Iluminação RGB Dinâmica - Efeito rainbow vibrante que transforma seu setup ✔ Teclas Semi-Mecânicas - Resposta rápida e toque suave para jogos precisos ✔ Design Ergonômico - Conforto garantido mesmo em maratonas de jogatina ✔ Cabo USB Resistente - 1,35m de comprimento para maior liberdade de movimento ✔ Controles Multimídia - Teclas dedicadas para volume/play/pause ✔ Visual Agressivo - Preto moderno que combina com qualquer estilo gamer 🖱️ MOUSE GAMER COM LED AJUSTÁVEL ✔ Plug & Play - Basta conectar e jogar! (sem necessidade de driver) ✔ Luzes LED Personalizáveis - Combine com as cores do seu teclado ✔ Precisão Otimizada - Ideal para FPS, MOBA e jogos casuais 📦 O QUE VOCÊ RECEBE: ✅ 1 Teclado Gamer Semi-Mecânico RGB ✅ 1 Mouse Gamer com LED ✅ Produto 100% novo e lacrado ⚙️ ESPECIFICAÇÕES: ▸ Tipo de teclas: Híbrido semi-mecânico (membrana aprimorada) ▸ DPI do mouse: Ajustável até 3200 ▸ Garantia: 3 meses contra defeitos de fabricação 💡 POR QUE ESCOLHER NOSSO KIT? 👉 Custo-benefício perfeito para iniciantes e intermediários 👉 Iluminação profissional que impressiona 👉 Durabilidade comprovada em testes rigorosos ⚠️ ATENÇÃO: • Produto vendido como kit (não inclui outros itens) • Frete calculado conforme região 🎁 PRONTO PARA ELEVAR SEUS GAMES? Garanta já o seu enquanto tem estoque! ⏳ #kit teclado e mouse gamer #mouse teclado', 100.0, 63.99, NULL, 'Computers & Accessories > Keyboards & Mice > Keyboards', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcx4tdl62fcia4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1386771889%2F23494280638', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211344897', 'Kit com 2 Máscaras de Hidratação SOS Hidratação + Gelatina #todecacho Super Definição Salon Line', 'O Kit conta com Gelatina #todecacho Super Definição que proporciona uma definição intensa, Máscara S.O.S Hidratação Bio-Reconstrução Fortalecedora que proporciona uma reposição e proteínas capilares e a Máscara S.O.S Hidratação Turbinada com ativos para proporcionar uma hidratação power. <>INDICAÇÕES$& Para quais tipos de cabelo? Para todos os tipos de cabelos. Qual a indicação? Cabelos sem definição, com frizz, danificados, ressecados e sem brilho. Pode usar a partir de quantos anos? A Gelatina #todecacho Super Definição a partir de 03 anos, já a Máscara S.O.S Hidratação Tirbinada e Máscara Recostrutora S.O.S. Bio-Reconstrução Fortalecedora a partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Gelatina #todecacho Super Definição Salon Line A Gelatina para cabelo ondulado, cacheado e crespo possui babosa e D-pantenol em sua fórmula que garantem hidratação, maciez e brilho. Além disso, aliados à tecnologia PROFIX, proporcionam definição intensa, combate ao frizz e fixação duradoura. Máscara S.O.S Hidratação Bio-Reconstrução Fortalecedora Salon Line Proteína do ovo: rico em proteína, vitaminas e minerais, o ovo fortalece e mantém os fios saudáveis, macios e brilhosos. Queratina: proteína fibrosa, ajudar a devolver a resistência e a elasticidade dos cabelos. Colágeno: proteína que ajuda na reposição proteica e na saúde dos fios. Máscara S.O.S Hidratação Turbinada Salon Line Manteiga de karité: hidrata e nutre profundamente o cabelo. Óleo de rícino: tem ação intensiva nas fibras capilares, fortalecendo e nutrindo os fios danificados. Azeite de oliva: poderoso antioxidante, garante o força e hidratação intensa. <>MODO DE USO$& Qual a melhor forma de usar? Gelatina #todecacho Super Definição Salon Line Com os cabelos limpos e úmidos, aplique a Gelatina de Cabelo mecha a mecha, uniformemente, no comprimento e pontas. Desembarace os fios com um pente de dentes largos e, em seguida, amasse-os iniciando o movimento das pontas até a raiz. Repita o movimento quantas vezes forem necessárias. A aplicação ideal dependerá da quantidade e do comprimento dos fios. Não enxágue. Máscara S.O.S Hidratação Bio-Reconstrução Fortalecedora Salon Line Após lavar os cabelos, retire o excesso de água e aplique a Máscara S.O.S Hidratação Bio-Reconstrução Fortalecedora do comprimento até as pontas. Aguarde 3 minutos e enxágue. Finalize como desejar. Máscara S.O.S Hidratação Turbinada Salon Line Após lavar os cabelos, retire o excesso de água e aplique a Máscara S.O.S Hidratação Turbinada do comprimento até as pontas. Aguarde 3 minutos e enxágue. Finalize como desejar. <>CARACTERÍSTICAS$& É produto vegano? A Máscara S.O.S Hidratação Turbinada e a Gelatina #todecacho são Veganos. É liberado? Apenas a Gelatina #todecacho Super Definição é liberada.', 84.0, 57.95, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/br-11134207-820li-mooapc79upza9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F58211344897', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298849464', 'Sandália Campesí de Salto Bloco Feminina CE142', 'Produto marca Campesí. Eleve seu estilo com a Sandália Campesí de Salto Bloco, a peça-chave para quem busca elegância e conforto em um só produto. Feita em material sintético de alta qualidade, ela é a escolha ideal para mulheres que prezam por um calçado leve e versátil. o design minimalista e o recorte elegante que valoriza os pés fazem dela um item indispensável, perfeito para compor looks sofisticados para o dia a dia ou ocasiões de lazer. a tira fina com fechamento em fivela não só adiciona um toque de charme, mas também garante o ajuste perfeito. Caminhe com confiança e conquiste o mundo com a Sandália Campesí de Salto Bloco. o salto de 5,50 cm oferece a altura ideal para alongar a silhueta, sem abrir mão do conforto e da estabilidade proporcionados pelo seu formato robusto. É a união perfeita entre tendência e praticidade, permitindo que você transite do escritório a um happy hour com a mesma elegância. Desfrute de cada passo com a certeza de estar usando um calçado que reflete seu bom gosto e sua busca por uma vida mais prática e estilosa. Compre agora e transforme seus looks com a Sandália Campesí de Salto Bloco. Esteja pronta para se destacar com um produto que não só segue as tendências da moda, mas também oferece o bem-estar que você merece. a versatilidade e o design atemporal garantem que este seja um investimento inteligente para o seu guarda-roupa. Peso: 0,576 kg Altura do salto: 5,5 cm', 199.9, 189.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-7rdvf-mdnmfpr8r73813', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F22298849464', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497551806', 'Sandália Dakota Rasteira Metalizado', 'Produto marca Dakota. A Sandália Dakota Rasteira é traz brilho e conforto para o dia a dia. Com design moderno e elegante, ela conta com calce fácil e prático, pois não possui fechamentos, apenas uma tira elástica que envolve o calcanhar. O destaque do modelo fica por conta das tiras tramadas e repletas de brilho sobre o pé, que garantem um visual sofisticado e cheio de estilo. Além disso, ela é perfeita para compor looks casuais e elegantes. Combine-a com um vestido de verão e um chapéu de palha para um look casual e estiloso. Para um visual mais elegante, use a sandália com um calça de alfaiataria e uma blusa de seda. Peso: 0,436 kg Altura do salto: 1,0 cm', 149.9, 69.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-82613-mlwg4tzna96o46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23497551806', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49209391629', 'Kit Finalização Creme para Pentear, Gelatina e Óleo Booster Cachos Ostentação', 'O kit contém 1 Creme para Pentear Cachos Ostentação 1kg, 1 Gelatina #todecacho Definição Cachos Ostentação 550g e 1 Óleo Booster Cachos Ostentação 120ml. O Kit Finalização Creme para Pentear, Gelatina e Óleo Booster Cachos Ostentação garante uma rotina de finalização luxuosa, entregando nutrição máxima, definição impecável, fixação prolongada, controle absoluto do frizz e aquele brilho espelhado de salão. <>INDICAÇÕES$& Para quais tipos de cabelo? Indicado para cabelos ondulados, cacheados e crespos. Qual a indicação? Para cabelos ressecados, opacos, sem definição e que buscam uma finalização duradoura com selagem absoluta das pontas. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Creme para Pentear e Óleo Booster Cachos Ostentação Enriquecidos com extrato de frutas vermelhas, óleo de argan e óleo de semente de uva, ativos que evitam a perda de água natural dos fios, garantem nutrição profunda, selagem das cutículas, proteção das pontas e um brilho espelhado radiante. Gelatina Definição Cachos Ostentação Conta com o mesmo blend nutritivo de frutas vermelhas, óleo de argan e semente de uva, aliado à tecnologia PROFIX, que garante 72h de formatação, fixação e durabilidade dos cachos, sem ressecar. <>MODO DE USO$& Qual a melhor forma de usar? Creme para Pentear e Gelatina Com os cabelos limpos e úmidos, aplique o Creme para Pentear e/ou a Gelatina mecha a mecha, uniformemente, no comprimento e pontas. Desembarace os fios com um pente de dentes largos e, em seguida, amasse-os iniciando o movimento das pontas até a raiz. Você pode usá-los sozinhos ou fazer uma misturinha para potencializar a definição e a fixação. Não enxágue. Óleo Booster Com o cabelo seco ou úmido, aplique algumas gotas na palma das mãos e espalhe bem do comprimento às pontas. Pode ser usado misturado ao creme ou à gelatina na hora da finalização para potencializar a nutrição, ou aplicado sozinho nos fios secos para selar as cutículas e quebrar o durinho deixado pelos finalizadores. Sem enxágue. <>CARACTERÍSTICAS$& É produto vegano? O Kit Finalização Creme para Pentear, Gelatina e Óleo Booster Cachos Ostentação não é totalmente vegano (o Creme para Pentear e a Gelatina são veganos, porém o Óleo Booster não é). É liberado? O Kit Finalização Creme para Pentear, Gelatina e Óleo Booster Cachos Ostentação não é totalmente liberado (o Creme para Pentear e a Gelatina são liberados, porém o Óleo Booster não é).', 112.0, 112.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-820no-mneb8c6g7jsx0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F49209391629', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253220211', 'Elastic Clay Bar Universal Descontaminação 100g Kers', 'Elastic Clay Bar Universal Descontaminação 100g Kers Clay Bar é um produto desenvolvido para remover pulverizações de tinta e resíduos de sujeira que não saem com uma limpeza comum sobre a pintura. Pode ser aplicada sobre pintura, vidros e plásticos e cromados. Não deixa resíduos e nem danifica o verniz, plásticos ou borrachas. Modo de uso// 1 – Garanta que a superfície esteja completamente limpa 2 – Verifique onde estão as contaminações usando o toque, veja se a superfície está áspera 3 – Misture sabão neutro e água em um pulverizador, aplicando a solução sobre a área que você quer descontaminar 4 – Passe a ClayBar sobre a região, pressionando levemente. A solução aplicada anteriormente servirá de lubrificante. 5 – Caso necessário, faça a repetição do processo até a contaminação ser completamente removida. 6 – Descarte as partes contaminadas da Claybar. 7 – O que sobrar, guarde na embalagem para evitar possíveis contaminações indesejadas.', 47.19, 47.19, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-825zv-mjg0c0g1fmdi47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F58253220211', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599250865', 'Moto de Brinquedo Ultra Cross Kendy', 'A diversão estará garantida com a Moto de Brinquedo Ultra Cross Kendy, que vai arrasar nas pistas e levar a diversão para outro nível! Prepare-se para uma experiência incrível. A moto de brinquedo infantil possui um design arrojado e realista para que as crianças se sintam verdadeiros pilotos profissionais, prontos para enfrentar qualquer desafio!Ela conta com um pezinho de descanso e os pequenos podem estacioná-la em qualquer lugar, aumentando ainda mais a diversão. É uma maneira fantástica de incentivar a imaginação e a criatividade dos pequenos. Além disso, é uma excelente aliada no desenvolvimento da coordenação motora das crianças. É uma forma divertida e estimulante de ajudar no crescimento e no desenvolvimento dos pequenos aventureiros.A Moto de Brinquedo Ultra Cross Kendy é fabricada com materiais de alta qualidade para acompanhar as aventuras das crianças. Sua estrutura resistente e design ergonômico oferecem estabilidade durante as brincadeiras, permitindo que as crianças se divirtam com segurança. Adquira agora mesmo a e proporcione às crianças uma experiência única e emocionante. Deixe que elas soltem a imaginação, desenvolvam suas habilidades motoras e se divirtam ao máximo.', 24.99, 22.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-825ae-mq57187c4kcs8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F20599250865', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18597765329', 'Pincel Trincha Para Pintura Gris 302 1 Polegada Roma', 'Pincel Trincha Para Pintura Gris 1 Polegada Roma O Pincel Trincha Roma cerdas médias foi desenvolvido para facilitar a execução de pinturas com tintas látex e acrílica. Cada produto foi detalhadamente desenhado com base aos critérios identificados pelas necessidades dos usuários. Tudo isso com o objetivo de oferecer um produto adequado as necessidades do mercado. Características do Produto: Marca: Roma; Ideal para todos os tipos de trabalhos, pincel de alta qualidade e excelente construção do produto; Trincha macia e suave com cerdas gris selecionadas; Indicada para tintas látex e acrílica; Cerda/Filamento: Natural Gris Selecionadas; Fabricada pelo sistema monobloco.', 13.69, 13.69, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Polisher', 'https://cf.shopee.com.br/file/sg-11134201-7rdwr-lygf2tb5eqrr50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F18597765329', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794949446', 'Coca-Cola Sem Açúcar Refrigerante', 'Desfrute do sabor autêntico e refrescante da Coca-Cola sem adição de açúcar. Perfeita para acompanhar suas refeições, churrascos ou momentos de lazer, sem abrir mão de um estilo de vida equilibrado. A Coca-Cola Sem Açúcar é ideal para compartilhar com amigos e familiares em qualquer ocasião. Refresque-se com o sabor clássico e zero açúcar!', 7.49, 7.49, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-82581-mr0bybldxyx8b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554761%2F23794949446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
