INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593872948', 'Bota Infantil Coturno Gracinha 812', 'A Bota Infantil Feminina Coturno Gracinha 812 é a escolha perfeita para deixar as pequenas fashionistas ainda mais estilosas e confortáveis. Com um design moderno e cheio de personalidade, ela é produzida com materiais de alta qualidade e resistência, garantindo durabilidade e segurança para as crianças. Ideal para qualquer ocasião, a bota possui um acabamento delicado e cheio de charme, deixando os looks das meninas ainda mais encantadores. Além disso, ela é super fácil de calçar e proporciona todo o suporte necessário para os pezinhos em crescimento. Invista nessa tendência e dê um toque de moda ao visual das pequenas com a Bota Infantil Feminina Coturno Gracinha 812.. MODELO: 6470812 REFERENCIA: 812 MARCA: Gracinha MATERIAL DA PALMILHA: Macia MATERIAL DA SOLA: Borracha MATERIAL INTERNO: Têxtil ACABAMENTO: Colado/Costurado DETALHES: Salto com 2,5 aproximadamente GÊNERO: Female GRUPO DE IDADE: Infant MEDIDA DO CANO: 12 cm aproximadamente CIRCUNFERÊNCIA DO CANO: 28 cm aproximadamente MATERIAL DO SAPATO: Verniz', 118.99, 118.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Boots', 'https://cf.shopee.com.br/file/sg-11134201-7repa-m82fn3z5lrr4c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F22593872948', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17875501977', 'Kit 2 Repelente Exposis Extreme Spray Sem Perfume 100ml', 'Kit 2 Repelente Exposis Extreme Spray Sem Perfume 100ml Exposis Extrême é um repelente de alta eficácia contra picadas de insetos para adultos e crianças a partir de 2 anos de idade. Proporciona até 10 horas de proteção para toda a família. * Kit Contém: 2 Repelente Exposis Extreme Spray Sem Perfume 100ml cada * Compre Produtos Exposis', 158.86, 158.86, NULL, 'Home & Living > Home Care Supplies > Others', 'https://cf.shopee.com.br/file/sg-11134201-7qveb-lh6bleioy2ck50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F17875501977', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497644861', 'Fralda Pampers Premium Care XXXG com 52un', 'O que é a Fralda Pampers Premium Care Pampers Premium Care é ideal para que a pele do seu bebê fique sempre como pele de bebê, oferecendo máxima absorção de Pampers e uma exclusiva loção hipoalergênica, a Pampers Premium Care ajuda a prevenir assaduras. Além disso, é suave como o algodão e ultra respirável. Não contém fibras de algodão Assim como os demais tamanhos, o XXXG, indicado para bebês com +19kg, é ultra respirável e ajuda a manter a pele do bebê sempre sequinha e fresca por até 12 horas. Para que serve a Fralda Pampers Premium Care Hipoalergênico? A fralda Pampers Premium Care pode ser usada durante o dia ou à noite. Visando à mobilidade, o modelo permite que o bebê se movimente sem desconforto, tanto durante o sono quanto durante as atividades do dia a dia. Composta por uma proteção macia e suave como algodão, seu formato possui canais de ar que permitem a respiração da pele, mantendo-a sequinha e arejada. Seu interior contém loção hipoalergênica exclusiva que previne alergias e irritações, além de contar com a tecnologia Algodão-Sec, que absorve e retém a umidade no interior da fralda, mantendo-a sequinha por até 12 horas e protegendo o bebê contra assaduras. Como usar a Fralda Pampers Premium Care Coloque o bebê sobre a fralda, desgrude as fitas e puxe-as. Grude as fitas sobre a faixa decorada. Benefícios e diferenciais Máxima absorção de Pampers. Loção hipoalergênica. Ultra respirável. Suave como algodão. Ajuste cômodo e flexível: esticam e se ajustam aos movimentos do seu bebê. Barreiras anti-derrames. Novos desenhos para o dia e para a noite. Composição Celulose, Polímero Superabsorvente, Polietileno, Polipropileno, Poliéster, Adesivos, Elásticos, Fragrância, Petrolato, Álcool Estearílico e Extrato de Aloe Barbadensis. Advertências Mantenha fora do alcance das crianças e animais. Se houver irritação, suspenda o uso imediatamente e procure orientação médica. Descarte após usar. Não jogue no vaso sanitário. Não deixe por muito tempo a fralda na criança, pois pode gerar assaduras.', 178.89, 163.16, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-7rccq-lsx0i9bdovzfa3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F18497644861', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
